// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {ERC2771Context} from "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import {Context} from "@openzeppelin/contracts/utils/Context.sol";
import {EasyAccessControl} from "./EasyAccessControl.sol";
import {IAccessControl} from "./interfaces/IAccessControl.sol";
import "./AccessControlErrors.sol";


/**
 * @title AccessControl (external)
 * @notice Standalone access control with bitmask roles. Intended to be shared by multiple contracts.
 */
contract AccessControl is
    IAccessControl,
    EasyAccessControl,
    ERC2771Context
{
    constructor(
        address contractAdmin_,
        address reserveAdmin_,
        address transferAdmin_,
        address trustedForwarder_
    )
        EasyAccessControl(contractAdmin_)
        ERC2771Context(trustedForwarder_)
        validAddress(reserveAdmin_)
        validAddress(transferAdmin_)
        validAddress(trustedForwarder_)
    {
        _grantRole(reserveAdmin_, RESERVE_ADMIN_ROLE);
        _grantRole(transferAdmin_, TRANSFER_ADMIN_ROLE);
    }

    function _msgSender()
        internal
        view
        override(Context, ERC2771Context)
        returns (address sender)
    {
        return ERC2771Context._msgSender();
    }

    function _msgData()
        internal
        view
        override(Context, ERC2771Context)
        returns (bytes calldata)
    {
        return ERC2771Context._msgData();
    }

    function _contextSuffixLength()
        internal
        view
        override(Context, ERC2771Context)
        returns (uint256)
    {
        return ERC2771Context._contextSuffixLength();
    }
}

