// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {Context} from "@openzeppelin/contracts/utils/Context.sol";
import {IAccessControl} from "./interfaces/IAccessControl.sol";
import "./AccessControlErrors.sol";

/**
 * @title Binary Access control
 * @author By CoMakery, Inc., Upside, Republic
 * @dev Binary equivalent to OpenZeppelin/AccessControl
 *  Uses bits for storing user roles, minify gas cost and contract size
 */
contract EasyAccessControl is IAccessControl, Context {
    uint8 public constant CONTRACT_ADMIN_ROLE = 1;  // 0000 0001
    uint8 public constant RESERVE_ADMIN_ROLE = 2;   // 0000 0010
    uint8 public constant WALLETS_ADMIN_ROLE = 4;   // 0000 0100
    uint8 public constant TRANSFER_ADMIN_ROLE = 8;  // 0000 1000
    uint8 public constant SOFT_BURN_ADMIN_ROLE = 16;// 0001 0000
    uint8 public constant MINT_ADMIN_ROLE = 32;     // 0010 0000

    // MAX_ROLE_BIT is the bitmask with all defined roles set (1|2|4|8|16|32 = 63)
    uint8 internal constant MAX_ROLE_BIT = 
        CONTRACT_ADMIN_ROLE |
        RESERVE_ADMIN_ROLE |
        WALLETS_ADMIN_ROLE |
        TRANSFER_ADMIN_ROLE |
        SOFT_BURN_ADMIN_ROLE |
        MINT_ADMIN_ROLE;

    mapping(address => uint8) private _roles; // address => binary roles
    uint8 public contractAdminCount; // counter of contract admins to keep at least one

    // Note: Events and errors are now defined in IAccessControl interface

    modifier validAddress(address addr_) {
        if (addr_ == address(0)) {
            revert EasyAccessControl_InvalidZeroAddress();
        }
        _;
    }

    modifier validRole(uint8 role) {
        if (role == 0 || role > MAX_ROLE_BIT) {
            revert EasyAccessControl_InvalidRole();
        }
        _;
    }

    modifier onlyContractAdminOrTransferAdmin() {
        _onlyContractAdminOrTransferAdmin();
        _;
    }
    function _onlyContractAdminOrTransferAdmin() internal view {
        if (
            !hasRole(_msgSender(), CONTRACT_ADMIN_ROLE) &&
            !hasRole(_msgSender(), TRANSFER_ADMIN_ROLE)
        ) {
            revert EasyAccessControl_DoesNotHaveContractOrTransferAdminRole(_msgSender());
        }
    }

    modifier onlyContractAdmin() {
        _onlyContractAdmin();
        _;
    }
    function _onlyContractAdmin() internal view {
        if (!hasRole(_msgSender(), CONTRACT_ADMIN_ROLE)) {
            revert EasyAccessControl_DoesNotHaveContractAdminRole(_msgSender());
        }
    }

    modifier onlyTransferAdmin() {
        _onlyTransferAdmin();
        _;
    }
    function _onlyTransferAdmin() internal view {
        if (!hasRole(_msgSender(), TRANSFER_ADMIN_ROLE)) {
            revert EasyAccessControl_DoesNotHaveTransferAdminRole(_msgSender());
        }
    }

    modifier onlyReserveAdmin() {
        _onlyReserveAdmin();
        _;
    }
    function _onlyReserveAdmin() internal view {
        if (!hasRole(_msgSender(), RESERVE_ADMIN_ROLE)) {
            revert EasyAccessControl_DoesNotHaveReserveAdminRole(_msgSender());
        }
    }

    modifier onlyWalletsAdmin() {
        _onlyWalletsAdmin();
        _;
    }
    function _onlyWalletsAdmin() internal view {
        if (!hasRole(_msgSender(), WALLETS_ADMIN_ROLE)) {
            revert EasyAccessControl_DoesNotHaveWalletsAdminRole(_msgSender());
        }
    }

    modifier onlyWalletsAdminOrTransferAdmin() {
        _onlyWalletsAdminOrTransferAdmin();
        _;
    }
    function _onlyWalletsAdminOrTransferAdmin() internal view {
        if (
            !hasRole(_msgSender(), WALLETS_ADMIN_ROLE) &&
            !hasRole(_msgSender(), TRANSFER_ADMIN_ROLE)
        ) {
            revert EasyAccessControl_DoesNotHaveAdminRole(_msgSender());
        }
    }

    modifier anyAdmin() {
        _anyAdmin();
        _;
    }
    function _anyAdmin() internal view {
        if (
            !hasRole(_msgSender(), RESERVE_ADMIN_ROLE) &&
            !hasRole(_msgSender(), WALLETS_ADMIN_ROLE) &&
            !hasRole(_msgSender(), TRANSFER_ADMIN_ROLE) &&
            !hasRole(_msgSender(), CONTRACT_ADMIN_ROLE)
        ) {
            revert EasyAccessControl_DoesNotHaveAdminRole(_msgSender());
        }
    }

    /**
     * @notice Constructor, init base role
     * @param contractAdmin_ address of contract admin
     */
    constructor(address contractAdmin_) validAddress(contractAdmin_) {
        _grantRole(contractAdmin_, CONTRACT_ADMIN_ROLE);
    }

    /**
     * @notice Grant roles to addresses using role bitmasks
     * @param addresses to grant roles
     * @param roles_ bitmasks array
     */
    function batchGrantRoles(
        address[] calldata addresses,
        uint8[] calldata roles_
    ) public onlyContractAdmin {
        uint256 _len = addresses.length;
        if (_len != roles_.length) {
            revert EasyAccessControl_ArraysMustBeSameLength();
        }
        for (uint256 i; i < _len; i++) {
            grantRole(addresses[i], roles_[i]);
        }
    }

    /**
     * @notice Revoke roles to addresses using role bitmasks
     * @param addresses to revoke roles
     * @param roles_ bitmasks array
     */
    function batchRevokeRoles(
        address[] calldata addresses,
        uint8[] calldata roles_
    ) public onlyContractAdmin {
        uint256 _len = addresses.length;
        if (_len != roles_.length) {
            revert EasyAccessControl_ArraysMustBeSameLength();
        }
        for (uint256 i; i < _len; i++) {
            revokeRole(addresses[i], roles_[i]);
        }
    }

    /**
     * @notice Grant role/roles to address using role bitmask
     * @param addr to grant role
     * @param role bitmask of role/roles to grant
     */
    function grantRole(
        address addr,
        uint8 role
    ) public validRole(role) validAddress(addr) onlyContractAdmin {
        _grantRole(addr, role);
    }

    /**
     * @notice Grant role/roles to address using role bitmask
     * @param addr to grant role
     * @param role bitmask of role/roles to grant
     */
    function _grantRole(address addr, uint8 role) internal virtual {
        if (hasRole(addr, role)) {
            revert EasyAccessControl_AlreadyHasRole();
        }
        if (
            _roles[addr] & CONTRACT_ADMIN_ROLE == 0 &&
            role & CONTRACT_ADMIN_ROLE > 0
        ) contractAdminCount++;
        _roles[addr] |= role;
        emit RoleChange(_msgSender(), addr, role, true);
    }

    /**
     * @notice Revoke role/roles from address using role bitmask
     * @param addr to revoke role
     * @param role bitmask of role/roles to revoke
     */
    function revokeRole(
        address addr,
        uint8 role
    ) public validRole(role) validAddress(addr) onlyContractAdmin {
        if (!hasRole(addr, role)) {
            revert EasyAccessControl_CannotRevokeRole();
        }
        if (role & CONTRACT_ADMIN_ROLE > 0) {
            if (contractAdminCount == 1) {
                revert EasyAccessControl_AtLeastOneContractAdminRequired();
            }
            contractAdminCount--;
        }
        _roles[addr] ^= role;
        emit RoleChange(_msgSender(), addr, role, false);
    }

    /**
     * @notice Check role/roles availability at address
     * @param addr to check role
     * @param role bitmask of role/roles to check
     * @return bool true or false
     */
    function hasRole(
        address addr,
        uint8 role
    ) public view validRole(role) validAddress(addr) returns (bool) {
        return _roles[addr] & role == role;
    }

    /**
     * @notice Get the roles for an address (equivalent to admins mapping)
     * @param addr The address to check
     * @return uint8 The bitmask of roles for the address
     */
    function roles(address addr) public view returns (uint8) {
        return _roles[addr];
    }
}

contracts/IdentityRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {RestrictedLockupToken} from "./RestrictedLockupToken.sol";
import {IIdentityRegistry} from "./interfaces/IIdentityRegistry.sol";
import {ERC165} from "@openzeppelin/contracts/utils/introspection/ERC165.sol";
import {Context} from "@openzeppelin/contracts/utils/Context.sol";
import {EasyAccessControl} from "./EasyAccessControl.sol";
import {ERC2771Context} from "@openzeppelin/contracts/metatx/ERC2771Context.sol";

contract IdentityRegistry is
    IIdentityRegistry,
    ERC165,
    EasyAccessControl,
    ERC2771Context
{
    uint256 constant MAX_REGIONS_COUNT = 10;
    uint256 constant MAX_VALIDITY_DURATION = 100 * 365 days;
    bytes4 public immutable INTERFACE_ID;
    uint256 private constant NO_ACCREDITATION = 0;

    mapping(address wallet => IdentityInfo info) private _identity;
    uint256 private _amlKycValidityDurationSeconds;

    error IdentityRegistry_InvalidWalletsAdmin();
    error IdentityRegistry_InvalidTrustedForwarder();
    error IdentityRegistry_WalletHasNoIdentityToRemove();
    error IdentityRegistry_WalletAlreadyHasSameRegions();
    error IdentityRegistry_WalletAlreadyHasRegion();
    error IdentityRegistry_WalletDoesNotHaveRegion();
    error IdentityRegistry_WalletAlreadyHasSameAmlKycStatus();
    error IdentityRegistry_WalletAlreadyHasSameAccreditationLevel();
    error IdentityRegistry_WalletAlreadyHasNoAccreditation();
    error IdentityRegistry_AlreadyHasSameAmlKycValidityDuration();
    error IdentityRegistry_EmptyRegionsArray();
    error IdentityRegistry_InvalidRegion();
    error IdentityRegistry_RegionsExceedsMaxCount();
    error IdentityRegistry_InvalidAmlKycValidityDuration();
    error IdentityRegistry_TimestampInTheFuture();

    constructor(
        address contractAdmin_,
        address walletsAdmin_,
        address trustedForwarder_,
        uint256 amlKycValidityDuration_
    ) EasyAccessControl(contractAdmin_) ERC2771Context(trustedForwarder_) {
        // contractAdmin verification is done in EasyAccessControl constructor
        // and reverts with EasyAccessControl_InvalidZeroAddress
        if (walletsAdmin_ == address(0)) {
            revert IdentityRegistry_InvalidWalletsAdmin();
        }
        if (trustedForwarder_ == address(0)) {
            revert IdentityRegistry_InvalidTrustedForwarder();
        }

        INTERFACE_ID = type(IIdentityRegistry).interfaceId;
        _grantRole(walletsAdmin_, WALLETS_ADMIN_ROLE);
        _updateAmlKycValidityDuration(amlKycValidityDuration_);
    }

    /**
     * Support of ERC165
     * @dev See https://eips.ethereum.org/EIPS/eip-165
     * @param interfaceId The interface identifier, as specified in ERC-165
     */
    function supportsInterface(
        bytes4 interfaceId
    ) public view override returns (bool) {
        return
            interfaceId == INTERFACE_ID || super.supportsInterface(interfaceId);
    }

    function _msgSender()
        internal
        view
        override(Context, ERC2771Context)
        returns (address sender)
    {
        return ERC2771Context._msgSender();
    }

    function _msgData()
        internal
        view
        override(Context, ERC2771Context)
        returns (bytes calldata)
    {
        return ERC2771Context._msgData();
    }

    function _contextSuffixLength()
        internal
        view
        override(Context, ERC2771Context)
        returns (uint256)
    {
        return ERC2771Context._contextSuffixLength();
    }

    /**
     * @dev Helper function to check if two arrays are equal
     */
    function _arraysEqual(uint256[] memory a, uint256[] memory b) private pure returns (bool) {
        if (a.length != b.length) {
            return false;
        }
        for (uint256 i = 0; i < a.length; i++) {
            if (a[i] != b[i]) {
                return false;
            }
        }
        return true;
    }

    /**
     * @dev Helper function to check if an array contains a specific value
     */
    function _arrayContains(uint256[] memory array, uint256 value) private pure returns (bool) {
        for (uint256 i = 0; i < array.length; i++) {
            if (array[i] == value) {
                return true;
            }
        }
        return false;
    }

    /**
     * @dev Helper function to remove a value from an array
     */
    function _removeFromArray(uint256[] storage array, uint256 value) private returns (bool) {
        for (uint256 i = 0; i < array.length; i++) {
            if (array[i] == value) {
                // Move the last element to the position of the element to remove
                array[i] = array[array.length - 1];
                array.pop();
                return true;
            }
        }
        return false;
    }

    /**
     * @dev Updates the regions for a wallet if they're different from the current values
     * @param owner The wallet address
     * @param newRegions The new regions array
     * @return changed Whether the regions were actually updated
     */
    function _updateRegions(address owner, uint256[] memory newRegions) private returns (bool changed) {
        if (newRegions.length == 0) {
            revert IdentityRegistry_EmptyRegionsArray();
        }
        if (newRegions.length > MAX_REGIONS_COUNT) {
            revert IdentityRegistry_RegionsExceedsMaxCount();
        }

        // Check for duplicates in the new regions array
        for (uint256 i = 0; i < newRegions.length; i++) {
            for (uint256 j = i + 1; j < newRegions.length; j++) {
                if (newRegions[i] == newRegions[j]) {
                    revert IdentityRegistry_InvalidRegion();
                }
            }
        }

        if (!_arraysEqual(_identity[owner].regions, newRegions)) {
            _identity[owner].regions = newRegions;
            emit RegionsSet(_msgSender(), owner, newRegions);
            return true;
        }
        return false;
    }

    /**
     * @dev Updates the AML/KYC status for a wallet if it's different from the current value
     * @param owner The wallet address
     * @param passed Whether AML/KYC is passed
     * @param timestamp The timestamp for the change (0 means use block.timestamp)
     * @return changed Whether the AML/KYC status was actually updated
     */
    function _updateAmlKyc(address owner, bool passed, uint256 timestamp) private returns (bool changed) {
        if (timestamp > block.timestamp) {
            revert IdentityRegistry_TimestampInTheFuture();
        }
        uint256 changeTimestamp = timestamp == 0 ? block.timestamp : timestamp;

        if (_identity[owner].amlKycPassed != passed || _identity[owner].lastAmlKycChangeTimestamp != changeTimestamp) {
            _identity[owner].amlKycPassed = passed;
            _identity[owner].lastAmlKycChangeTimestamp = changeTimestamp;

            if (passed) {
                emit AmlKycPassed(_msgSender(), owner, changeTimestamp);
            } else {
                emit AmlKycFailed(_msgSender(), owner, changeTimestamp);
            }
            return true;
        }
        return false;
    }

    /**
     * @dev Updates the accreditation type for a wallet if it's different from the current value
     * @param owner The wallet address
     * @param newAccreditationType The new accreditation type
     * @param timestamp The timestamp for the change (0 means use block.timestamp)
     * @return changed Whether the accreditation was actually updated
     */
    function _updateAccreditation(address owner, uint256 newAccreditationType, uint256 timestamp) private returns (bool changed) {
        if (timestamp > block.timestamp) {
            revert IdentityRegistry_TimestampInTheFuture();
        }
        uint256 changeTimestamp = timestamp == 0 ? block.timestamp : timestamp;

        if (_identity[owner].accreditationType != newAccreditationType || _identity[owner].lastAccreditationChangeTimestamp != changeTimestamp) {
            uint256 oldAccreditationType = _identity[owner].accreditationType;
            _identity[owner].accreditationType = newAccreditationType;
            _identity[owner].lastAccreditationChangeTimestamp = changeTimestamp;

            if (newAccreditationType == NO_ACCREDITATION) {
                emit AccreditationRevoked(_msgSender(), owner, oldAccreditationType, changeTimestamp);
            } else {
                emit AccreditationGranted(_msgSender(), owner, newAccreditationType, changeTimestamp);
            }
            return true;
        }
        return false;
    }

    function _updateAmlKycValidityDuration(uint256 amlKycValidityDuration_) private {
        if (amlKycValidityDuration_ > MAX_VALIDITY_DURATION) {
            revert IdentityRegistry_InvalidAmlKycValidityDuration();
        }
        uint256 oldAmlKycValidityDuration = _amlKycValidityDurationSeconds;
        _amlKycValidityDurationSeconds = amlKycValidityDuration_;
        emit AmlKycValidityDurationSet(_msgSender(), oldAmlKycValidityDuration, amlKycValidityDuration_);
    }

    /// @inheritdoc IIdentityRegistry
    function setAmlKycValidityDuration(uint256 amlKycValidityDuration_) external onlyContractAdmin {
        if (amlKycValidityDuration_ == _amlKycValidityDurationSeconds) {
            revert IdentityRegistry_AlreadyHasSameAmlKycValidityDuration();
        }
        _updateAmlKycValidityDuration(amlKycValidityDuration_);
    }

    /// @inheritdoc IIdentityRegistry
    function setIdentity(
        address owner,
        IdentityInfo memory info
    ) public override onlyWalletsAdmin {
        IdentityInfo memory oldIdentity = _identity[owner];

        bool isNewIdentity = (oldIdentity.regions.length == 0 && 
                             oldIdentity.accreditationType == NO_ACCREDITATION && 
                             !oldIdentity.amlKycPassed && 
                             oldIdentity.lastAmlKycChangeTimestamp == 0 && 
                             oldIdentity.lastAccreditationChangeTimestamp == 0);

        if (isNewIdentity) {
            emit IdentityCreated(_msgSender(), owner);
        }

        // Update each field
        _updateRegions(owner, info.regions);
        _updateAmlKyc(owner, info.amlKycPassed, info.lastAmlKycChangeTimestamp);
        _updateAccreditation(owner, info.accreditationType, info.lastAccreditationChangeTimestamp);
    }

    /// @inheritdoc IIdentityRegistry
    function batchSetIdentity(address[] memory owners, IdentityInfo memory info) external override onlyWalletsAdmin {
        for (uint256 i = 0; i < owners.length; i++) {
            setIdentity(owners[i], info);
        }
    }

    /// @inheritdoc IIdentityRegistry
    function removeIdentity(address owner) external override onlyWalletsAdmin {
        IdentityInfo memory info = _identity[owner];
        if (info.accreditationType == NO_ACCREDITATION
            && info.regions.length == 0
            && !info.amlKycPassed
            && info.lastAmlKycChangeTimestamp == 0
            && info.lastAccreditationChangeTimestamp == 0)
        {
            revert IdentityRegistry_WalletHasNoIdentityToRemove();
        }
        delete _identity[owner];
        emit IdentityRemoved(_msgSender(), owner);
    }

    /// @inheritdoc IIdentityRegistry
    function identity(
        address owner
    ) external view override returns (IdentityInfo memory) {
        return _identity[owner];
    }

    /// @inheritdoc IIdentityRegistry
    function setRegions(
        address owner,
        uint256[] memory newRegions
    ) external override onlyWalletsAdmin {
        if (!_updateRegions(owner, newRegions)) {
            revert IdentityRegistry_WalletAlreadyHasSameRegions();
        }
    }

    /// @inheritdoc IIdentityRegistry
    function addRegion(
        address owner,
        uint256 region
    ) external override onlyWalletsAdmin {
        if (_arrayContains(_identity[owner].regions, region)) {
            revert IdentityRegistry_WalletAlreadyHasRegion();
        }
        if (_identity[owner].regions.length >= MAX_REGIONS_COUNT) {
            revert IdentityRegistry_RegionsExceedsMaxCount();
        }

        _identity[owner].regions.push(region);
        emit RegionAdded(_msgSender(), owner, region);
    }

    /// @inheritdoc IIdentityRegistry
    function removeRegion(
        address owner,
        uint256 region
    ) external override onlyWalletsAdmin {
        if (!_removeFromArray(_identity[owner].regions, region)) {
            revert IdentityRegistry_WalletDoesNotHaveRegion();
        }

        emit RegionRemoved(_msgSender(), owner, region);
    }

    /// @inheritdoc IIdentityRegistry
    function grantAmlKyc(address owner, uint256 amlKycTimestamp) external override onlyWalletsAdmin {
        if (!_updateAmlKyc(owner, true, amlKycTimestamp)) {
            revert IdentityRegistry_WalletAlreadyHasSameAmlKycStatus();
        }
    }

    /// @inheritdoc IIdentityRegistry
    function revokeAmlKyc(address owner, uint256 amlKycTimestamp) external override onlyWalletsAdmin {
        if (!_updateAmlKyc(owner, false, amlKycTimestamp)) {
            revert IdentityRegistry_WalletAlreadyHasSameAmlKycStatus();
        }
    }

    /// @inheritdoc IIdentityRegistry
    function grantAccreditation(
        address owner,
        uint256 _accreditationType,
        uint256 accreditationTimestamp
    ) external override onlyWalletsAdmin {
        if (!_updateAccreditation(owner, _accreditationType, accreditationTimestamp)) {
            revert IdentityRegistry_WalletAlreadyHasSameAccreditationLevel();
        }
    }

    /// @inheritdoc IIdentityRegistry
    function revokeAccreditation(
        address owner,
        uint256 accreditationTimestamp
    ) external override onlyWalletsAdmin {
        if (!_updateAccreditation(owner, NO_ACCREDITATION, accreditationTimestamp)) {
            revert IdentityRegistry_WalletAlreadyHasNoAccreditation();
        }
    }

    /// @inheritdoc IIdentityRegistry
    function regions(
        address owner
    ) external view override returns (uint256[] memory) {
        return _identity[owner].regions;
    }

    /// @inheritdoc IIdentityRegistry
    function hasRegion(
        address owner,
        uint256 region
    ) external view override returns (bool) {
        return _arrayContains(_identity[owner].regions, region);
    }

    /// @inheritdoc IIdentityRegistry
    function accreditationType(address owner) external view override returns (uint256) {
        return _identity[owner].accreditationType;
    }

    /// @inheritdoc IIdentityRegistry
    function isAmlKycPassed(
        address owner
    ) external view override returns (bool) {
        bool isAmlKycValid = _amlKycValidityDurationSeconds == 0 ? true : (_identity[owner].lastAmlKycChangeTimestamp + _amlKycValidityDurationSeconds) >= block.timestamp;

        return _identity[owner].amlKycPassed && isAmlKycValid;
    }

    /// @inheritdoc IIdentityRegistry
    function amlKycValidityDuration() external view override returns (uint256) {
        return _amlKycValidityDurationSeconds;
    }
}

contracts/InterestPayment.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.8.28;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {ERC20, IERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ERC2771Context} from "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import {Context} from "@openzeppelin/contracts/utils/Context.sol";
import {IRestrictedLockupToken} from "./interfaces/IRestrictedLockupToken.sol";
import {IAccessControl} from "./interfaces/IAccessControl.sol";
import {ISnapshotPeriods} from "./interfaces/ISnapshotPeriods.sol";
import {IInterestPayment} from "./interfaces/IInterestPayment.sol";
import {IDividends} from "./interfaces/IDividends.sol";
import "./AccessControlErrors.sol";

/**
 * @title InterestPayment
 * @notice Contract for managing interest payments for loans backed by RestrictedLockupToken
 * @dev Tracks interest accrual based on token holdings and allows claiming of interest payments
 */
contract InterestPayment is
    IInterestPayment,
    IDividends,
    ReentrancyGuard,
    Pausable,
    ERC2771Context
{
    // Role constants
    uint8 public constant CONTRACT_ADMIN_ROLE = 1;
    uint8 public constant RESERVE_ADMIN_ROLE = 2;
    uint8 public constant WALLETS_ADMIN_ROLE = 4;
    uint8 public constant TRANSFER_ADMIN_ROLE = 8;

    uint256 public constant INTEREST_RATE_PRECISION_FACTOR = 1_000_000_000;
    uint256 private constant BIPS_PRECISION = 10_000;

    // Valid duration periods in seconds (360, 365, 366 days)
    uint256 private constant DURATION_360_DAYS = 360 * 24 * 60 * 60; // 31,104,000 seconds
    uint256 private constant DURATION_365_DAYS = 365 * 24 * 60 * 60; // 31,536,000 seconds
    uint256 private constant DURATION_366_DAYS = 366 * 24 * 60 * 60; // 31,622,400 seconds

    /// @dev Struct to hold constructor parameters to avoid stack too deep issues
    struct ConstructorParams {
        address accessControl; // external access control address
        address restrictedLockupTokenAddress;
        address trustedForwarder;
        address paymentToken;
        uint256 paymentPeriodSeconds;
        uint256 principalAmountPerToken;
        uint256 interestAccrualStartTimestamp;
        uint256 interestAccrualEndTimestamp;
        uint256 maxInterestRate;
    }

    IRestrictedLockupToken private immutable restrictedLockupToken_;
    ISnapshotPeriods public immutable snapshotPeriods;
    IERC20 private immutable paymentToken_;
    uint256 public maxInterestRate;
    uint256 private immutable principalAmountPerToken_;
    uint256 public interestRatePeriodSeconds;
    uint256 public interestAccrualStartTimestamp;
    uint256 public interestAccrualEndTimestamp;
    uint256 public paymentPausedAfterTimestamp;
    address public reclaimerAddress;
    using SafeERC20 for IERC20;
    IAccessControl public accessControl;

    struct PaymentPeriod {
        uint256 startTimestamp;
        uint256 endTimestamp;
        uint256 interestRatePerSecond;
        uint256 totalClaimedInterest;
        uint256 totalReclaimedInterest;
        uint256 interestRate;
        bool paused;
    }

    struct AccountInfo {
        uint256 claimedInterest;
        uint256 reclaimedInterest;
    }

    /// @dev Dividend-related structures (adapted from Dividends contract)
    struct FundedDividends {
        uint256 totalFunds; // Total dividend tokens
        uint256 unusedFunds; // Unused dividend tokens
        uint256 dividendPerSecurity; // Dividend token per security token
    }

    uint256 private _fundedPrincipalAmount;
    uint256 private _totalPrincipalAmountClaimed;
    uint256 private _totalPrincipalAmountReclaimed;
    uint256 private _totalPrincipalAmountUnused;

    uint256 private _totalInterestAmountFunded;
    uint256 private _totalInterestAmountUnused;
    uint256 private _totalInterestAmountClaimed;
    uint256 private _totalInterestAmountReclaimed;

    PaymentPeriod[] public paymentPeriods;

    // @dev periodIdx => receiver => amount of claimed and reclaimed interest funds
    mapping(uint256 => mapping(address => AccountInfo))
        private accountInfoByPeriods; // claimed interest funds of ERC20

    /// @dev Dividend-related mappings (adapted from Dividends contract)
    /// @dev timestamp => token => receiver => amount of claimed dividend funds
    mapping(uint256 => mapping(address => mapping(address => uint256)))
        internal dividendClaimedFunds; // claimed dividend funds of ERC20

    /// @dev timestamp => token addr => FundedDividends struct
    mapping(uint256 => mapping(address => FundedDividends))
        internal fundedDividends;

    // Errors
    error InterestPayment_InvalidRestrictedLockupTokenAddress();
    error InterestPayment_InvalidPaymentPeriodSeconds();
    error InterestPayment_InvalidAmount();
    error InterestPayment_TokenSupplyIsZero();
    error InterestPayment_PrincipalAmountNotDivisibleByTokenSupply();
    error InterestPayment_InvalidFeeApplied();
    error InterestPayment_InvalidUnclaimedAmount(
        uint256 claimableFunds,
        uint256 claimedFunds
    );
    error InterestPayment_InvalidPeriod();
    error InterestPayment_InvalidPeriodIndex();
    error InterestPayment_StartTimestampGreaterThanEndTimestamp();
    error InterestPayment_StartTimestampBeforeAccrualStartTimestamp();
    error InterestPayment_EndTimestampGreaterThanAccrualEndTimestamp();
    error InterestPayment_PeriodDurationNotMultipleOfInterestRatePeriod();
    error InterestPayment_PeriodAlreadyExists();
    error InterestPayment_PeriodNotNext();
    error InterestPayment_NoPaymentPeriods();
    error InterestPayment_NoFundsToClaim();
    error InterestPayment_NotEnoughFundsToClaim();
    error InterestPayment_NotEnoughFundedPrincipal();
    error InterestPayment_PaymentNotPausedAfter();
    error InterestPayment_CannotUnpauseAfterMaturity();
    error InterestPayment_CannotReclaimAllForOngoingPeriod();
    error InterestPayment_InvalidTimestamp();
    error InterestPayment_InvalidInterestAccrualStartTimestamp();
    error InterestPayment_InvalidInterestAccrualEndTimestamp();
    error InterestPayment_InvalidInterestAccrualPeriod();
    error InterestPayment_InvalidPrincipalAmountPerToken();
    error InterestPayment_InvalidReclaimerAddress();
    error InterestPayment_PaymentPeriodPaused(uint256 periodIdx);
    error InterestPayment_MaturityNotReached();
    error InterestPayment_InvalidPaymentToken();
    error InterestPayment_InterestRateGreaterThanMaxInterestRate();
    error InterestPayment_PeriodAlreadyStarted();
    error InterestPayment_InterestRateNotChanged();
    error InterestPayment_MaxInterestRateNotChanged();
    error InterestPayment_InvalidInterestRatePeriodDuration();

    // Dividend-related errors (adapted from Dividends contract)
    error InterestPayment_InvalidDividendSnapshotId();
    error InterestPayment_NoRemainingUnclaimedDividendBalance();
    error InterestPayment_InvalidDividendTokenAddress();
    error InterestPayment_InvalidTokenDecimals(uint8 restrictedLockupTokenDecimals);
    error InterestPayment_IndivisibleAmount(
        uint256 paymentTokenAmount,
        uint256 totalSupplyAt
    );
    error InterestPayment_InvalidUnclaimedDividendBalance(
        uint256 claimableFunds,
        uint256 claimedFunds
    );
    error InterestPayment_ZeroTotalSupply();
    error InterestPayment_DividendsAlreadyClaimed();
    error InterestPayment_InvalidArrayLengths();

    modifier onlyValidPeriod(uint256 periodIdx_) {
        if (periodIdx_ >= paymentPeriods.length) {
            revert InterestPayment_InvalidPeriodIndex();
        }
        _;
    }

    modifier onlyValidReclaimerAddress(address reclaimerAddress_) {
        if (reclaimerAddress_ == address(0)) {
            revert InterestPayment_InvalidReclaimerAddress();
        }
        _;
    }

    modifier whenPeriodPaymentNotPaused(uint256 periodIdx) {
        if (paymentPeriodPaused(periodIdx)) {
            revert InterestPayment_PaymentPeriodPaused(periodIdx);
        }
        _;
    }

    modifier onlyValidAmount(uint256 amount) {
        if (amount == 0) {
            revert InterestPayment_InvalidAmount();
        }
        _;
    }

    modifier onlyValidDividendSnapshotId(uint256 timestamp_) {
        if (timestamp_ == 0 || timestamp_ >= block.timestamp) {
            revert InterestPayment_InvalidDividendSnapshotId();
        }
        _;
    }

    modifier onlyValidInterestRatePeriodDuration(uint256 interestRatePeriodDuration_) {
        if (interestRatePeriodDuration_ != DURATION_360_DAYS && 
            interestRatePeriodDuration_ != DURATION_365_DAYS && 
            interestRatePeriodDuration_ != DURATION_366_DAYS) {
            revert InterestPayment_InvalidInterestRatePeriodDuration();
        }
        _;
    }

    constructor(
        ConstructorParams memory params
    ) ReentrancyGuard() ERC2771Context(params.trustedForwarder) {
        if (params.restrictedLockupTokenAddress == address(0)) {
            revert InterestPayment_InvalidRestrictedLockupTokenAddress();
        }
        if (params.paymentPeriodSeconds == 0) {
            revert InterestPayment_InvalidPaymentPeriodSeconds();
        }
        if (params.interestAccrualStartTimestamp == 0) {
            revert InterestPayment_InvalidInterestAccrualStartTimestamp();
        }
        if (params.interestAccrualEndTimestamp == 0) {
            revert InterestPayment_InvalidInterestAccrualEndTimestamp();
        }
        if (
            params.interestAccrualStartTimestamp >=
            params.interestAccrualEndTimestamp
        ) {
            revert InterestPayment_InvalidInterestAccrualPeriod();
        }
        if (params.principalAmountPerToken == 0) {
            revert InterestPayment_InvalidPrincipalAmountPerToken();
        }
        if (params.paymentToken == address(0)) {
            revert InterestPayment_InvalidPaymentToken();
        }

        // set external access control
        if (params.accessControl == address(0)) {
            revert EasyAccessControl_InvalidZeroAddress();
        }

        accessControl = IAccessControl(params.accessControl);
        interestAccrualStartTimestamp = params.interestAccrualStartTimestamp;
        interestAccrualEndTimestamp = params.interestAccrualEndTimestamp;
        interestRatePeriodSeconds = params.paymentPeriodSeconds;
        maxInterestRate = params.maxInterestRate;
        principalAmountPerToken_ = params.principalAmountPerToken;

        restrictedLockupToken_ = IRestrictedLockupToken(
            params.restrictedLockupTokenAddress
        );
        snapshotPeriods = ISnapshotPeriods(
            restrictedLockupToken_.snapshotPeriodsAddress()
        );
        paymentToken_ = IERC20(params.paymentToken);
    }

    function _msgSender()
        internal
        view
        override(Context, ERC2771Context)
        returns (address sender)
    {
        return ERC2771Context._msgSender();
    }

    function _msgData()
        internal
        view
        override(Context, ERC2771Context)
        returns (bytes calldata)
    {
        return ERC2771Context._msgData();
    }

    function _contextSuffixLength()
        internal
        view
        override(Context, ERC2771Context)
        returns (uint256)
    {
        return ERC2771Context._contextSuffixLength();
    }

    /// @inheritdoc IInterestPayment
    function paymentPeriodPaused(
        uint256 periodIdx
    ) public view override returns (bool) {
        return paymentPeriods[periodIdx].paused;
    }

    // Access control modifiers (using external accessControl)
    modifier onlyContractAdminOrTransferAdmin() {
        _onlyContractAdminOrTransferAdmin();
        _;
    }
    modifier onlyContractAdmin() {
        _onlyContractAdmin();
        _;
    }
    modifier onlyTransferAdmin() {
        _onlyTransferAdmin();
        _;
    }
    function _onlyTransferAdmin() internal view {
        if (!accessControl.hasRole(_msgSender(), TRANSFER_ADMIN_ROLE)) {
            revert EasyAccessControl_DoesNotHaveTransferAdminRole(_msgSender());
        }
    }
    function _onlyContractAdminOrTransferAdmin() internal view {
        if (
            !accessControl.hasRole(_msgSender(), CONTRACT_ADMIN_ROLE) &&
            !accessControl.hasRole(_msgSender(), TRANSFER_ADMIN_ROLE)
        ) {
            revert EasyAccessControl_DoesNotHaveContractOrTransferAdminRole(_msgSender());
        }
    }
    function _onlyContractAdmin() internal view {
        if (!accessControl.hasRole(_msgSender(), CONTRACT_ADMIN_ROLE)) {
            revert EasyAccessControl_DoesNotHaveContractAdminRole(_msgSender());
        }
    }

    /// @inheritdoc IInterestPayment
    function pausePaymentPeriod(
        uint256 periodIdx
    )
        external
        override
        onlyContractAdminOrTransferAdmin
        onlyValidPeriod(periodIdx)
    {
        paymentPeriods[periodIdx].paused = true;
        emit PeriodPaused(_msgSender(), periodIdx);
    }

    /// @inheritdoc IInterestPayment
    function unpausePaymentPeriod(
        uint256 periodIdx
    )
        external
        override
        onlyContractAdminOrTransferAdmin
        onlyValidPeriod(periodIdx)
    {
        paymentPeriods[periodIdx].paused = false;
        emit PeriodUnpaused(_msgSender(), periodIdx);
    }

    /**
     * @dev pause contract. Only contract or transfer admin.
     */
    function pause(bool isPaused_) external onlyContractAdminOrTransferAdmin {
        if (isPaused_) {
            _pause();
        } else {
            _unpause();
        }
    }

    function _pausePaymentAfterTimestamp(uint256 timestamp) internal {
        if (timestamp == 0 || timestamp < block.timestamp) {
            revert InterestPayment_InvalidTimestamp();
        }
        if (timestamp < interestAccrualStartTimestamp) {
            revert InterestPayment_InvalidTimestamp();
        }
        paymentPausedAfterTimestamp = timestamp;

        emit PaymentPausedAfter(timestamp);
    }

    /**
     * @dev pause contract. Only contract or transfer admin.
     */
    function pausePaymentAfter(
        uint256 timestamp
    ) external onlyContractAdminOrTransferAdmin {
        _pausePaymentAfterTimestamp(timestamp);
    }

    function unpausePaymentAfter() external onlyContractAdminOrTransferAdmin {
        if (paymentPausedAfterTimestamp == 0) {
            revert InterestPayment_PaymentNotPausedAfter();
        }
        if (block.timestamp > interestAccrualEndTimestamp) {
            revert InterestPayment_CannotUnpauseAfterMaturity();
        }
        paymentPausedAfterTimestamp = 0;

        emit PaymentUnpausedAfter();
    }

    /// @inheritdoc IInterestPayment
    function setReclaimerAddress(
        address newReclaimerAddress
    ) external onlyContractAdmin {
        reclaimerAddress = newReclaimerAddress;

        emit ReclaimerAddressChanged(_msgSender(), newReclaimerAddress);
    }

    function _updateInterestAccrualEnd(uint256 newInterestAccrualEndTimestamp) internal {
        interestAccrualEndTimestamp = newInterestAccrualEndTimestamp;

        emit InterestAccrualEndShifted(
            _msgSender(),
            newInterestAccrualEndTimestamp
        );
    }

    /// @inheritdoc IInterestPayment
    function shiftInterestAccrualEnd(
        uint256 newInterestAccrualEndTimestamp
    ) external onlyContractAdminOrTransferAdmin {
        if (newInterestAccrualEndTimestamp <= interestAccrualEndTimestamp) {
            revert InterestPayment_InvalidInterestAccrualEndTimestamp();
        }
        _updateInterestAccrualEnd(newInterestAccrualEndTimestamp);
    }

    function setMaxInterestRate(
        uint256 maxInterestRate_
    ) external onlyContractAdmin {
        if (maxInterestRate_ == maxInterestRate) {
            revert InterestPayment_MaxInterestRateNotChanged();
        }
        maxInterestRate = maxInterestRate_;

        emit SetMaxInterestRate(_msgSender(), maxInterestRate_);
    }

    function updateInterestRateForPeriod(
        uint256 periodIdx,
        uint256 interestRate_,
        uint256 interestRatePeriodDuration
    )
        external
        nonReentrant
        onlyTransferAdmin
        whenNotPaused
        onlyValidPeriod(periodIdx)
        onlyValidInterestRatePeriodDuration(interestRatePeriodDuration)
    {
        if (interestRate_ > maxInterestRate && maxInterestRate != 0) {
            revert InterestPayment_InterestRateGreaterThanMaxInterestRate();
        }
        if (block.timestamp > paymentPeriods[periodIdx].startTimestamp) {
            revert InterestPayment_PeriodAlreadyStarted();
        }
        if (interestRate_ == paymentPeriods[periodIdx].interestRate) {
            revert InterestPayment_InterestRateNotChanged();
        }
        uint256 interestRatePerSecond = calculateInterestRatePerSecond(
            interestRate_,
            interestRatePeriodDuration
        );
        paymentPeriods[periodIdx].interestRatePerSecond = interestRatePerSecond;
        paymentPeriods[periodIdx].interestRate = interestRate_;

        emit InterestRateUpdated(_msgSender(), periodIdx, interestRate_);
    }

    function totalInterestAmountFunded() public view returns (uint256) {
        return _totalInterestAmountFunded;
    }

    function totalInterestAmountUnused() public view returns (uint256) {
        return _totalInterestAmountUnused;
    }

    function totalInterestAmountClaimed() public view returns (uint256) {
        return _totalInterestAmountClaimed;
    }

    function totalInterestAmountReclaimed() public view returns (uint256) {
        return _totalInterestAmountReclaimed;
    }

    /// @inheritdoc IInterestPayment
    function accruedInterest(
        address account
    ) public view override returns (uint256) {
        return accruedInterestAt(account, block.timestamp);
    }

    /// @inheritdoc IInterestPayment
    function accruedInterestAt(
        address account,
        uint256 timestamp
    ) public view override returns (uint256) {
        uint256 endTimestamp = nearestInterestPaymentTimestampAt(timestamp);
        if (endTimestamp <= interestAccrualStartTimestamp) {
            return 0;
        }

        uint256 accruedInterestAmount = 0;
        for (uint256 i = 0; i < paymentPeriods.length; i++) {
            PaymentPeriod memory period = paymentPeriods[i];
            uint256 accountOwnershipForPeriod = 0;
            if (endTimestamp >= period.endTimestamp) {
                // fully accrued period
                accountOwnershipForPeriod = snapshotPeriods.ownershipForPeriod(
                    address(restrictedLockupToken_),
                    account,
                    period.startTimestamp,
                    period.endTimestamp
                );
            } else if (endTimestamp > period.startTimestamp) {
                accountOwnershipForPeriod = snapshotPeriods.ownershipForPeriod(
                    address(restrictedLockupToken_),
                    account,
                    period.startTimestamp,
                    endTimestamp
                );
            }
            accruedInterestAmount += _calculateInterest(
                period.interestRatePerSecond * accountOwnershipForPeriod
            );
            if (endTimestamp <= period.startTimestamp) {
                break;
            }
        }

        return accruedInterestAmount;
    }

    //  it can be calculated
    // as totalAccruedInterestAt(period.endTimestamp) - totalAccruedInterestAt(period.startTimestamp)
    // or as is ownershipForPeriod * period.interestRatePerSecond * principalAmountPerToken / PRECISION_FACTOR / BIPS_PRECISION
    function accruedInterestForPeriod(
        address account,
        uint256 periodIdx
    ) public view returns (uint256) {
        uint256 endTimestamp = nearestInterestPaymentTimestampAt(
            block.timestamp
        );
        PaymentPeriod memory period = paymentPeriods[periodIdx];
        if (endTimestamp <= period.startTimestamp) {
            return 0;
        }
        if (endTimestamp >= period.endTimestamp) {
            endTimestamp = period.endTimestamp;
        }
        uint256 ownershipForPeriodAmount = snapshotPeriods.ownershipForPeriod(
            address(restrictedLockupToken_),
            account,
            period.startTimestamp,
            endTimestamp
        );

        return
            _calculateInterest(
                period.interestRatePerSecond * ownershipForPeriodAmount
            );
    }

    /// @inheritdoc IInterestPayment
    function totalAccruedInterest() external view returns (uint256) {
        return totalAccruedInterestAt(block.timestamp);
    }

    /// @inheritdoc IInterestPayment
    function totalAccruedInterestAt(
        uint256 timestamp
    ) public view override returns (uint256 totalAmount) {
        uint256 endTimestamp = timestamp > block.timestamp
            ? nearestInterestPaymentTimestampAt(block.timestamp)
            : nearestInterestPaymentTimestampAt(timestamp);
        for (uint256 i = 0; i < paymentPeriods.length; i++) {
            PaymentPeriod memory period = paymentPeriods[i];
            uint256 totalOwnershipForPeriod = 0;
            if (endTimestamp >= period.endTimestamp) {
                // fully accrued period
                totalOwnershipForPeriod = snapshotPeriods
                    .totalOwnershipForPeriod(
                        address(restrictedLockupToken_),
                        period.startTimestamp,
                        period.endTimestamp
                    );
            } else if (endTimestamp > period.startTimestamp) {
                totalOwnershipForPeriod = snapshotPeriods
                    .totalOwnershipForPeriod(
                        address(restrictedLockupToken_),
                        period.startTimestamp,
                        endTimestamp
                    );
            }
            totalAmount += _calculateInterest(
                period.interestRatePerSecond * totalOwnershipForPeriod
            );
            if (endTimestamp <= period.startTimestamp) {
                break;
            }
        }
    }

    function _calculateInterest(
        uint256 interestOwnershipPerSecond
    ) internal view returns (uint256) {
        return
            (interestOwnershipPerSecond * principalAmountPerToken_) /
            INTEREST_RATE_PRECISION_FACTOR /
            BIPS_PRECISION;
    }

    // @inheritdoc IInterestPayment
    function nearestInterestPaymentTimestampAt(
        uint256 timestamp
    ) public view returns (uint256) {
        if (timestamp < interestAccrualStartTimestamp) {
            return interestAccrualStartTimestamp;
        }
        uint256 effectiveTimestamp = timestamp;
        if (
            paymentPausedAfterTimestamp > 0 &&
            timestamp > paymentPausedAfterTimestamp
        ) {
            effectiveTimestamp = paymentPausedAfterTimestamp;
        }
        if (effectiveTimestamp >= interestAccrualEndTimestamp) {
            return interestAccrualEndTimestamp;
        }

        uint256 paymentTimestamp = effectiveTimestamp -
            ((effectiveTimestamp - interestAccrualStartTimestamp) %
                interestRatePeriodSeconds);

        return paymentTimestamp;
    }

    // @inheritdoc IInterestPayment
    function findPaymentPeriodIndex(
        uint256 startTimestamp,
        uint256 endTimestamp
    ) public view returns (uint256) {
        if (paymentPeriods.length == 0) {
            return type(uint256).max;
        }

        uint256 left = 0;
        uint256 right = paymentPeriods.length;

        while (left < right) {
            uint256 mid = left + (right - left) / 2;
            if (paymentPeriods[mid].startTimestamp < startTimestamp) {
                left = mid + 1;
            } else {
                right = mid;
            }
        }
        if (left == paymentPeriods.length) {
            return type(uint256).max;
        }

        if (
            paymentPeriods[left].startTimestamp == startTimestamp &&
            paymentPeriods[left].endTimestamp == endTimestamp
        ) {
            return left;
        }

        return type(uint256).max; // Return max if not found
    }

    /// @dev fund interest for a period
    /// @param startTimestamp start timestamp
    /// @param endTimestamp end timestamp
    /// @param interestRate_ interest rate in BIPS
    /// @param interestRatePeriodDuration interest rate period duration
    function createPaymentPeriod(
        uint256 startTimestamp,
        uint256 endTimestamp,
        uint256 interestRate_,
        uint256 interestRatePeriodDuration
    ) external nonReentrant onlyTransferAdmin whenNotPaused onlyValidInterestRatePeriodDuration(interestRatePeriodDuration) {
        if (startTimestamp >= endTimestamp) {
            revert InterestPayment_StartTimestampGreaterThanEndTimestamp();
        }
        if (startTimestamp < interestAccrualStartTimestamp) {
            revert InterestPayment_StartTimestampBeforeAccrualStartTimestamp();
        }
        if (endTimestamp > interestAccrualEndTimestamp) {
            revert InterestPayment_EndTimestampGreaterThanAccrualEndTimestamp();
        }
        if ((endTimestamp - startTimestamp) % interestRatePeriodSeconds != 0) {
            if (endTimestamp != interestAccrualEndTimestamp) {
                revert InterestPayment_PeriodDurationNotMultipleOfInterestRatePeriod();
            }
        }

        uint256 accrualPeriodIdx = findPaymentPeriodIndex(
            startTimestamp,
            endTimestamp
        );
        if (accrualPeriodIdx != type(uint256).max) {
            revert InterestPayment_PeriodAlreadyExists();
        }
        // no period found -> create new period
        // but check if it is next period after last funded period or startTimestamp is accrual start timestamp
        if (paymentPeriods.length > 0) {
            if (
                startTimestamp !=
                paymentPeriods[paymentPeriods.length - 1].endTimestamp
            ) {
                revert InterestPayment_PeriodNotNext();
            }
        } else {
            if (startTimestamp != interestAccrualStartTimestamp) {
                revert InterestPayment_PeriodNotNext();
            }
        }

        _createPaymentPeriod(
            startTimestamp,
            endTimestamp,
            interestRate_,
            interestRatePeriodDuration
        );
    }

    function _createPaymentPeriod(
        uint256 startTimestamp,
        uint256 endTimestamp,
        uint256 interestRate_,
        uint256 interestRatePeriodDuration
    ) internal {
        if (interestRate_ > maxInterestRate && maxInterestRate != 0) {
            revert InterestPayment_InterestRateGreaterThanMaxInterestRate();
        }
        uint256 accrualPeriodIdx = paymentPeriods.length;
        uint256 interestRatePerSecond = calculateInterestRatePerSecond(
            interestRate_,
            interestRatePeriodDuration
        );

        paymentPeriods.push(
            PaymentPeriod(
                startTimestamp,
                endTimestamp,
                interestRatePerSecond,
                0,
                0,
                interestRate_,
                false
            )
        );

        emit PaymentPeriodCreated(
            _msgSender(),
            accrualPeriodIdx,
            startTimestamp,
            endTimestamp,
            interestRate_
        );
    }

    function calculateInterestRatePerSecond(
        uint256 interestRate_,
        uint256 interestRatePeriodDuration
    ) internal pure returns (uint256) {
        return
            (interestRate_ * INTEREST_RATE_PRECISION_FACTOR) /
            interestRatePeriodDuration;
    }

    /// @inheritdoc IInterestPayment
    function fundInterest(
        uint256 amount
    )
        external
        nonReentrant
        whenNotPaused
        onlyValidAmount(amount)
    {
        _totalInterestAmountFunded += amount;
        _totalInterestAmountUnused += amount;

        uint256 _balanceBefore = paymentToken_.balanceOf(address(this));
        paymentToken_.safeTransferFrom(_msgSender(), address(this), amount);
        uint256 _balanceAfter = paymentToken_.balanceOf(address(this));
        if (_balanceBefore + amount != _balanceAfter) {
            revert InterestPayment_InvalidFeeApplied();
        }

        emit Funded(_msgSender(), amount);
    }

    /// @inheritdoc IInterestPayment
    function claimInterestForPeriod(
        uint256 paymentPeriodIdx,
        uint256 amount
    )
        public
        nonReentrant
        onlyValidPeriod(paymentPeriodIdx)
        whenPeriodPaymentNotPaused(paymentPeriodIdx)
        whenNotPaused
    {
        _claimInterestForPeriod(_msgSender(), paymentPeriodIdx, amount, false);
    }

    // @inheritdoc IInterestPayment
    function batchClaimInterestForPeriods(
        uint256[] memory paymentPeriodIdxs,
        uint256 amount
    ) external whenNotPaused {
        if (paymentPeriodIdxs.length == 0) {
            revert InterestPayment_InvalidPeriod();
        }
        if (
            amount > _totalInterestAmountUnused ||
            _totalInterestAmountUnused == 0
        ) {
            revert InterestPayment_NoFundsToClaim();
        }
        uint256 totalClaimableAmount = 0;
        for (uint256 i = 0; i < paymentPeriodIdxs.length; i++) {
            if (paymentPeriodIdxs[i] >= paymentPeriods.length) {
                revert InterestPayment_InvalidPeriodIndex();
            }
            if (paymentPeriodPaused(paymentPeriodIdxs[i])) {
                revert InterestPayment_PaymentPeriodPaused(
                    paymentPeriodIdxs[i]
                );
            }
            uint256 claimableAmount = unclaimedAmountForPeriod(
                _msgSender(),
                paymentPeriodIdxs[i]
            );
            if (claimableAmount == 0) {
                revert InterestPayment_NoFundsToClaim();
            }

            totalClaimableAmount += claimableAmount;
            if (amount > 0 && totalClaimableAmount > amount) {
                uint256 adjustment = totalClaimableAmount - amount;
                claimableAmount -= adjustment;
                totalClaimableAmount = amount;
            }
            claimInterestForPeriod(paymentPeriodIdxs[i], claimableAmount);
            if (amount > 0 && totalClaimableAmount >= amount) {
                break;
            }
        }
    }

    function _claimInterest(
        address target,
        uint256 amount,
        bool isForceClaimByAdmin
    ) internal {
        uint256 currentTimestamp = block.timestamp;
        uint256 currentPaymentTimestamp = nearestInterestPaymentTimestampAt(
            currentTimestamp
        );

        uint256 totalClaimableAmount = 0;

        // Check if there are any funded periods
        if (paymentPeriods.length == 0) {
            revert InterestPayment_NoPaymentPeriods();
        }

        // Process each funded period
        for (uint256 i = 0; i < paymentPeriods.length; i++) {
            PaymentPeriod storage period = paymentPeriods[i];
            // Check if period is accrued (fully or partially)
            if (currentPaymentTimestamp <= period.startTimestamp) {
                // Period has not started accruing yet
                // we can break here because all subsequent periods will not be accrued
                break;
            }
            uint256 claimableAmount = unclaimedAmountForPeriod(target, i);

            // Skip periods with no unused funds if payment period is paused
            if (claimableAmount == 0 || (!isForceClaimByAdmin && paymentPeriodPaused(i))) {
                continue;
            }

            totalClaimableAmount += claimableAmount;

            // Check if we've reached the amount cap (if provided)
            if (amount > 0 && totalClaimableAmount > amount) {
                // Adjust the claimable amount for this period to respect the cap
                uint256 adjustment = totalClaimableAmount - amount;
                claimableAmount -= adjustment;
                totalClaimableAmount = amount;
            }

            // Update claimed funds and unused funds
            period.totalClaimedInterest += claimableAmount;
            accountInfoByPeriods[i][target]
                .claimedInterest += claimableAmount;

            if (isForceClaimByAdmin) {
                emit ForceClaimed(_msgSender(), target, claimableAmount, i);
            } else {
                emit Claimed(target, claimableAmount, i);
            }

            // If we've reached the amount cap, exit the loop
            if (amount > 0 && totalClaimableAmount >= amount) {
                break;
            }
        }

        if (amount > 0 && totalClaimableAmount < amount) {
            revert InterestPayment_NotEnoughFundsToClaim();
        }
        // Check if we have any funds to claim after processing all periods
        if (totalClaimableAmount == 0) {
            revert InterestPayment_NoFundsToClaim();
        }
        if (totalClaimableAmount > _totalInterestAmountUnused) {
            revert InterestPayment_NoFundsToClaim();
        }
        _totalInterestAmountUnused -= totalClaimableAmount;
        _totalInterestAmountClaimed += totalClaimableAmount;

        // Transfer the total claimable amount
        paymentToken_.safeTransfer(target, totalClaimableAmount);
    }

    function _claimInterestForPeriod(
        address target,
        uint256 paymentPeriodIdx,
        uint256 amount,
        bool isForceClaimByAdmin
    ) internal {
        if (
            amount > _totalInterestAmountUnused ||
            _totalInterestAmountUnused == 0
        ) {
            revert InterestPayment_NoFundsToClaim();
        }
        uint256 availableClaimableAmount = unclaimedAmountForPeriod(
            target,
            paymentPeriodIdx
        );
        if (availableClaimableAmount == 0) {
            revert InterestPayment_NoFundsToClaim();
        }
        if (availableClaimableAmount < amount) {
            revert InterestPayment_NotEnoughFundsToClaim();
        }
        if (amount > 0) {
            // claim specific amount for period (not all funds)
            availableClaimableAmount = amount;
        }

        accountInfoByPeriods[paymentPeriodIdx][target]
            .claimedInterest += availableClaimableAmount;
        paymentPeriods[paymentPeriodIdx]
            .totalClaimedInterest += availableClaimableAmount;
        _totalInterestAmountClaimed += availableClaimableAmount;
        _totalInterestAmountUnused -= availableClaimableAmount;

        if (isForceClaimByAdmin) {
            emit ForceClaimed(_msgSender(), target, availableClaimableAmount, paymentPeriodIdx);
        } else {
            emit Claimed(target, availableClaimableAmount, paymentPeriodIdx);
        }

        paymentToken_.safeTransfer(target, availableClaimableAmount);
    }

    /// @dev claim interest for all periods
    /// @notice this function can run out of gas if there are a lot of periods
    ///         so claim each period separately
    function claimInterest(uint256 amount) public nonReentrant whenNotPaused {
        _claimInterest(_msgSender(), amount, false);
    }

    /// @notice Force claim interest for a specific wallet address
    /// @dev Only callable by Transfer Admin. Similar to claimInterest but claims on behalf of a wallet address and with amount cap
    /// @param wallet The wallet address to claim interest for
    /// @param amount The maximum amount to claim, or 0 for all available funds
    function forceClaim(
        address wallet,
        uint256 amount
    ) external nonReentrant onlyTransferAdmin whenNotPaused {
        _claimInterest(wallet, amount, true);
    }

    function paymentPeriodsCount() public view returns (uint256) {
        return paymentPeriods.length;
    }

    function periodTotalInterest(
        uint256 periodIdx
    ) public view returns (uint256) {
        uint256 endTimestamp = nearestInterestPaymentTimestampAt(
            block.timestamp
        );
        PaymentPeriod memory period = paymentPeriods[periodIdx];
        if (endTimestamp <= period.startTimestamp) {
            return 0;
        }
        if (endTimestamp >= period.endTimestamp) {
            endTimestamp = period.endTimestamp;
        }
        uint256 totalOwnershipForPeriod = snapshotPeriods
            .totalOwnershipForPeriod(
                address(restrictedLockupToken_),
                period.startTimestamp,
                endTimestamp
            );

        return
            _calculateInterest(
                period.interestRatePerSecond * totalOwnershipForPeriod
            );
    }

    function periodTotalClaimedInterest(
        uint256 periodIdx
    ) public view returns (uint256) {
        return paymentPeriods[periodIdx].totalClaimedInterest;
    }

    function periodTotalReclaimedInterest(
        uint256 periodIdx
    ) public view returns (uint256) {
        return paymentPeriods[periodIdx].totalReclaimedInterest;
    }

    /// @inheritdoc IInterestPayment
    function periodAvailableInterest(
        uint256 periodIdx
    ) public view returns (uint256) {
        uint256 _totalAccruedInterestForPeriod = periodTotalInterest(periodIdx);

        if (
            _totalAccruedInterestForPeriod <=
            paymentPeriods[periodIdx].totalClaimedInterest +
                paymentPeriods[periodIdx].totalReclaimedInterest
        ) {
            return 0;
        }

        return
            _totalAccruedInterestForPeriod -
            paymentPeriods[periodIdx].totalClaimedInterest -
            paymentPeriods[periodIdx].totalReclaimedInterest;
    }

    function periodDuration(uint256 periodIdx) public view returns (uint256) {
        return
            paymentPeriods[periodIdx].endTimestamp -
            paymentPeriods[periodIdx].startTimestamp;
    }

    function periodStartTimestamp(
        uint256 periodIdx
    ) public view returns (uint256) {
        return paymentPeriods[periodIdx].startTimestamp;
    }

    function periodEndTimestamp(
        uint256 periodIdx
    ) public view returns (uint256) {
        return paymentPeriods[periodIdx].endTimestamp;
    }

    function unclaimedAmountAt(
        address receiver_,
        uint256 timestamp
    ) public view returns (uint256 totalClaimableAmount) {
        for (uint256 i = 0; i < paymentPeriods.length; i++) {
            if (paymentPeriods[i].startTimestamp > timestamp) {
                break;
            }
            totalClaimableAmount += unclaimedAmountForPeriod(receiver_, i);
        }
    }

    /// @inheritdoc IInterestPayment
    /// @dev Cap available claimable amount to unused funds in the period or total unused funds
    function unclaimedAmountForPeriod(
        address receiver_,
        uint256 paymentPeriodIdx_
    ) public view returns (uint256 _unclaimedAmountForPeriod) {
        uint256 _claimableFunds = accruedInterestForPeriod(
            receiver_,
            paymentPeriodIdx_
        );
        uint256 _usedFunds = usedAmountForPeriod(receiver_, paymentPeriodIdx_);
        // should not happen because we check for available funds to claim first but just in case
        if (_usedFunds > _claimableFunds) {
            revert InterestPayment_InvalidUnclaimedAmount(
                _claimableFunds,
                _usedFunds
            );
        }

        _unclaimedAmountForPeriod = _claimableFunds - _usedFunds;
        // if reclaimed all funds for period, we can't change unclaimed balance for specific user
        uint256 totalPeriodUnusedInterest = periodAvailableInterest(
            paymentPeriodIdx_
        );
        // cover reclaimAll for period case
        if (_unclaimedAmountForPeriod > totalPeriodUnusedInterest) {
            _unclaimedAmountForPeriod = totalPeriodUnusedInterest;
        }
        // cover reclaim all contract funds case
        if (_unclaimedAmountForPeriod > _totalInterestAmountUnused) {
            _unclaimedAmountForPeriod = _totalInterestAmountUnused;
        }
    }

    // @inheritdoc IInterestPayment
    function claimedAmountForPeriod(
        address receiver_,
        uint256 periodIdx_
    ) public view returns (uint256) {
        return accountInfoByPeriods[periodIdx_][receiver_].claimedInterest;
    }

    function accountTotalClaimedAmount(
        address receiver_
    ) public view returns (uint256 totalClaimed) {
        for (uint256 i = 0; i < paymentPeriods.length; i++) {
            totalClaimed += accountInfoByPeriods[i][receiver_].claimedInterest;
        }
        return totalClaimed;
    }

    function accountTotalReclaimedAmount(
        address receiver_
    ) public view returns (uint256 totalReclaimed) {
        for (uint256 i = 0; i < paymentPeriods.length; i++) {
            totalReclaimed += accountInfoByPeriods[i][receiver_]
                .reclaimedInterest;
        }
        return totalReclaimed;
    }

    function reclaimedAmountForPeriod(
        address receiver_,
        uint256 periodIdx_
    ) public view returns (uint256) {
        return accountInfoByPeriods[periodIdx_][receiver_].reclaimedInterest;
    }

    function usedAmountForPeriod(
        address receiver_,
        uint256 periodIdx_
    ) public view returns (uint256) {
        return
            accountInfoByPeriods[periodIdx_][receiver_].claimedInterest +
            accountInfoByPeriods[periodIdx_][receiver_].reclaimedInterest;
    }

    /// @inheritdoc IInterestPayment
    function reclaimInterestForPeriod(
        address wallet,
        uint256 paymentPeriodIdx,
        uint256 amount
    )
        public
        nonReentrant
        onlyTransferAdmin
        onlyValidPeriod(paymentPeriodIdx)
        onlyValidReclaimerAddress(reclaimerAddress)
        whenNotPaused
    {
        if (
            amount > _totalInterestAmountUnused ||
            _totalInterestAmountUnused == 0
        ) {
            revert InterestPayment_NoFundsToClaim();
        }

        // Cap available claimable amount to unused funds in the period or total unused funds
        uint256 availableClaimableAmount = unclaimedAmountForPeriod(
            wallet,
            paymentPeriodIdx
        );
        if (availableClaimableAmount == 0) {
            revert InterestPayment_NoFundsToClaim();
        }
        if (availableClaimableAmount < amount) {
            revert InterestPayment_NotEnoughFundsToClaim();
        }
        if (amount > 0) {
            // claim specific amount for period (not all funds)
            availableClaimableAmount = amount;
        }

        accountInfoByPeriods[paymentPeriodIdx][wallet]
            .reclaimedInterest += availableClaimableAmount;
        paymentPeriods[paymentPeriodIdx]
            .totalReclaimedInterest += availableClaimableAmount;
        _totalInterestAmountReclaimed += availableClaimableAmount;
        _totalInterestAmountUnused -= availableClaimableAmount;
        emit Reclaimed(
            _msgSender(),
            wallet,
            availableClaimableAmount,
            paymentPeriodIdx
        );
        paymentToken_.safeTransfer(reclaimerAddress, availableClaimableAmount);
    }

