    /// @notice Batch force claim interest for specific periods for a wallet
    /// @dev Only callable by Transfer Admin. Similar to batchReclaimInterest but transfers amount to wallet instead of reclaimer
    /// @param wallet The wallet address to claim interest for
    /// @param paymentPeriodIdxs Array of payment period indices to claim interest from
    /// @param amount The maximum amount to claim, or 0 for all available funds
    function batchForceClaimInterest(
        address wallet,
        uint256[] memory paymentPeriodIdxs,
        uint256 amount
    )
        external
        nonReentrant
        onlyTransferAdmin
        whenNotPaused
    {
        uint256 currentTimestamp = block.timestamp;
        uint256 currentPaymentTimestamp = nearestInterestPaymentTimestampAt(
            currentTimestamp
        );

        uint256 totalClaimableAmount = 0;

        if (paymentPeriodIdxs.length == 0) {
            revert InterestPayment_InvalidPeriodIndex();
        }

        // Check if there are any funded periods
        if (paymentPeriods.length == 0) {
            revert InterestPayment_NoPaymentPeriods();
        }

        // Process each specified period
        for (uint256 i = 0; i < paymentPeriodIdxs.length; i++) {
            if (paymentPeriodIdxs[i] >= paymentPeriods.length) {
                revert InterestPayment_InvalidPeriodIndex();
            }
            PaymentPeriod storage period = paymentPeriods[paymentPeriodIdxs[i]];

            // Check if period is accrued (fully or partially)
            if (currentPaymentTimestamp <= period.startTimestamp) {
                // Period has not started accruing yet
                continue;
            }

            // Get available claimable amount for this period
            uint256 claimableAmount = unclaimedAmountForPeriod(
                wallet,
                paymentPeriodIdxs[i]
            );
            // Skip if no available funds to claim
            if (claimableAmount == 0) {
                continue;
            }

            // Add to total claimable amount
            totalClaimableAmount += claimableAmount;

            // Check if we've reached the amount cap (if provided)
            if (amount > 0 && totalClaimableAmount > amount) {
                // Adjust the claimable amount for this period to respect the cap
                uint256 adjustment = totalClaimableAmount - amount;
                claimableAmount -= adjustment;
                totalClaimableAmount = amount;
            }

            // Update claimed funds and unused funds
            period.totalClaimedInterest += claimableAmount;
            accountInfoByPeriods[paymentPeriodIdxs[i]][wallet]
                .claimedInterest += claimableAmount;

            emit ForceClaimed(
                _msgSender(),
                wallet,
                claimableAmount,
                paymentPeriodIdxs[i]
            );

            // If we've reached the amount cap, exit the loop
            if (amount > 0 && totalClaimableAmount >= amount) {
                break;
            }
        }

        if (amount > 0 && totalClaimableAmount < amount) {
            revert InterestPayment_NotEnoughFundsToClaim();
        }
        // Check if we have any funds to claim after processing all periods
        if (totalClaimableAmount == 0) {
            revert InterestPayment_NoFundsToClaim();
        }
        if (totalClaimableAmount > _totalInterestAmountUnused) {
            revert InterestPayment_NoFundsToClaim();
        }
        _totalInterestAmountUnused -= totalClaimableAmount;
        _totalInterestAmountClaimed += totalClaimableAmount;

        // Transfer the total claimable amount to the wallet (not to reclaimerAddress)
        paymentToken_.safeTransfer(wallet, totalClaimableAmount);
    }

    function reclaimInterestForAllRecipients(
        uint256 paymentPeriodIdx
    )
        external
        nonReentrant
        onlyTransferAdmin
        onlyValidPeriod(paymentPeriodIdx)
        onlyValidReclaimerAddress(reclaimerAddress)
    {
        if (block.timestamp < paymentPeriods[paymentPeriodIdx].endTimestamp) {
            revert InterestPayment_CannotReclaimAllForOngoingPeriod();
        }
        uint256 availableClaimableAmount = periodAvailableInterest(
            paymentPeriodIdx
        );
        if (availableClaimableAmount == 0) {
            revert InterestPayment_NoFundsToClaim();
        }
        if (_totalInterestAmountUnused < availableClaimableAmount) {
            revert InterestPayment_NoFundsToClaim();
        }

        paymentPeriods[paymentPeriodIdx]
            .totalReclaimedInterest += availableClaimableAmount;
        _totalInterestAmountReclaimed += availableClaimableAmount;
        _totalInterestAmountUnused -= availableClaimableAmount;
        emit ReclaimedAll(
            reclaimerAddress,
            availableClaimableAmount,
            paymentPeriodIdx
        );

        // Transfer the total reclaimed amount to reclaimerAddress
        paymentToken_.safeTransfer(reclaimerAddress, availableClaimableAmount);
    }

    function reclaimTotalInterest(
        uint256 amount
    )
        external
        nonReentrant
        onlyTransferAdmin
        whenNotPaused
        onlyValidAmount(amount)
        onlyValidReclaimerAddress(reclaimerAddress)
    {
        if (
            _totalInterestAmountFunded <=
            _totalInterestAmountClaimed + _totalInterestAmountReclaimed
        ) {
            revert InterestPayment_NoFundsToClaim();
        }
        if (amount > _totalInterestAmountUnused) {
            revert InterestPayment_NoFundsToClaim();
        }
        uint256 totalReclaimedAmount = amount;
        _totalInterestAmountReclaimed += totalReclaimedAmount;
        _totalInterestAmountUnused -= totalReclaimedAmount;
        emit ReclaimedAll(
            reclaimerAddress,
            totalReclaimedAmount,
            type(uint256).max
        );
        paymentToken_.safeTransfer(reclaimerAddress, totalReclaimedAmount);
    }

    function fundPrincipal(
        uint256 amount
    )
        public
        onlyTransferAdmin
        whenNotPaused
        nonReentrant
        onlyValidAmount(amount)
    {
        uint256 totalSupply = restrictedLockupToken_.totalSupply();
        uint256 claimedBalanceLeft = totalSupply -
            restrictedLockupToken_.balanceOf(address(this));
        if (claimedBalanceLeft == 0) {
            revert InterestPayment_TokenSupplyIsZero();
        }
        // validate that distributed is divisible by supply left in circulation (out of InterestPayment contract)
        uint256 expectedPrincipalTotalAmount = _totalPrincipalAmountUnused +
            amount;
        if (expectedPrincipalTotalAmount % claimedBalanceLeft != 0) {
            revert InterestPayment_PrincipalAmountNotDivisibleByTokenSupply();
        }

        _fundedPrincipalAmount += amount;
        _totalPrincipalAmountUnused += amount;

        emit PrincipalFunded(_msgSender(), amount);

        uint256 _balanceBefore = paymentToken_.balanceOf(address(this));
        paymentToken_.safeTransferFrom(_msgSender(), address(this), amount);
        uint256 _balanceAfter = paymentToken_.balanceOf(address(this));
        if (_balanceBefore + amount != _balanceAfter) {
            revert InterestPayment_InvalidFeeApplied();
        }
    }

    function _claimPrincipal(
        address target,
        uint256 amount
    ) internal {
        if (_totalPrincipalAmountUnused == 0) {
            revert InterestPayment_NoFundsToClaim();
        }
        if (block.timestamp < interestAccrualEndTimestamp) {
            revert InterestPayment_MaturityNotReached();
        }

        uint256 accountBalance = restrictedLockupToken_.balanceOf(target);
        if (accountBalance == 0) {
            revert InterestPayment_NoFundsToClaim();
        }
        uint256 allowedPrincipalAmount = accountBalance *
            principalAmountPerToken_;
        if (_totalPrincipalAmountUnused < allowedPrincipalAmount) {
            revert InterestPayment_NotEnoughFundedPrincipal();
        }

        // Handle amount parameter: 0 means claim all, >0 means claim specific amount
        uint256 principalToClaim = allowedPrincipalAmount;
        uint256 tokensToBurn = accountBalance;
        if (amount > 0) {
            // Claim specific amount
            if (amount > allowedPrincipalAmount) {
                revert InterestPayment_NotEnoughFundedPrincipal();
            }
            principalToClaim = amount;
            tokensToBurn = amount / principalAmountPerToken_;
            // Ensure exact division
            if (tokensToBurn * principalAmountPerToken_ != amount) {
                revert InterestPayment_PrincipalAmountNotDivisibleByTokenSupply();
            }
        }

        _totalPrincipalAmountUnused -= principalToClaim;
        _totalPrincipalAmountClaimed += principalToClaim;

        restrictedLockupToken_.softBurn(target, tokensToBurn);
        emit PrincipalClaimed(target, principalToClaim);

        paymentToken_.safeTransfer(target, principalToClaim);
    }

    function claimPrincipal(
        uint256 amount
    ) external nonReentrant whenNotPaused {
        address sender = _msgSender();
        _claimPrincipal(sender, amount);
    }

    /**
     * @notice Force claim principal for a specific wallet address
     * @dev Only callable by Transfer Admin. Similar to claimPrincipal but claims on behalf of a wallet address
     * @param wallet The wallet address to claim principal for
     * @param amount The amount to claim, or 0 for all available principal
     */
    function forceClaimPrincipal(
        address wallet,
        uint256 amount
    ) external nonReentrant onlyTransferAdmin whenNotPaused {
        _claimPrincipal(wallet, amount);
    }

    function reclaimPrincipal(
        uint256 amount
    )
        external
        nonReentrant
        onlyTransferAdmin
        onlyValidReclaimerAddress(reclaimerAddress)
    {
        if (_totalPrincipalAmountUnused == 0) {
            revert InterestPayment_NoFundsToClaim();
        }

        // Handle amount parameter: 0 means reclaim all, >0 means reclaim specific amount
        uint256 principalToReclaim = _totalPrincipalAmountUnused;
        if (amount > 0) {
            // Reclaim specific amount
            if (amount > _totalPrincipalAmountUnused) {
                revert InterestPayment_NotEnoughFundedPrincipal();
            }
            principalToReclaim = amount;
        }

        _totalPrincipalAmountUnused -= principalToReclaim;
        _totalPrincipalAmountReclaimed += principalToReclaim;

        emit PrincipalReclaimed(_msgSender(), principalToReclaim);
        paymentToken_.safeTransfer(reclaimerAddress, principalToReclaim);
    }

    function fundedPrincipalAmount() public view returns (uint256) {
        return _fundedPrincipalAmount;
    }

    function reclaimedPrincipalAmount() public view returns (uint256) {
        return _totalPrincipalAmountReclaimed;
    }

    function claimedPrincipalAmount() public view returns (uint256) {
        return _totalPrincipalAmountClaimed;
    }

    function totalAvailablePrincipalAmount() public view returns (uint256) {
        return _totalPrincipalAmountUnused;
    }

    function availablePrincipalAmount(
        address account
    ) public view returns (uint256) {
        uint256 accountBalance = restrictedLockupToken_.balanceOf(account);
        if (accountBalance == 0) {
            return 0;
        }
        uint256 allowedPrincipalAmount = accountBalance *
            principalAmountPerToken_;
        if (_totalPrincipalAmountUnused < allowedPrincipalAmount) {
            return _totalPrincipalAmountUnused;
        }
        return allowedPrincipalAmount;
    }

    /// @inheritdoc IInterestPayment
    function earlyRepayment(uint256 timestamp) external onlyContractAdminOrTransferAdmin {
        if (timestamp < block.timestamp) {
            revert InterestPayment_InvalidTimestamp();
        }

        _pausePaymentAfterTimestamp(timestamp);
        _updateInterestAccrualEnd(timestamp);

        emit EarlyRepayment(_msgSender(), timestamp);
    }

    /// @notice Force claim interest for an account for a specific period
    /// @dev Only callable by Transfer Admin. Similar to claimInterestForPeriod but claims on behalf of a wallet address
    /// @param wallet The wallet address to claim interest for
    /// @param paymentPeriodIdx The payment period index to claim interest for
    /// @param amount The amount to claim, capped at available claimable amount
    function forceClaimForPeriod(
        address wallet,
        uint256 paymentPeriodIdx,
        uint256 amount
    )
        external
        nonReentrant
        onlyTransferAdmin
        onlyValidPeriod(paymentPeriodIdx)
        whenNotPaused
    {
        _claimInterestForPeriod(wallet, paymentPeriodIdx, amount, true);
    }

    /// @inheritdoc IInterestPayment
    function restrictedLockupToken() external view returns (address) {
        return address(restrictedLockupToken_);
    }

    /// @inheritdoc IInterestPayment
    function paymentToken() external view returns (address) {
        return address(paymentToken_);
    }

    /// @inheritdoc IInterestPayment
    function principalAmountPerToken() external view returns (uint256) {
        return principalAmountPerToken_;
    }

    // =============================================================================
    // DIVIDEND FUNCTIONALITY (Adapted from Dividends Contract)
    // =============================================================================

    /// @inheritdoc IDividends
    function totalAwardedBalanceAt(
        address token_,
        address receiver_,
        uint256 timestamp_
    ) public view override onlyValidDividendSnapshotId(timestamp_) returns (uint256) {
        return
            unclaimedBalanceAt(token_, receiver_, timestamp_) +
            claimedBalanceAt(token_, receiver_, timestamp_);
    }

    /**
     * @dev Check if amount is divisible into totalSupply at timestamp
     * @param amount_ Amount to check divisibility
     * @param timestamp_ Timestamp for historical data
     * @return isDivisible_ boolean. True if amount is valid and divisible by totalSupply.
     */
    function isAmountDivisible(
        uint256 amount_,
        uint256 timestamp_
    ) public view returns (bool isDivisible_) {
        uint256 totalSupplyAtTimestamp = snapshotPeriods.getPastTotalSupply(
            address(restrictedLockupToken_),
            timestamp_
        );
        isDivisible_ = amount_ % totalSupplyAtTimestamp == 0;
    }

    /// @inheritdoc IDividends
    function claimedBalanceAt(
        address token_,
        address receiver_,
        uint256 timestamp_
    ) public view override onlyValidDividendSnapshotId(timestamp_) returns (uint256) {
        return dividendClaimedFunds[timestamp_][token_][receiver_];
    }

    /// @inheritdoc IDividends
    function claimDividend(
        address token_,
        uint256 timestamp_,
        uint256 amount_
    )
        public
        override
        nonReentrant
        onlyValidDividendSnapshotId(timestamp_)
        whenNotPaused
    {
        uint256 _unclaimedBalance = unclaimedBalanceAt(
            token_,
            _msgSender(),
            timestamp_
        );

        if (amount_ == 0) {
            amount_ = _unclaimedBalance;
        }
        if (amount_ > _unclaimedBalance) {
            revert InterestPayment_NotEnoughFundsToClaim();
        }

        if (_unclaimedBalance == 0) {
            revert InterestPayment_NoRemainingUnclaimedDividendBalance();
        }

        dividendClaimedFunds[timestamp_][token_][_msgSender()] += amount_;
        fundedDividends[timestamp_][token_].unusedFunds -= amount_;

        emit DividendClaimed(_msgSender(), token_, amount_, timestamp_);

        IERC20(token_).safeTransfer(_msgSender(), amount_);
    }

    /**
     * @dev Reclaim dividends for a specific target address and send to contract reclaimer
     * Can only be called by transfer admin
     * @param token_ ERC-20 token address
     * @param targetAddress_ Address to reclaim dividends for
     * @param timestamp_ timestamp for dividend distribution
     */
    function reclaimDividend(
        address token_,
        address targetAddress_,
        uint256 timestamp_,
        uint256 amount_
    )
        external
        override
        nonReentrant
        onlyTransferAdmin
        onlyValidDividendSnapshotId(timestamp_)
        whenNotPaused
        onlyValidReclaimerAddress(reclaimerAddress)
    {
        uint256 _unclaimedBalance = unclaimedBalanceAt(
            token_,
            targetAddress_,
            timestamp_
        );

        if (amount_ == 0) {
            amount_ = _unclaimedBalance;
        }
        if (amount_ > _unclaimedBalance) {
            revert InterestPayment_NotEnoughFundsToClaim();
        }

        if (_unclaimedBalance == 0) {
            revert InterestPayment_NoRemainingUnclaimedDividendBalance();
        }

        // Mark the dividends as claimed for the target address
        dividendClaimedFunds[timestamp_][token_][targetAddress_] += amount_;
        fundedDividends[timestamp_][token_].unusedFunds -= amount_;

        emit DividendReclaimed(_msgSender(), targetAddress_, token_, amount_, timestamp_);

        // Transfer to contract reclaimer address
        IERC20(token_).safeTransfer(reclaimerAddress, amount_);
    }

    /// @inheritdoc IDividends
    function unclaimedBalanceAt(
        address token_,
        address receiver_,
        uint256 timestamp_
    ) public view override onlyValidDividendSnapshotId(timestamp_) returns (uint256 _unclaimedBalanceAt) {
        uint256 _claimableFunds = _claimableFundsAt(
            token_,
            receiver_,
            timestamp_
        );
        uint256 _claimedFunds = claimedBalanceAt(
            token_,
            receiver_,
            timestamp_
        );
        if (_claimedFunds > _claimableFunds) {
            revert InterestPayment_InvalidUnclaimedDividendBalance(
                _claimableFunds,
                _claimedFunds
            );
        }

        _unclaimedBalanceAt = _claimableFunds - _claimedFunds;
    }

    /// @inheritdoc IDividends
    function batchClaimDividend(
        address token_,
        uint256[] calldata timestamps_,
        uint256[] calldata amounts_
    ) external override whenNotPaused {
        uint256 _timestampsLength = timestamps_.length;
        if (_timestampsLength != amounts_.length) {
            revert InterestPayment_InvalidArrayLengths();
        }
        for (uint256 i; i < _timestampsLength; ++i) {
            claimDividend(token_, timestamps_[i], amounts_[i]);
        }
    }

    /// @inheritdoc IDividends
    function fundDividend(
        address token_,
        uint256 amount_,
        uint256 timestamp_
    )
        external
        override
        nonReentrant
        onlyTransferAdmin
        onlyValidDividendSnapshotId(timestamp_)
        whenNotPaused
    {
        if (amount_ == 0) {
            revert InterestPayment_InvalidAmount();
        }
        if (token_ == address(0)) {
            revert InterestPayment_InvalidDividendTokenAddress();
        }
        IERC20 _paymentToken = IERC20(token_);
        uint8 _restrictedLockupTokenDecimals = restrictedLockupToken_.decimals();
        if (_restrictedLockupTokenDecimals > ERC20(token_).decimals()) {
            revert InterestPayment_InvalidTokenDecimals(
                _restrictedLockupTokenDecimals
            );
        }

        uint256 _totalSupply = snapshotPeriods.getPastTotalSupply(
            address(restrictedLockupToken_),
            timestamp_
        );
        if (_totalSupply == 0) {
            revert InterestPayment_ZeroTotalSupply();
        }
        if (amount_ % _totalSupply != 0) {
            revert InterestPayment_IndivisibleAmount(amount_, _totalSupply);
        }

        uint256 _dividendPerSecurity = amount_ / _totalSupply;

        fundedDividends[timestamp_][token_].unusedFunds += amount_;
        fundedDividends[timestamp_][token_].totalFunds += amount_;
        fundedDividends[timestamp_][token_].dividendPerSecurity =
            fundedDividends[timestamp_][token_].dividendPerSecurity +
            _dividendPerSecurity;

        emit DividendFunded(_msgSender(), token_, amount_, timestamp_);
        uint256 _balanceBefore = _paymentToken.balanceOf(address(this));
        _paymentToken.safeTransferFrom(_msgSender(), address(this), amount_);
        uint256 _balanceAfter = _paymentToken.balanceOf(address(this));
        if (_balanceBefore + amount_ != _balanceAfter) {
            revert InterestPayment_InvalidFeeApplied();
        }
    }

    /**
     * @dev Reclaim ERC-20 tokens from a specific dividend snapshot
     * Can only be done if no dividends have been claimed for this snapshot (unusedFunds == totalFunds)
     * If amount is 0, reclaims all available funds
     * @param token_ ERC-20 token address
     * @param amount_ amount of tokens to reclaim (0 = reclaim all)
     * @param timestamp_ timestamp for dividend distribution
     */
    function reclaimTotalDividend(
        address token_,
        uint256 amount_,
        uint256 timestamp_
    )
        external
        override
        nonReentrant
        onlyTransferAdmin
        onlyValidDividendSnapshotId(timestamp_)
        whenNotPaused
        onlyValidReclaimerAddress(reclaimerAddress)
    {
        FundedDividends storage _fundedDividend = fundedDividends[timestamp_][token_];

        // Check if any dividends have been claimed (unusedFunds should equal totalFunds if no claims)
        if (_fundedDividend.unusedFunds != _fundedDividend.totalFunds) {
            revert InterestPayment_DividendsAlreadyClaimed();
        }

        // Check if there are any funds to reclaim
        if (_fundedDividend.unusedFunds == 0) {
            revert InterestPayment_NoFundsToClaim();
        }

        uint256 _amountToReclaim;
        if (amount_ == 0) {
            // Reclaim all funds
            _amountToReclaim = _fundedDividend.totalFunds;
        } else {
            // Validate amount is not greater than available funds
            if (amount_ > _fundedDividend.totalFunds) {
                revert InterestPayment_NotEnoughFundsToClaim();
            }

            // Validate divisibility (same as fundDividend)
            uint256 _totalSupply = snapshotPeriods.getPastTotalSupply(
                address(restrictedLockupToken_),
                timestamp_
            );
            // it is always greater than 0 because we can't fund dividend with 0 supply
            // so it fails on InterestPayment_NoFundsToClaim
            if (amount_ % _totalSupply != 0) {
                revert InterestPayment_IndivisibleAmount(amount_, _totalSupply);
            }

            _amountToReclaim = amount_;
        }

        // Calculate the dividend per security to subtract
        uint256 _dividendPerSecurityToSubtract = _amountToReclaim / snapshotPeriods.getPastTotalSupply(
            address(restrictedLockupToken_),
            timestamp_
        );

        // Update dividend tracking
        _fundedDividend.unusedFunds -= _amountToReclaim;
        _fundedDividend.totalFunds -= _amountToReclaim;
        _fundedDividend.dividendPerSecurity -= _dividendPerSecurityToSubtract;

        emit DividendReclaimed(_msgSender(), address(this), token_, _amountToReclaim, timestamp_);

        // Transfer tokens back to the caller
        IERC20(token_).safeTransfer(reclaimerAddress, _amountToReclaim);
    }

    /// @inheritdoc IDividends
    function tokensAt(
        address token_,
        uint256 timestamp_
    ) external view override onlyValidDividendSnapshotId(timestamp_) returns (uint256) {
        return fundedDividends[timestamp_][token_].unusedFunds;
    }

    /**
     * @dev Proxy function for restricted token to retrieve totalSupply at timestamp
     * @param timestamp_ Timestamp for historical data
     * @return totalSupply at timestamp
     */
    function totalSupplyAt(
        uint256 timestamp_
    ) external view onlyValidDividendSnapshotId(timestamp_) returns (uint256) {
        return snapshotPeriods.getPastTotalSupply(address(restrictedLockupToken_), timestamp_);
    }

    /**
     * @dev Proxy function for restricted token to retrieve balanceOf address at timestamp
     * @param sender_ address to check balance
     * @param timestamp_ timestamp for historical data
     * @return balance of address at timestamp
     */
    function balanceOfAt(
        address sender_,
        uint256 timestamp_
    ) external view onlyValidDividendSnapshotId(timestamp_) returns (uint256) {
        return snapshotPeriods.getPastBalanceOf(address(restrictedLockupToken_), sender_, timestamp_);
    }

    /// @inheritdoc IDividends
    function fundsAt(
        address token_,
        uint256 timestamp_
    ) external view override onlyValidDividendSnapshotId(timestamp_) returns (uint256) {
        return fundedDividends[timestamp_][token_].totalFunds;
    }

    /**
     * @dev _claimableFundsAt private function to calculate claimable funds for receiver at a given timestamp
     * @param token_ ERC20 token address
     * @param receiver_ address of receiver
     * @param timestamp_ Timestamp for historical data
     * @return claimable funds for receiver at timestamp
     */
    function _claimableFundsAt(
        address token_,
        address receiver_,
        uint256 timestamp_
    ) private view returns (uint256) {
        return (fundedDividends[timestamp_][token_].dividendPerSecurity *
            snapshotPeriods.getPastBalanceOf(address(restrictedLockupToken_), receiver_, timestamp_));
    }
}

contracts/PurchaseContract.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.8.28;

import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {ERC2771Context} from "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {Context} from "@openzeppelin/contracts/utils/Context.sol";
import {IInterestPayment} from "./interfaces/IInterestPayment.sol";
import {RestrictedLockupToken} from "./RestrictedLockupToken.sol";

/**
 * @title PurchaseContract
 * @notice Contract for handling token purchases with USDC payments and automatic distribution
 * @dev Implements atomic purchase transactions with originator payments, admin fees, and token minting
 */
contract PurchaseContract is Ownable, ERC2771Context, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ============================================
    // EVENTS
    // ============================================

    event PurchaseExecuted(
        string indexed purchaseId,
        address indexed payerAddress,
        address indexed tokenRecipientAddress,
        address authorityAddress,
        uint256 originatorPurchaseAmount,
        uint256 prefundedInterestAmount,
        uint256 adminFeeExcludingPrefundedInterestAmount,
        uint256 mintAmount,
        address originatorAddress
    );

    event PurchaseCanceled(
        address indexed authorityAddress,
        address indexed paymentTokenAddress,
        address indexed canceledPurchaseWallet,
        uint256 amount
    );

    event AutomationAdminUpdated(address indexed oldAdmin, address indexed newAdmin);
    event AdminFeeWalletUpdated(address indexed oldWallet, address indexed newWallet);
    event CanceledPurchaseWalletUpdated(address indexed oldWallet, address indexed newWallet);
    event OriginatorPaymentWalletUpdated(address indexed oldWallet, address indexed newWallet);

    // ============================================
    // ERRORS
    // ============================================

    error PurchaseContract_InvalidZeroAddress();
    error PurchaseContract_InvalidPaymentToken();
    error PurchaseContract_InvalidTokenContract();
    error PurchaseContract_OnlyAutomationAdmin();
    error PurchaseContract_PurchaseIdAlreadyUsed();
    error PurchaseContract_PurchaseIdNotUsed();
    error PurchaseContract_InvalidAmount();
    error PurchaseContract_DecimalPrecisionMismatch();
    error PurchaseContract_TransferFailed();
    error PurchaseContract_AdminFeeWalletNotSet();
    error PurchaseContract_CanceledPurchaseWalletNotSet();
    error PurchaseContract_OriginatorPaymentWalletNotSet();
    error PurchaseContract_TokenRecipientAmlKycNotPassed();
    error PurchaseContract_PayerAmlKycNotPassed();
    error PurchaseContract_InvalidTotalAmount();
    error PurchaseContract_RemainderNotZero();
    error PurchaseContract_InterestPaymentNotConfigured();

    // ============================================
    // STATE VARIABLES
    // ============================================

    /// @notice Interest payment contract for funding interest
    IInterestPayment public immutable interestPayment;
    RestrictedLockupToken public immutable tokenContract;

    /// @notice USDC token contract
    IERC20 public immutable paymentToken;

    /// @notice Automation admin address that can execute purchases and cancellations
    address public automationAdmin;

    /// @notice Admin fee wallet address
    address public adminFeeWallet;

    /// @notice Canceled purchase wallet address
    address public canceledPurchaseWallet;

    /// @notice Originator payment wallet address
    address public originatorPaymentWallet;

    /// @notice Mapping to track used purchase IDs
    mapping(string => bool) public usedPurchaseIds;

    // ============================================
    // MODIFIERS
    // ============================================

    modifier onlyAutomationAdmin() {
        if (_msgSender() != automationAdmin) {
            revert PurchaseContract_OnlyAutomationAdmin();
        }
        _;
    }

    modifier validAddress(address addr) {
        if (addr == address(0)) {
            revert PurchaseContract_InvalidZeroAddress();
        }
        _;
    }

    modifier validAmount(uint256 amount) {
        if (amount == 0) {
            revert PurchaseContract_InvalidAmount();
        }
        _;
    }

    // ============================================
    // CONSTRUCTOR
    // ============================================

    constructor(
        address contractAdmin_,
        address trustedForwarder_,
        address tokenContract_,
        address interestPayment_,
        address paymentToken_
    ) 
        Ownable(contractAdmin_)
        ERC2771Context(trustedForwarder_)
        validAddress(contractAdmin_)
        validAddress(trustedForwarder_)
        validAddress(tokenContract_)
        validAddress(paymentToken_)
    {
        if (interestPayment_ != address(0)) {
            interestPayment = IInterestPayment(interestPayment_);
            if (interestPayment.paymentToken() != paymentToken_) {
                revert PurchaseContract_InvalidPaymentToken();
            }
            if (interestPayment.restrictedLockupToken() != tokenContract_) {
                revert PurchaseContract_InvalidTokenContract();
            }
        }
        // Note: interestPayment can be address(0) if contract is deployed without interest functionality

        paymentToken = IERC20(paymentToken_);
        tokenContract = RestrictedLockupToken(tokenContract_);
    }

    // ============================================
    // ADMIN FUNCTIONS
    // ============================================

    /**
     * @notice Update automation admin address
     * @param newAutomationAdmin_ New automation admin address
     */
    function updateAutomationAdmin(address newAutomationAdmin_) 
        external 
        onlyOwner 
        validAddress(newAutomationAdmin_) 
    {
        address oldAdmin = automationAdmin;
        automationAdmin = newAutomationAdmin_;
        emit AutomationAdminUpdated(oldAdmin, newAutomationAdmin_);
    }

    /**
     * @notice Update admin fee wallet address
     * @param newAdminFeeWallet_ New admin fee wallet address
     */
    function updateAdminFeeWallet(address newAdminFeeWallet_) 
        external 
        onlyOwner 
        validAddress(newAdminFeeWallet_) 
    {
        address oldWallet = adminFeeWallet;
        adminFeeWallet = newAdminFeeWallet_;
        emit AdminFeeWalletUpdated(oldWallet, newAdminFeeWallet_);
    }

    /**
     * @notice Update canceled purchase wallet address
     * @param newCanceledPurchaseWallet_ New canceled purchase wallet address
     */
    function updateCanceledPurchaseWallet(address newCanceledPurchaseWallet_) 
        external 
        onlyOwner 
        validAddress(newCanceledPurchaseWallet_) 
    {
        address oldWallet = canceledPurchaseWallet;
        canceledPurchaseWallet = newCanceledPurchaseWallet_;
        emit CanceledPurchaseWalletUpdated(oldWallet, newCanceledPurchaseWallet_);
    }

    /**
     * @notice Update originator payment wallet address
     * @param newOriginatorPaymentWallet_ New originator payment wallet address
     */
    function updateOriginatorPaymentWallet(address newOriginatorPaymentWallet_) 
        external 
        onlyOwner 
        validAddress(newOriginatorPaymentWallet_) 
    {
        address oldWallet = originatorPaymentWallet;
        originatorPaymentWallet = newOriginatorPaymentWallet_;
        emit OriginatorPaymentWalletUpdated(oldWallet, newOriginatorPaymentWallet_);
    }

    // ============================================
    // PURCHASE FUNCTIONS
    // ============================================

    struct PurchaseParams {
        string purchaseId;
        address payerAddress;
        address tokenRecipientAddress;
        uint256 originatorPurchaseAmount;
        uint256 mintAmount;
        uint256 adminFeeAmount;
        uint256 totalAmount;
    }

     struct PurchaseParamsWithInterest {
        string purchaseId;
        address payerAddress;
        address tokenRecipientAddress;
        uint256 mintAmount;
        uint256 originatorPurchaseAmount;
        uint256 prefundedInterestAmount;
        uint256 adminFeeExcludingPrefundedInterestAmount;
        uint256 totalAmount;
    }

    /**
     * @notice Execute a token purchase with USDC payment and interest funding
     * @param params Purchase parameters
     */
    function executePurchaseWithInterest(
        PurchaseParamsWithInterest memory params
    ) 
        external 
        nonReentrant 
        onlyAutomationAdmin
        validAddress(params.payerAddress)
        validAddress(params.tokenRecipientAddress)
    {
        // Validation: Ensure interest payment contract is configured when using this function
        if (address(interestPayment) == address(0)) {
            revert PurchaseContract_InterestPaymentNotConfigured();
        }
        // Validation: Check unique purchaseId
        if (usedPurchaseIds[params.purchaseId]) {
            revert PurchaseContract_PurchaseIdAlreadyUsed();
        }

        // Validation: Ensure required addresses are set
        if (adminFeeWallet == address(0)) {
            revert PurchaseContract_AdminFeeWalletNotSet();
        }
        if (originatorPaymentWallet == address(0)) {
            revert PurchaseContract_OriginatorPaymentWalletNotSet();
        }
        if (params.mintAmount == 0) {
            revert PurchaseContract_InvalidAmount();
        }
        if (params.totalAmount != params.originatorPurchaseAmount + params.prefundedInterestAmount + params.adminFeeExcludingPrefundedInterestAmount) {
            revert PurchaseContract_InvalidTotalAmount();
        }
        if (!tokenContract.isAmlKycPassed(params.tokenRecipientAddress)) {
            revert PurchaseContract_TokenRecipientAmlKycNotPassed();
        }
        if (!tokenContract.isAmlKycPassed(params.payerAddress)) {
            revert PurchaseContract_PayerAmlKycNotPassed();
        }

        // Step 2: Transfer originator amount to originator address
        if (params.originatorPurchaseAmount > 0) {
            paymentToken.safeTransfer(originatorPaymentWallet, params.originatorPurchaseAmount);
        }

        // Step 3: Fund interest in InterestPayment contract
        if (params.prefundedInterestAmount > 0) {
            paymentToken.safeIncreaseAllowance(address(interestPayment), params.prefundedInterestAmount);
            interestPayment.fundInterest(params.prefundedInterestAmount);
        }

        // Step 4: Transfer admin fee to admin fee wallet
        if (params.adminFeeExcludingPrefundedInterestAmount > 0) {
            paymentToken.safeTransfer(adminFeeWallet, params.adminFeeExcludingPrefundedInterestAmount);
        }

        // Step 5: Mint tokens to recipient
        tokenContract.mint(params.tokenRecipientAddress, params.mintAmount);

        // Step 6: Mark purchase as completed
        usedPurchaseIds[params.purchaseId] = true;

        // Step 7: Emit event
        emit PurchaseExecuted(
            params.purchaseId,
            params.payerAddress,
            params.tokenRecipientAddress,
            _msgSender(),
            params.originatorPurchaseAmount,
            params.prefundedInterestAmount,
            params.adminFeeExcludingPrefundedInterestAmount,
            params.mintAmount,
            originatorPaymentWallet
        );
    }

    /**
     * @notice Execute a token purchase with USDC payment (without interest funding)
     * @dev This function can be used when the contract is deployed without an interest payment contract
     * @param params Purchase parameters (prefundedInterestAmount will be ignored)
     */
    function executePurchase(
        PurchaseParams memory params
    ) 
        external 
        nonReentrant 
        onlyAutomationAdmin
        validAddress(params.payerAddress)
        validAddress(params.tokenRecipientAddress)
    {
        // Validation: Check unique purchaseId
        if (usedPurchaseIds[params.purchaseId]) {
            revert PurchaseContract_PurchaseIdAlreadyUsed();
        }

        // Validation: Ensure required addresses are set
        if (adminFeeWallet == address(0)) {
            revert PurchaseContract_AdminFeeWalletNotSet();
        }
        if (originatorPaymentWallet == address(0)) {
            revert PurchaseContract_OriginatorPaymentWalletNotSet();
        }
        if (!tokenContract.isAmlKycPassed(params.tokenRecipientAddress)) {
            revert PurchaseContract_TokenRecipientAmlKycNotPassed();
        }
        if (!tokenContract.isAmlKycPassed(params.payerAddress)) {
            revert PurchaseContract_PayerAmlKycNotPassed();
        }

        // For executePurchase (without interest), we expect prefundedInterestAmount to be 0
        // and totalAmount to equal originatorPurchaseAmount + adminFeeExcludingPrefundedInterestAmount
        if (params.totalAmount != params.originatorPurchaseAmount + params.adminFeeAmount) {
            revert PurchaseContract_InvalidTotalAmount();
        }

        // Step 2: Transfer originator amount to originator address
        if (params.originatorPurchaseAmount > 0) {
            paymentToken.safeTransfer(originatorPaymentWallet, params.originatorPurchaseAmount);
        }

        // Step 3: Skip interest funding since no interest payment contract is configured
        // params.prefundedInterestAmount is ignored in this function

        // Step 4: Transfer admin fee to admin fee wallet
        if (params.adminFeeAmount > 0) {
            paymentToken.safeTransfer(adminFeeWallet, params.adminFeeAmount);
        }

        // Step 5: Mint tokens to recipient
        // When no interest payment contract is configured, we need to calculate mint amount differently
        // For now, we'll use a 1:1 ratio or could use a configurable ratio
        if (params.mintAmount == 0) {
            revert PurchaseContract_InvalidAmount();
        }
        tokenContract.mint(params.tokenRecipientAddress, params.mintAmount);

        // Step 6: Mark purchase as completed
        usedPurchaseIds[params.purchaseId] = true;

        // Step 7: Emit event (prefundedInterestAmount will be 0 for this function)
        emit PurchaseExecuted(
            params.purchaseId,
            params.payerAddress,
            params.tokenRecipientAddress,
            _msgSender(),
            params.originatorPurchaseAmount,
            0, // No prefunded interest amount
            params.adminFeeAmount,
            params.mintAmount,
            originatorPaymentWallet
        );
    }

    /**
     * @notice Cancel a purchase and transfer amount to canceled purchase wallet
     * @param paymentTokenAddress_ The payment token address to cancel
     * @param amount_ Amount to transfer to canceled purchase wallet
     */
    function cancelPurchase(
        address paymentTokenAddress_,
        uint256 amount_
    ) 
        external 
        nonReentrant 
        onlyAutomationAdmin
        validAmount(amount_)
    {
        // Validation: Ensure canceled purchase wallet is set
        if (canceledPurchaseWallet == address(0)) {
            revert PurchaseContract_InvalidZeroAddress();
        }

        // Transfer amount to canceled purchase wallet
        IERC20(paymentTokenAddress_).safeTransfer(canceledPurchaseWallet, amount_);

        emit PurchaseCanceled(_msgSender(), paymentTokenAddress_, canceledPurchaseWallet, amount_);
    }

    // ============================================
    // VIEW FUNCTIONS
    // ============================================

    /**
     * @notice Check if a purchase ID has been used
     * @param purchaseId_ The purchase ID to check
     * @return Whether the purchase ID has been used
     */
    function isPurchaseIdUsed(string calldata purchaseId_) external view returns (bool) {
        return usedPurchaseIds[purchaseId_];
    }

    // ============================================
    // ERC2771 OVERRIDES
    // ============================================

    function _msgSender()
        internal
        view
        override(Context, ERC2771Context)
        returns (address sender)
    {
        return ERC2771Context._msgSender();
    }

    function _msgData()
        internal
        view
        override(Context, ERC2771Context)
        returns (bytes calldata)
    {
        return ERC2771Context._msgData();
    }

    function _contextSuffixLength()
        internal
        view
        override(Context, ERC2771Context)
        returns (uint256)
    {
        return ERC2771Context._contextSuffixLength();
    }
}

contracts/RestrictedLockupToken.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.8.28;

import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC165, ERC165} from "@openzeppelin/contracts/utils/introspection/ERC165.sol";
import {ERC2771Context} from "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import {Context} from "@openzeppelin/contracts/utils/Context.sol";
import {BitScan} from "@solidity-bits/contracts/BitScan.sol";
import {ITransferRules} from "./interfaces/ITransferRules.sol";
import {ISnapshotPeriods} from "./interfaces/ISnapshotPeriods.sol";
import {IIdentityRegistry} from "./interfaces/IIdentityRegistry.sol";
import {IERC1404} from "./interfaces/IERC1404.sol";
import {SnapshotPeriods} from "./SnapshotPeriods.sol";
import {VestingMath} from "./libraries/VestingMath.sol";
import {BitManipulationLib} from "./libraries/BitManipulationLib.sol";
import {Storage} from "./Storage.sol";
import {IAccessControl} from "./interfaces/IAccessControl.sol";
import {IRestrictedLockupTokenExtension} from "./interfaces/IRestrictedLockupTokenExtension.sol";
import "./AccessControlErrors.sol"; // Import for access to errors

/**
  @title A smart contract for unlocking tokens based on a release schedule with multi-type token support
  @author By CoMakery, Inc., Upside, Republic
  @dev When deployed the contract is as a proxy for a single token that it creates release schedules for
      it implements the ERC20 token interface to integrate with wallets but it is not an independent token.
      The token must implement a burn function.
      Enhanced with multi-type token functionality for different regulatory classifications.
*/
contract RestrictedLockupToken is
    Storage,
    ERC20,
    ReentrancyGuard,
    ERC165,
    ERC2771Context
{
    using BitScan for uint256;
    using BitManipulationLib for uint256;
    /// @dev Struct to hold constructor parameters to avoid stack too deep issues
    struct ConstructorParams {
        address transferRules;
        address accessControl; // external access control
        address snapshotPeriods;
        address trustedForwarder;
        address identityRegistry;
        address restrictedLockupTokenManagementExtension;
        address restrictedLockupTokenExtension;
        string symbol;
        string name;
        uint8 decimals;
        uint256 maxTotalSupply;
        uint256 minTimelockAmount;
        uint256 maxReleaseDelay;
        bool recordMintTimestamp;
    }

    struct TransferParams {
        address from;
        address to;
        IIdentityRegistry.IdentityInfo recipientIdentity;
        bool isAmlKycPassed;
        bool validateRestrictions;
        uint256 remainingAmount;
        uint256 bitmaskToSet;
        uint256 bitmaskToClear;
    }

    uint8 private immutable _decimals;

    /**
     * @dev Configure deployment for a specific token with release schedule security parameters
     * @dev The symbol should end with " Unlock" & be less than 11 characters for MetaMask "custom token" compatibility
     */
    constructor(
        ConstructorParams memory params
    )
        ERC20(params.name, params.symbol)
        ERC2771Context(params.trustedForwarder)
    {
        // Restricted Token
        if (bytes(params.name).length == 0) {
            revert RestrictedLockupToken_InvalidName();
        }
        if (bytes(params.symbol).length == 0) {
            revert RestrictedLockupToken_InvalidSymbol();
        }
        if (params.transferRules == address(0)) {
            revert RestrictedLockupToken_InvalidTransferRules();
        }
        if (params.accessControl == address(0)) {
            revert RestrictedLockupToken_InvalidAccessControl();
        }
        if (params.trustedForwarder == address(0)) {
            revert RestrictedLockupToken_InvalidTrustedForwarder();
        }
        if (params.identityRegistry == address(0)) {
            revert RestrictedLockupToken_InvalidIdentityRegistry();
        }
        if (params.restrictedLockupTokenManagementExtension == address(0)) {
            revert RestrictedLockupToken_InvalidRestrictedLockupTokenManagementExtension();
        }
        if (params.restrictedLockupTokenExtension == address(0)) {
            revert RestrictedLockupToken_InvalidRestrictedLockupTokenExtension();
        }
        if (params.snapshotPeriods == address(0)) {
            snapshotsEnabled = false;
        } else {
            snapshotsEnabled = true;
        }
        // Token Lockup
        if (params.minTimelockAmount == 0) {
            revert RestrictedLockupToken_InvalidMinTimelockAmount();
        }
        if (params.maxTotalSupply > _maxSafeSupply()) {
            revert RestrictedLockupToken_MaxTotalSupplyTooLarge();
        }
        // Transfer rules can be swapped out for a new contract inheriting from the ITransferRules interface
        transferRules = ITransferRules(params.transferRules);
        snapshotPeriods = ISnapshotPeriods(params.snapshotPeriods);
        identityRegistry = IIdentityRegistry(params.identityRegistry);
        accessControl = IAccessControl(params.accessControl);
        restrictedLockupTokenManagementExtension = params.restrictedLockupTokenManagementExtension;
        restrictedLockupTokenExtension = params.restrictedLockupTokenExtension;

        maxTotalSupply = params.maxTotalSupply;
        _decimals = params.decimals;

        minTimelockAmount = params.minTimelockAmount;
        maxReleaseDelay = params.maxReleaseDelay;
        recordMintTimestamp = params.recordMintTimestamp;
        deploymentDay = VestingMath.toMidnightTimestamp(block.timestamp);

        // Calculate and set immutable slotsPerWord based on maxTotalSupply (already in basis units)
        slotsPerWord = BitManipulationLib.calculateSlotsPerWord(maxTotalSupply);
        uint256 slotsPerWordExtension = IRestrictedLockupTokenExtension(restrictedLockupTokenExtension).slotsPerWord();
        if (slotsPerWordExtension != slotsPerWord) {
            revert RestrictedLockupToken_ExtensionSlotsPerWordMismatch(slotsPerWord, slotsPerWordExtension);
        }
        slotsPerWordExtension = IRestrictedLockupTokenExtension(restrictedLockupTokenManagementExtension).slotsPerWord();
        if (slotsPerWordExtension != slotsPerWord) {
            revert RestrictedLockupToken_ExtensionSlotsPerWordMismatch(slotsPerWord, slotsPerWordExtension);
        }
        maxBalancePerSubIndex = BitManipulationLib.calculateMaxBalancePerSubIndex(slotsPerWord);
        elementBitSize = BitManipulationLib.calculateElementBitSize(slotsPerWord);

        // Initialize delegated function selectors
        _initializeDelegatedSelectors();
    }

    // ============================================
    // FALLBACK PATTERN FOR HOLDER MANAGEMENT
    // ============================================

    /// @dev Function selectors that should be delegated to the management extension
    mapping(bytes4 => bool) private _delegatedToManagementExtension;
    /// @dev Function selectors that should be delegated to the extension
    mapping(bytes4 => bool) private _delegatedToExtension;

    /**
     * @dev Initialize delegated function selectors in constructor
     * This is done in a separate function to avoid constructor size issues
     */
    function _initializeDelegatedSelectors() private {
        // Management Extension - Holder management functions
        _delegatedToManagementExtension[bytes4(keccak256("createHolderFromAddress(address)"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("appendHolderAddress(address,uint256)"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("addHolderWithAddresses(address[])"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("removeHolder(uint256)"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("removeWalletFromHolder(address)"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("batchRemoveWalletFromHolder(address[])"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("getHolderAddresses(uint256)"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("getHolderId(address)"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("addressHasHolder(address)"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("holderExists(uint256)"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("setHolderMax(uint256)"))] = true;

        // Management Extension - Admin functions
        _delegatedToManagementExtension[bytes4(keccak256("pause(bool)"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("freeze(address,bool)"))] = true;

        // Extension - Release schedule functions
        _delegatedToExtension[bytes4(keccak256("createReleaseSchedule(uint256,uint256,uint256,uint256)"))] = true;
        _delegatedToExtension[bytes4(keccak256("fundReleaseScheduleWithHolding((address,uint256,uint256,uint256,uint256),address[])"))] = true;
        _delegatedToExtension[bytes4(keccak256("fundReleaseSchedule(address,uint256,uint256,uint256,address[])"))] = true;
        _delegatedToExtension[bytes4(keccak256("batchFundReleaseScheduleWithHolding((address,uint256,uint256,uint256,uint256)[],address[])"))] = true;
        _delegatedToExtension[bytes4(keccak256("batchFundReleaseSchedule(address[],uint256[],uint256[],uint256[],address[])"))] = true;
        _delegatedToExtension[bytes4(keccak256("mintReleaseScheduleTokenType(address,uint256,uint256,uint256,uint256,address[])"))] = true;
        _delegatedToExtension[bytes4(keccak256("mintReleaseSchedule(address,uint256,uint256,uint256,address[])"))] = true;
        _delegatedToExtension[bytes4(keccak256("batchMintReleaseScheduleTokenType(address[],uint256[],uint256[],uint256[],uint256[],address[])"))] = true;
        _delegatedToExtension[bytes4(keccak256("batchMintReleaseSchedule(address[],uint256[],uint256[],uint256[],address[])"))] = true;
        _delegatedToExtension[bytes4(keccak256("updateTimelockTokenType(address,uint256,uint256)"))] = true;
        _delegatedToExtension[bytes4(keccak256("findHoldingFor(address,address,uint256)"))] = true;

        // Extension - Burn functions, safe appove, max total supply and holding management
        _delegatedToExtension[bytes4(keccak256("burn(address,uint256)"))] = true;
        _delegatedToExtension[bytes4(keccak256("softBurn(address,uint256)"))] = true;
        _delegatedToExtension[bytes4(keccak256("burnHolding(address,uint256,uint256)"))] = true;
        _delegatedToExtension[bytes4(keccak256("updateHoldingTokenType(address,uint256,uint256,uint256,uint256)"))] = true;
        _delegatedToExtension[bytes4(keccak256("safeApprove(address,uint256)"))] = true;
        _delegatedToExtension[bytes4(keccak256("setMaxTotalSupply(uint256)"))] = true;

        // Management Extension - Holding view functions
        _delegatedToManagementExtension[bytes4(keccak256("holdingCountOf(address)"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("holdingOf(address,uint256)"))] = true;
        // Management Extension - Upgrade functions
        _delegatedToManagementExtension[bytes4(keccak256("upgradeTransferRules(address)"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("upgradeIdentityRegistry(address)"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("getFrozenStatus(address)"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("isValidTransferRules(address)"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("isValidIdentityRegistry(address)"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("existingTokenTypesCount()"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("existingTokenTypes(uint256)"))] = true;
        _delegatedToManagementExtension[bytes4(keccak256("tokenTypeExists(uint256)"))] = true;
    }

    /**
     * @dev Fallback function that delegates calls to appropriate extension
     */
    fallback() external {
        bytes4 selector = msg.sig;
        address extension;

        if (_delegatedToManagementExtension[selector]) {
            extension = restrictedLockupTokenManagementExtension;
        } else if (_delegatedToExtension[selector]) {
            extension = restrictedLockupTokenExtension;
        } else {
            revert("Function not found");
        }

        assembly ("memory-safe") {
            // Copy calldata to memory
            calldatacopy(0, 0, calldatasize())

            // Delegatecall to extension
            let result := delegatecall(gas(), extension, 0, calldatasize(), 0, 0)

            // Copy return data
            returndatacopy(0, 0, returndatasize())

            // Return or revert based on result
            switch result
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }

    /**
     * Support of ERC165
     * @dev See https://eips.ethereum.org/EIPS/eip-165
     * @param interfaceId_ The interface identifier, as specified in ERC-165
     */
    function supportsInterface(
        bytes4 interfaceId_
    ) public view override(ERC165) returns (bool) {
        return
            interfaceId_ == type(IERC1404).interfaceId ||
            super.supportsInterface(interfaceId_);
    }

    /**
     * @dev get circulating token supply, ie tokens that have already been minted and are in circulation. Akin to Outstanding, Issued shares.
     * @return _circulatingTokenSupply total circulating token supply.
     * @notice circulatingTokenSupply() == totalSupply() == "outstanding shares" == "issued shares"
     */
    function circulatingTokenSupply()
        public
        view
        returns (uint256 _circulatingTokenSupply)
    {
        _circulatingTokenSupply = totalSupply();
    }

    /**
     * @dev get unissued token supply, ie tokens that can still be minted. Akin to Unissued shares.
     * @return _unissuedTokenSupply total unissued token supply.
     */
    function unissuedTokenSupply()
        public
        view
        returns (uint256 _unissuedTokenSupply)
    {
        _unissuedTokenSupply = maxTotalSupply - circulatingTokenSupply();
    }

    /**
     * @dev Calls the TransferRules detectTransferRetriction function to determine if tokens can be transferred.
     * detectTransferRestriction returns a status code. ERC-1404 standard.
     * @param from_ The address the tokens are transferred from
     * @param to_ The address the tokens would be transferred to
     * @param value_ The quantity of tokens to be transferred
     */
    function detectTransferRestriction(
        address from_,
        address to_,
        uint256 value_
    ) public view returns (uint256) {
        return
            transferRules.detectTransferRestriction(
                address(this),
                from_,
                to_,
                value_
            );
    }

    /**
     * @dev Calls the TransferRules checkTransferAllowed function to determine if tokens of a specific type can be transferred to a recipient.
     * This function checks transfer restrictions based on token type, mint timestamp, and recipient address.
     * @param tokenType_ The type of token being transferred
     * @param mintTimestamp_ The timestamp when the tokens were originally minted
     * @param recipientIdentity The identity of the recipient
     * @param isAmlKycPassed_ Whether the recipient has passed AML/KYC
     * @return uint256 A status code indicating if the transfer is allowed (0 = allowed, non-zero = restricted)
     */
    function detectTransferRestrictionFor(
        uint256 tokenType_,
        uint256 mintTimestamp_,
        IIdentityRegistry.IdentityInfo memory recipientIdentity,
        bool isAmlKycPassed_
    ) public view returns (uint256) {
        return transferRules.detectTransferRestrictionForHolding(
            tokenType_,
            mintTimestamp_,
            recipientIdentity,
            isAmlKycPassed_
        );
    }

    /**
     * @dev Calls TransferRules to look up a human readable error message for a given error code.
     * This is the original implementation that accepts a uint256 parameter; the uint8 overload below provides ERC-1404 compliance.
     * @param restrictionCode_ is an error code to lookup an error code for
     * @return a human readable error message
     */
    function messageForTransferRestriction(
        uint256 restrictionCode_
    ) public view returns (string memory) {
        return transferRules.messageForTransferRestriction(restrictionCode_);
    }

    /**
     * @dev Calls TransferRules to lookup a human readable error message that goes with an error code. ERC-1404 standard.
     * @param restrictionCode_ is an error code to lookup an error code for, u8 for ERC-1404 standard compatibility
     * @return a human readable error message
     */
    function messageForTransferRestriction(
        uint8 restrictionCode_
    ) public view returns (string memory) {
        return transferRules.messageForTransferRestriction(uint256(restrictionCode_));
    }

    /**
     * @notice Balance of simple ERC20 tokens without any timelocks for a given address
     * @param who_ Address to calculate
     * @return amount The amount of simple ERC20 tokens available. See token.balanceOf
     **/
    function superBalanceOf(address who_) public view returns (uint256) {
        return
            balanceOf(who_) - unlockedBalanceOf(who_) - lockedBalanceOf(who_);
    }

    /**
     * @notice Total unlocked balance for a given address - 1) balance of simple ERC20 tokens without any timelocks (superBalanceOf) + 2) unlocked tokens that remain (unlockedBalanceOf)
     * @param who_ Address to calculate
     * @return amount The unlocked total balance of
     **/
    function unlockedTotalBalanceOf(
        address who_
    ) public view returns (uint256) {
        return balanceOf(who_) - lockedBalanceOf(who_);
    }

    /**
     * @notice Total locked balance for a given address across all timelocks
     * @param who_ Address to calculate
     * @return amount_
     */
    function lockedBalanceOf(
        address who_
    ) public view returns (uint256 amount_) {
        uint256 _timelockCountOf = timelockCountOf(who_);
        for (uint256 i; i < _timelockCountOf; ++i) {
            amount_ += lockedBalanceOfTimelock(who_, i);
        }
    }

    /**
     * @dev Override ERC20 transferFrom to enforce transfer restrictions
     * @param from_ is the address to transfer from
     * @param to_ is the address to transfer to
     * @return true if transfer is successful
     */
    function transferFrom(
        address from_,
        address to_,
        uint256 amount_
    ) public virtual override returns (bool) {
        _enforceTransferRestrictions(from_, to_, amount_);
        uint256 transferredAmount = _updateTimelock(from_, to_, amount_, true);
        _handleMultiTypeTransfer(from_, to_, amount_ - transferredAmount, true);
        super.transferFrom(from_, to_, amount_);

        return true;
    }

    /**
     * @notice Total unlocked balance remaining for a given address across all timelocks
     * @param who_ Address to calculate
     * @return amount_
     */
    function unlockedBalanceOf(
        address who_
    ) public view returns (uint256 amount_) {
        uint256 _timelockCountOf = timelockCountOf(who_);
        for (uint256 i; i < _timelockCountOf; ++i) {
            amount_ += unlockedBalanceOfTimelock(who_, i);
        }
    }

    /**
     * @dev get token decimals
     * @return decimals
     */
    function decimals() public view virtual override returns (uint8) {
        return _decimals;
    }

    /**
    * @notice calculates how many tokens would be released at a specified time for a scheduleId.
        This is independent of any specific address or address's timelock.
    * @param commencedTimestamp_ the commencement time to use in the calculation for the scheduled
    * @param currentTimestamp_ the timestamp to calculate unlocked tokens for
    * @param amount_ the amount of tokens
    * @param scheduleId_ the schedule id used to calculate the unlocked amount
    * @return _unlocked the total amount unlocked for the schedule given the other parameters
    */
    function calculateUnlocked(
        uint256 commencedTimestamp_,
        uint256 currentTimestamp_,
        uint256 amount_,
        uint256 scheduleId_
    ) public view returns (uint256) {
        return
            calculateUnlocked(
                commencedTimestamp_,
                currentTimestamp_,
                amount_,
                releaseSchedules[scheduleId_]
            );
    }

    /**
     * @notice returns the total count of timelocks for a specific address
     * @param who_ the address to get the timelock count for
     * @return number of timelocks
     */
    function timelockCountOf(address who_) public view returns (uint256) {
        return timelocks[who_].length;
    }

    /**
     * @notice Get The locked balance for a specific address and specific timelock
     * @param who_ The address to check
     * @param timelockIndex_ Specific timelock belonging to the who address
     * @return _locked Balance of the timelock
     */
    function lockedBalanceOfTimelock(
        address who_,
        uint256 timelockIndex_
    ) public view returns (uint256 _locked) {
        Timelock memory _timelock = timelockOf(who_, timelockIndex_);
        if (_timelock.totalAmount > _timelock.tokensTransferred) {
            _locked =
                _timelock.totalAmount -
                totalUnlockedToDateOfTimelock(who_, timelockIndex_);
        }
    }

    /**
     * @notice Get the unlocked balance for a specific address and specific timelock
     * @param who_ the address to check
     * @param timelockIndex_ for a specific timelock belonging to the who address
     * @return _unlocked balance of the timelock
     */
    function unlockedBalanceOfTimelock(
        address who_,
        uint256 timelockIndex_
    ) public view returns (uint256 _unlocked) {
        Timelock memory _timelock = timelockOf(who_, timelockIndex_);
        if (_timelock.totalAmount > _timelock.tokensTransferred) {
            _unlocked =
                totalUnlockedToDateOfTimelock(who_, timelockIndex_) -
                _timelock.tokensTransferred;
        }
    }

    /**
     * @notice Gets the total locked and unlocked balance of a specific address's timelocks to the current block timestamp
     * @param who_ The address to check
     * @param timelockIndex_ The index of the timelock for the who address
     * @return Locked and unlocked amount for the specified timelock
     */
    function totalUnlockedToDateOfTimelock(
        address who_,
        uint256 timelockIndex_
    ) public view returns (uint256) {
        Timelock memory _timelock = timelockOf(who_, timelockIndex_);

        return
            calculateUnlocked(
                _timelock.commencementTimestamp,
                block.timestamp,
                _timelock.totalAmount,
                _timelock.scheduleId
            );
    }

    /**
     * @notice Get the struct details for an address's specific timelock
     * @param who_ Address to check
     * @param index_ The index of the timelock for the who address
     * @return Struct with the attributes of the timelock
     */
    function timelockOf(
        address who_,
        uint256 index_
    ) public view returns (Timelock memory) {
        return timelocks[who_][index_];
    }

    /**
    * @notice calculates how many tokens would be released at a specified time for a ReleaseSchedule struct.
            This is independent of any specific address or address's timelock.

    * @param commencedTimestamp_ the commencement time to use in the calculation for the scheduled
    * @param currentTimestamp_ the timestamp to calculate unlocked tokens for
    * @param amount_ the amount of tokens
    * @param releaseSchedule_ a ReleaseSchedule struct used to calculate the unlocked amount
    * @return the total amount unlocked for the schedule given the other parameters
    */
    function calculateUnlocked(
        uint256 commencedTimestamp_,
        uint256 currentTimestamp_,
        uint256 amount_,
        ReleaseSchedule memory releaseSchedule_
    ) public pure returns (uint256) {
        return VestingMath.calculateUnlocked(
            commencedTimestamp_,
            currentTimestamp_,
            amount_,
            releaseSchedule_.releaseCount,
            releaseSchedule_.delayUntilFirstReleaseInSeconds,
            releaseSchedule_.initialReleasePortionInBips,
            releaseSchedule_.periodBetweenReleasesInSeconds
        );
    }

    /**
     * @notice ERC20 standard interface function
     * Provide controls of Restricted and Lockup tokens
     * Can transfer simple ERC20 tokens and unlocked tokens at the same time
     * First will transfer unlocked tokens and then simple ERC20
     * @param to_ recipient of transfer
     * @param amount_ amount of tokens to transfer
     * @return bool. True on success / Reverted on error
     */
    function transfer(
        address to_,
        uint256 amount_
    ) public virtual override returns (bool) {
        _enforceTransferRestrictions(_msgSender(), to_, amount_);
        return _transfer(to_, amount_);
    }

    /**
     * @dev Transfer a holding of a specific token type
     * @param to recipient of transfer
     * @param amount amount of tokens to transfer
     * @param globalHoldingIdx holding index
     * @return bool. True on success / Reverted on error
     */
    function transferHolding(
        address to,
        uint256 amount,
        uint256 globalHoldingIdx
    ) external returns (bool) {
        if (amount == 0) {
            revert RestrictedLockupToken_InvalidAmount();
        }
        if (globalHoldingIdx >= mintTimestampCount) {
            revert RestrictedLockupToken_HoldingIndexOutOfBound();
        }

        address _sender = _msgSender();
        // Get real balance (considering overflow)
        uint256 senderBalance = _getRealBalance(_sender, globalHoldingIdx);
        if (amount > senderBalance) {
            revert RestrictedLockupToken_NoItemWithEnoughBalance();
        }

        _enforceTransferRestrictions(_sender, to, amount);
        _processHoldingTransfer(
            _sender,
            to,
            amount,
            globalHoldingIdx,
            senderBalance
        );
        super._transfer(_sender, to, amount);

        return true;
    }

    /**
     * @dev Internal function to process holding transfer (reduces stack depth)
     */
    function _processHoldingTransfer(
        address sender,
        address to,
        uint256 amount,
        uint256 globalHoldingIdx,
        uint256 senderBalance
    ) internal {
        uint256 bucketIndex = globalHoldingIdx / slotsPerWord;
        uint256 subIndex = globalHoldingIdx % slotsPerWord;
        uint256 element = BitManipulationLib.getPackedElement(globalMintTimestamps[bucketIndex], subIndex, elementBitSize);
        (uint256 tokenType, uint256 daysAfterDeployment) = BitManipulationLib.unpackElement(element);

        _enforceTransferRestrictionsFor(tokenType, BitManipulationLib.daysSinceDeployToTimestamp(daysAfterDeployment, deploymentDay), to);
        _executeTransferFromHolding(
            sender,
            to,
            tokenType,
            daysAfterDeployment,
            globalHoldingIdx,
            senderBalance,
            amount
        );
    }

    /**
     * @dev Allows the reserve admin to create new tokens in a specified address.
     * The total number of tokens cannot exceed the maxTotalSupply (the "Hard Cap").
     * Automatically determines the appropriate token type based on recipient's identity.
     * @param to_ The addres to mint tokens into.
     * @param value_ The number of tokens to mint.
     */
    function mint(
        address to_,
        uint256 value_
    ) public validAddress(to_) onlyReserveOrMintAdmin {
        // Determine token type based on recipient's identity
        uint256 _mintTokenType = transferRules.determineTokenType(to_, identityRegistry);
        _mintWithType(to_, value_, _mintTokenType);
    }

    /**
     * @dev batchTransfer tokens
     */
    function batchTransfer(
        address[] calldata recipients,
        uint256[] calldata amounts
    ) external returns (bool) {
        uint256 _recipientsLength = recipients.length;
        if (_recipientsLength != amounts.length) {
            revert RestrictedLockupToken_RecipientAndAmountLengthsShouldMatch();
        }
        for (uint256 i; i < _recipientsLength; ++i) {
            transfer(recipients[i], amounts[i]);
        }

        return true;
    }

    /**
     * @dev Transfer tokens from one address to another with ignoring of transfer rules
     * With reserve admin access only
     * @param from_ sender address
     * @param to_ recipient address
     * @param amount_ amount of tokens
     */
    function forceTransferBetween(
        address from_,
        address to_,
        uint256 amount_
    ) external onlyReserveAdmin onlyExistingAddress(to_) {
        if (from_ == to_) {
            revert RestrictedLockupToken_SenderCannotBeRecipient(from_);
        }
        if (from_ == address(0)) {
            revert RestrictedLockupToken_InvalidZeroAddress();
        }
        if (amount_ == 0) {
            revert RestrictedLockupToken_InvalidAmount();
        }

        uint256 transferredAmount = _updateTimelock(from_, to_, amount_, false);
        _handleMultiTypeTransfer(from_, to_, amount_ - transferredAmount, false);

        super._transfer(from_, to_, amount_);
        emit ForceTransferBetween(_msgSender(), from_, to_, amount_);
    }

    /**
     * @notice the total number of schedules that have been created
     * @return count of schedules
     */
    function scheduleCount() external view returns (uint256 count) {
        return releaseSchedules.length;
    }

    /**
     * @notice Check the total remaining balance of a timelock including the locked and unlocked portions
     * @param who_ the address to check
     * @param timelockIndex_  Specific timelock belonging to the who address
     * @return total remaining balance of a timelock
     */
    function balanceOfTimelock(
        address who_,
        uint256 timelockIndex_
    ) external view returns (uint256) {
        Timelock memory _timelock = timelockOf(who_, timelockIndex_);
        if (_timelock.totalAmount <= _timelock.tokensTransferred) {
            return 0;
        } else {
            return _timelock.totalAmount - _timelock.tokensTransferred;
        }
    }

    /**
    * @notice Cancel a cancelable timelock created by the fundReleaseSchedule, fundReleaseScheduleWithHolding, mintReleaseSchedule, or mintReleaseScheduleTokenType functions.
        If canceled the tokens that are locked at the time of the cancellation will be returned to the funder
        and unlocked tokens will be transferred to the recipient.
    * @param target_ The initial recipient address of the timelock which will be cancelled.
    * @param timelockIndex_ timelock index
    * @param scheduleId_ require it matches expected
    * @param commencementTimestamp_ require it matches expected
    * @param totalAmount_ require it matches expected
    * @param reclaimTokenTo_ reclaim token to
    * @return success Always returns true on completion so that a function calling it can revert if the required call did not succeed
    */
    function cancelTimelock(
        address target_,
        uint256 timelockIndex_,
        uint256 scheduleId_,
        uint256 commencementTimestamp_,
        uint256 totalAmount_,
        address reclaimTokenTo_
    ) external nonReentrant returns (bool success) {
        if (timelockCountOf(target_) <= timelockIndex_) {
            revert RestrictedLockupToken_InvalidTimelock();
        }
        if (reclaimTokenTo_ == address(0)) {
            revert RestrictedLockupToken_InvalidReclaimTo();
        }

        Timelock storage _timelock = timelocks[target_][timelockIndex_];

        if (!_canBeCanceled(_timelock)) {
            revert RestrictedLockupToken_TimelockCannotBeCanceled();
        }
        if (_timelock.scheduleId != scheduleId_) {
            revert RestrictedLockupToken_ScheduleIdDoesNotMatch();
        }
        if (_timelock.commencementTimestamp != commencementTimestamp_) {
            revert RestrictedLockupToken_CommencementTimestampDoesNotMatch();
        }
        if (_timelock.totalAmount != totalAmount_) {
            revert RestrictedLockupToken_TotalAmountDoesNotMatch();
        }

        uint256 _canceledAmount = lockedBalanceOfTimelock(
            target_,
            timelockIndex_
        );

        if (_canceledAmount == 0) {
            revert RestrictedLockupToken_TimelockHasNoValueRemaining();
        }

        // Get token type and mint timestamp from global holding index
        (uint256 tokenType, uint256 mintTimestamp) = _getTokenTypeAndMintTimestampFromGlobalIndex(_timelock.globalHoldingIndex);

        // Check token type transfer restrictions if mintTimestamp + lockDuration > current time
        // to keep restrictions consistent, we check the restrictions on the reclaimTokenTo address
        // in order to not allow to bypass restrictions by using a different address
        // don't trigger SENDER TOKENS LOCKED - we expect this because the canceled amount is still locked
        _enforceTransferRestrictionsFor(
            tokenType,
            mintTimestamp,
            reclaimTokenTo_
        );
        uint256 _paidAmount = unlockedBalanceOfTimelock(
            target_,
            timelockIndex_
        );
        _timelock.tokensTransferred = _timelock.totalAmount;
        uint256 daysAfterDeployment = BitManipulationLib.calculateDaysAfterDeployment(mintTimestamp, deploymentDay);
        // Add to reclaimer's optimized holdings structure
        _addToHoldingsByIndex(reclaimTokenTo_, _timelock.globalHoldingIndex, _canceledAmount);

        // Add to target's optimized holdings structure if there's a paid amount
        if (_paidAmount > 0) {
            _addToHoldingsByIndex(target_, _timelock.globalHoldingIndex, _paidAmount);
        }
        // only canceledAmount must be transferred back from initial target recipient to reclaimTokenTo
        // paid amount (ie already-unlocked tokens) is already initially transferred to the target recipient but locked
        super._transfer(target_, reclaimTokenTo_, _canceledAmount);

        emit TimelockCanceled(
            _msgSender(),
            target_,
            timelockIndex_,
            reclaimTokenTo_,
            _canceledAmount,
            _paidAmount
        );
        return true;
    }

    /**
    * @notice transfers the unlocked token from an address's specific timelock
        It is typically more convenient to call transfer. But if the account has many timelocks the cost of gas
        for calling transfer may be too high. Calling transferTimelock from a specific timelock limits the transfer cost.
    * @param to_ the address that the tokens will be transferred to
    * @param amount_ the number of token base units to be transferred to the to address
    * @param timelockId_ the specific timelock of the function caller to transfer unlocked tokens from
    * @return bool always true when completed
    */
    function transferTimelock(
        address to_,
        uint256 amount_,
        uint256 timelockId_
    ) external nonReentrant returns (bool) {
        address _sender = _msgSender();
        if (unlockedBalanceOfTimelock(_sender, timelockId_) < amount_) {
            revert RestrictedLockupToken_AmountExceedsUnlockedBalance();
        }

        Timelock storage _timelock = timelocks[_sender][timelockId_];

        // Get token type and mint timestamp from global holding index
        (uint256 tokenType, uint256 mintTimestamp) = _getTokenTypeAndMintTimestampFromGlobalIndex(_timelock.globalHoldingIndex);

        // Check token type transfer restrictions if mintTimestamp + lockDuration > current time
        _enforceTransferRestrictionsFor(
            tokenType,
            mintTimestamp,
            to_
        );
        _enforceTransferRestrictions(_sender, to_, amount_);

        // Update timelock state
        _timelock.tokensTransferred += amount_;

        // Add to recipient's optimized holdings structure
        _addToHoldingsByIndex(
            to_,
            _timelock.globalHoldingIndex,
            amount_
        );

        // Perform standard ERC20 transfer
        super._transfer(_sender, to_, amount_);

        // Emit token type transfer event
        emit TokenTypeTransferred(_sender, to_, amount_, tokenType);

        return true;
    }

    /**
     * @dev update hook
     * @notice During a burn, this is invoked by the _burn function (ERC20.sol) which artificially sets `to` to the 0x0 address. Tokens are NOT actually transferred to 0x0 during a burn.
     * @param from_ from address
     * @param to_ to address
     * @param amount_ amount
     */
    function _update(
        address from_,
        address to_,
        uint256 amount_
    ) internal virtual override {
        if (snapshotsEnabled) {
            snapshotPeriods.onUpdate(address(this), from_, to_, amount_);
        }
        super._update(from_, to_, amount_); // Call parent hook

        /// @notice when to is 0x0, it's a burn (note - 0x0 is not actually transferred any tokens during burn)
        /// do NOT create a holder in that case
        if (!_addressHasHolder(to_) && to_ != address(0)) {
            _createHolderFromAddress(to_);
        }
    }

    /**
     *  @notice Check if timelock can be cancelable by _msgSender()
     * @param timelock_ Timelock struct to check for cancelation
     */
    function _canBeCanceled(
        Timelock storage timelock_
    ) private view returns (bool) {
        uint256 _len = timelock_.cancelableBy.length;
        for (uint256 i; i < _len; ++i) {
            if (_msgSender() == timelock_.cancelableBy[i]) {
                return true;
            }
        }
        return false;
    }

    /**
     * @notice Update the timelock state to account for unlocked tokens that are transferred out
     * @param from Address from
     * @param to Address to (for token type restriction checking)
     * @param amount_ Amount of tokens to transfer, includes unlocked tokens still within timelock, and simple tokens
     * @return _unlockedAmount Amount of unlocked tokens that are transferred out (does NOT include simple tokens)
     */
    function _updateTimelock(
        address from,
        address to,
        uint256 amount_,
        bool validateRestrictions
    ) private returns (uint256 _unlockedAmount) {
        if (amount_ == 0) {
            return 0;
        }
        uint256 _simpleTokenBalance = amount_;
        uint256 lockedBalance = 0;
        IIdentityRegistry.IdentityInfo memory recipientIdentity = identityRegistry.identity(to);
        bool isAmlKycPassed_ = identityRegistry.isAmlKycPassed(to);

        /// @notice transfer from unlocked tokens
        for (uint256 i; i < timelockCountOf(from); ++i) {
            /// @notice if the timelock has no value left
            if (
                timelocks[from][i].tokensTransferred ==
                timelocks[from][i].totalAmount
            ) {
                continue;
            } else {
                uint256 _unlockedBalanceOfTimelock = unlockedBalanceOfTimelock(
                    from,
                    i
                );
                if (_unlockedBalanceOfTimelock == 0) {
                    continue;
                }
                lockedBalance += lockedBalanceOfTimelock(from, i);

                if (validateRestrictions) {
                    // Check token type transfer restrictions for timelock tokens
                    Timelock memory _timelock = timelocks[from][i];
                    (uint256 tokenType, uint256 mintTimestamp) = _getTokenTypeAndMintTimestampFromGlobalIndex(_timelock.globalHoldingIndex);
                    uint256 restrictionCode = detectTransferRestrictionFor(
                        tokenType,
                        mintTimestamp,
                        recipientIdentity,
                        isAmlKycPassed_
                    );

                    if (restrictionCode != 0) {
                        continue; // skip this timelock because it's not allowed to transfer
                    }
                }

                if (_simpleTokenBalance > _unlockedBalanceOfTimelock) {
                    _simpleTokenBalance -= _unlockedBalanceOfTimelock;
                    timelocks[from][i]
                        .tokensTransferred += _unlockedBalanceOfTimelock;

                    // Add to recipient's optimized holdings structure
                    Timelock memory _timelock = timelocks[from][i];
                    (uint256 tokenType,) = _getTokenTypeAndMintTimestampFromGlobalIndex(_timelock.globalHoldingIndex);
                    _addToHoldingsByIndex(
                        to,
                        _timelock.globalHoldingIndex,
                        _unlockedBalanceOfTimelock
                    );

                    emit TokenTypeTransferred(from, to, _unlockedBalanceOfTimelock, tokenType);
                } else {
                    timelocks[from][i].tokensTransferred += _simpleTokenBalance;

                    // Add to recipient's optimized holdings structure
                    Timelock memory _timelock = timelocks[from][i];
                    (uint256 tokenType,) = _getTokenTypeAndMintTimestampFromGlobalIndex(_timelock.globalHoldingIndex);
                    _addToHoldingsByIndex(
                        to,
                        _timelock.globalHoldingIndex,
                        _simpleTokenBalance
                    );

                    emit TokenTypeTransferred(from, to, _simpleTokenBalance, tokenType);

                    _simpleTokenBalance = 0;
                    break;
                }
            }
        }
        // validate that we have enough total unlocked balance to transfer if we have any unlocked tokens left
        // balanceOf includes 1) locked, 2) unlocked, and 3) simple tokens
        // check if the amount to transfer is <= the total transferrable balance (unlocked + simple)
        if ((balanceOf(from) - lockedBalance) < amount_) {
            // revert RestrictedLockupToken_InvalidAmount();
            revert RestrictedLockupToken_InsufficientTotalBalanceOf();
        }
        // by the end, _simpleTokenBalance MUST be LTE the amount because unlocked amount is the difference
        _unlockedAmount = amount_ - _simpleTokenBalance;
    }

    /**
     * @param to address to send to
     * @param amount amount to send
     */
    function _transfer(address to, uint256 amount) private returns (bool) {
        address _sender = _msgSender();
        uint256 transferredAmount = _updateTimelock(_sender, to, amount, true);
        _handleMultiTypeTransfer(_sender, to, amount - transferredAmount, true);

        super._transfer(_sender, to, amount);
        return true;
    }

