    }

    /**
     * @dev Mint tokens of a specific type to an address
     * @param to The address to mint to
     * @param amount The amount to mint
     * @param tokenType The type of token to mint (0-255, uses 8 bits)
     */
    function mintTokenType(address to, uint256 amount, uint256 tokenType) external onlyReserveOrMintAdmin {
        // Verify tokenType is within 8-bit limit (0-255)
        if (tokenType > 255) {
            revert RestrictedLockupToken_InvalidTokenType();
        }

        // Verify if the specified token type is allowed for the recipient
        if (!transferRules.tokenTypeAllowed(tokenType, to, identityRegistry)) {
            revert RestrictedLockupToken_TokenTypeNotAllowedForRecipient();
        }
        _mintWithType(to, amount, tokenType);
    }

    /**
     * @dev Internal function to mint tokens with a specific type
     */
    function _mintWithType(address to, uint256 amount, uint256 tokenType) internal {
        if (amount == 0) {
            revert RestrictedLockupToken_InvalidZeroAmount();
        }
        if (totalSupply() + amount > maxTotalSupply) {
            revert RestrictedLockupToken_CannotExceedMaxTotalSupply();
        }

        uint256 dayMintTimestamp = recordMintTimestamp ? 
            VestingMath.toMidnightTimestamp(block.timestamp) : 
            BitManipulationLib.daysSinceDeployToTimestamp(recordPausedOnDaysAfterDeployment, deploymentDay);

        // Add to optimized holdings structure
        _addToHoldingsByType(
            to,
            tokenType,
            BitManipulationLib.calculateDaysAfterDeployment(dayMintTimestamp, deploymentDay),
            amount
        );

        // Perform standard ERC20 mint to maintain compatibility
        _mint(to, amount);

        emit TokenTypeMinted(to, amount, tokenType, dayMintTimestamp);
    }

    /**
     * @dev Process transfers for a single token type with cached identity info (optimized direct bitmap iteration)
     * @dev Gas optimization: Split into helper functions to avoid stack too deep, no pre-allocation
     */
    function _processTransfers(
        address from,
        address to,
        uint256 remainingAmount,
        bool validateRestrictions
    ) internal returns (uint256) {
        // Cache identity information outside the loop to save gas
        uint256 walletIndexesLength = walletIndexesByType[from].length;
        TransferParams memory transferParams = TransferParams({
            from: from,
            to: to,
            recipientIdentity: identityRegistry.identity(to),
            isAmlKycPassed: identityRegistry.isAmlKycPassed(to),
            validateRestrictions: validateRestrictions,
            remainingAmount: remainingAmount,
            bitmaskToSet: 0,
            bitmaskToClear: 0
        });
        // Iterate through bitmap words directly - no pre-allocation!
        for (uint256 i = 0; i < walletIndexesLength && transferParams.remainingAmount > 0; i++) {
            uint256 word = walletIndexesByType[from][i];
            if (word == 0) continue;

            // Process word with ultra-optimization (batched bitmap updates)
            transferParams = _processTransferBitmapWord(
                transferParams, word, i
            );
        }

        return transferParams.remainingAmount;
    }

    /**
     * @dev helper function to process transfers for a single bitmap word
     * @dev Processes transfers in bucket-aligned batches for maximum efficiency
     * @dev Uses new globalMintTimestamps structure with slotsPerWord elements per bucket
     */
    function _processTransferBitmapWord(
        TransferParams memory transferParams,
        uint256 word_,
        uint256 wordIndex_
    ) internal returns (TransferParams memory) {
        // Note: Individual bitmap operations are now used instead of batched operations

        while (word_ != 0 && transferParams.remainingAmount > 0) {
            uint256 globalIndex = wordIndex_ * 256 + word_.bitScanForward256();

            // Process entire bucket if not already processed and it exists
            // Inline bucket calculations to reduce variable count
            if (globalIndex < mintTimestampCount) {
                transferParams = _processTransferAlignedPackedHoldings(
                    transferParams, globalIndex
                );

                // Clear all bits in the current word chunk regardless of what was processed
                // This ensures we don't process the same bucket multiple times
                // Clear all bits that belong to this bucket and are in the current word
                word_ = BitManipulationLib.clearBucketBits(word_, globalIndex, wordIndex_, slotsPerWord);
            } else {
                // Index out of range, just clear current bit
                word_ &= word_ - 1;
            }
        }

        // Apply batched bitmap changes for this word (only if we have changes)
       if (transferParams.bitmaskToClear > 0) {
            _applyBitmaskToClear(transferParams.from, wordIndex_, transferParams.bitmaskToClear);
            transferParams.bitmaskToClear = 0;
        }
        if (transferParams.bitmaskToSet > 0) {
            _applyBitmaskToWord(transferParams.to, wordIndex_, transferParams.bitmaskToSet);
            transferParams.bitmaskToSet = 0;
        }

        return transferParams;
    }


    /**
     * @dev Process transfer from packed holdings (up to slotsPerWord balances at once)
     * @dev Uses new optimized globalMintTimestamps structure with slotsPerWord elements per bucket
     * @dev Returns remaining amount, total transferred amount, and bitmap masks for efficient updates
     */
    function _processTransferAlignedPackedHoldings(
        TransferParams memory transferParams,
        uint256 globalIndex
    ) internal returns (TransferParams memory) {
        uint256 tempRemainingAmount = transferParams.remainingAmount;

        // Calculate bucket index and starting subIndex from global index
        // uint256 bucketIndex = globalIndex / 8;        
        // Load the packed timestamps once for efficiency
        uint256 packedTimestamps = globalMintTimestamps[globalIndex / slotsPerWord];

        // Get packed balances for this bucket once
        uint256 fromPackedBalances = packedBalancesByTypeAndTime[transferParams.from][globalIndex / slotsPerWord];
        uint256 toPackedBalances = packedBalancesByTypeAndTime[transferParams.to][globalIndex / slotsPerWord];

        // Process slotsPerWord consecutive holdings starting from bucket start
        // Align globalIndex to bucket start to process all holdings in the bucket
        for (uint256 i = 0; i < slotsPerWord && tempRemainingAmount > 0; i++) {
            // Only process holdings that are in the same word as the original globalIndex
            // This prevents processing holdings from buckets that span across word boundaries
            if (((globalIndex / slotsPerWord) * slotsPerWord + i) / 256 != globalIndex / 256) {
                continue;
            }
            uint256 packedBalance = BitManipulationLib.getPackedBalance(fromPackedBalances, i, elementBitSize);
            if (packedBalance == 0) continue;

            // Unpack token type and days (needed for event and possible validation)
            // Check restrictions if validation is enabled
            if (transferParams.validateRestrictions) {
                (uint256 currentTokenType, uint256 daysAfterDeployment) = BitManipulationLib.unpackElement(
                    (packedTimestamps >> (i * elementBitSize)) & ((1 << elementBitSize) - 1)
                );
                if (transferRules.detectTransferRestrictionForHolding(
                    currentTokenType,
                    BitManipulationLib.daysSinceDeployToTimestamp(daysAfterDeployment, deploymentDay),
                    transferParams.recipientIdentity,
                    transferParams.isAmlKycPassed
                ) != 0) {
                    continue; // Skip this holding due to restrictions
                }
            }

            // Get real balance (considering overflow)
            uint256 currentBalance = packedBalance;
            uint256 currentGlobalIndex = (globalIndex / slotsPerWord) * slotsPerWord + i;
            if (packedBalance == maxBalancePerSubIndex) {
                currentBalance = overflowBalances[transferParams.from][currentGlobalIndex];
            }

            // Calculate transfer amount for this holding
            uint256 transferAmount = tempRemainingAmount > currentBalance ? currentBalance : tempRemainingAmount;

            // Calculate new balances
            uint256 newFromBalance = currentBalance - transferAmount;

            // Handle sender balance update (considering overflow)
            if (newFromBalance == 0) {
                // Balance becomes zero, clear everything
                fromPackedBalances = BitManipulationLib.setPackedBalance(fromPackedBalances, i, 0, elementBitSize);
                if (packedBalance == maxBalancePerSubIndex) {
                    delete overflowBalances[transferParams.from][currentGlobalIndex];
                }
                // Clear bitmap bit
                _clearBitmapBit(transferParams.from, currentGlobalIndex);
            } else if (newFromBalance < maxBalancePerSubIndex) {
                // New balance fits in uint32, store in packed storage
                fromPackedBalances = BitManipulationLib.setPackedBalance(fromPackedBalances, i, newFromBalance, elementBitSize);
                if (packedBalance == maxBalancePerSubIndex) {
                    delete overflowBalances[transferParams.from][currentGlobalIndex];
                }
            } else {
                // New balance still exceeds uint32 max, keep max in packed storage and update overflow mapping
                overflowBalances[transferParams.from][currentGlobalIndex] = newFromBalance;
            }

            uint256 newToBalance = 0;
            (newToBalance, toPackedBalances) = _updateRecipientBalance(
                transferParams.to,
                toPackedBalances,
                currentGlobalIndex,
                i,
                transferAmount
            );

            tempRemainingAmount -= transferAmount;

            // Set bit for recipient if they now have balance
            if (newToBalance > 0) {
                transferParams.bitmaskToSet |= (1 << currentGlobalIndex % 256);
            }

            // Clear bit for sender if they now have zero balance
            // Only clear bits that are in the current word to avoid cross-word issues
            if (newFromBalance == 0) {
                transferParams.bitmaskToClear |= (1 << currentGlobalIndex % 256);
            }

            // Emit transfer event
            emit TokenTypeTransferred(
                transferParams.from,
                transferParams.to,
                transferAmount,
                BitManipulationLib.unpackTokenTypeElement((packedTimestamps >> (i * elementBitSize)) & ((1 << elementBitSize) - 1))
            );
        }

        // Update storage only once if any transfers occurred
        if (transferParams.remainingAmount > tempRemainingAmount) {
            packedBalancesByTypeAndTime[transferParams.from][globalIndex / slotsPerWord] = fromPackedBalances;
            packedBalancesByTypeAndTime[transferParams.to][globalIndex / slotsPerWord] = toPackedBalances;
            transferParams.remainingAmount = tempRemainingAmount;
        }

        return transferParams;
    }

    function _updateRecipientBalance(
        address to,
        uint256 toPackedBalances_,
        uint256 globalIndex,
        uint256 subIndex,
        uint256 transferAmount
    ) internal returns (uint256 newToBalance, uint256 toPackedBalances) {
        uint256 currentToBalance = BitManipulationLib.getPackedBalance(toPackedBalances_, subIndex, elementBitSize);
        if (currentToBalance == maxBalancePerSubIndex) {
            currentToBalance = overflowBalances[to][globalIndex];
        }

        newToBalance = currentToBalance + transferAmount;
        toPackedBalances = _setPackedBalanceWithOverflow(
            to,
            globalIndex,
            subIndex,
            newToBalance,
            toPackedBalances_
        );
    }

    function _setPackedBalanceWithOverflow(
        address account,
        uint256 globalIndex,
        uint256 subIndex,
        uint256 newBalance,
        uint256 packedBalances
    ) internal returns (uint256 packedBalancesResult) {
        if (newBalance < maxBalancePerSubIndex) {
            // New balance fits in uint32, store in packed storage
            packedBalancesResult = BitManipulationLib.setPackedBalance(packedBalances, subIndex, newBalance, elementBitSize);
        } else {
            // New balance exceeds uint32 max, store max in packed storage and real amount in overflow mapping
            packedBalancesResult = BitManipulationLib.setPackedBalance(packedBalances, subIndex, maxBalancePerSubIndex, elementBitSize);
            overflowBalances[account][globalIndex] = newBalance;
        }
    }

    /**
     * @dev Helper function to update packed balance considering overflow
     * @param account The account to update
     * @param globalIndex_ The global index
     * @param newBalance The new balance value
     * @param oldPackedBalance The old packed balance value (for overflow detection)
     */
    function _updatePackedBalance(
        address account,
        uint256 globalIndex_,
        uint256 newBalance,
        uint256 oldPackedBalance
    ) internal {
        uint256 packedKey = BitManipulationLib.getPackedBalanceKeyFromGlobalIndex(globalIndex_, slotsPerWord);
        uint256 subIndex = globalIndex_ % slotsPerWord;
        uint256 packedBalances = packedBalancesByTypeAndTime[account][packedKey];

        if (newBalance == 0) {
            // Balance becomes zero, clear everything
            packedBalances = BitManipulationLib.setPackedBalance(packedBalances, subIndex, 0, elementBitSize);
            packedBalancesByTypeAndTime[account][packedKey] = packedBalances;
            // Clear any overflow balance
            if (oldPackedBalance == maxBalancePerSubIndex) {
                delete overflowBalances[account][globalIndex_];
            }
            // Clear bitmap bit
            _clearBitmapBit(account, globalIndex_);
        } else if (newBalance < maxBalancePerSubIndex) {
            // New balance fits in uint32, store in packed storage
            packedBalances = BitManipulationLib.setPackedBalance(packedBalances, subIndex, newBalance, elementBitSize);
            packedBalancesByTypeAndTime[account][packedKey] = packedBalances;
            // Clear any existing overflow balance
            if (oldPackedBalance == maxBalancePerSubIndex) {
                delete overflowBalances[account][globalIndex_];
            }
        } else {
            // New balance exceeds uint32 max, store max in packed storage and real amount in overflow mapping
            packedBalances = BitManipulationLib.setPackedBalance(packedBalances, subIndex, maxBalancePerSubIndex, elementBitSize);
            packedBalancesByTypeAndTime[account][packedKey] = packedBalances;
            overflowBalances[account][globalIndex_] = newBalance;
        }
    }

    /**
     * @dev Execute the actual transfer from a holding
     * @dev Final step with minimal variables
     */
    function _executeTransferFromHolding(
        address from,
        address to,
        uint256 tokenType,
        uint256 daysAfterDeployment,
        uint256 globalIndex_,
        uint256 currentBalance,
        uint256 remainingAmount_
    ) internal returns (uint256) {
        uint256 transferAmount = remainingAmount_ > currentBalance ? currentBalance : remainingAmount_;

        // Get old packed balance for overflow detection
        uint256 packedKey = BitManipulationLib.getPackedBalanceKeyFromGlobalIndex(globalIndex_, slotsPerWord);
        uint256 subIndex = globalIndex_ % slotsPerWord;
        uint256 packedBalance = BitManipulationLib.getPackedBalance(packedBalancesByTypeAndTime[from][packedKey], subIndex, elementBitSize);

        // Calculate and update new balance using helper
        uint256 newFromBalance = currentBalance - transferAmount;
        _updatePackedBalance(from, globalIndex_, newFromBalance, packedBalance);

        // Add to recipient's optimized holdings structure
        _addToHoldingsByIndex(to, globalIndex_, transferAmount);

        // Emit transfer event
        emit TokenTypeTransferred(from, to, transferAmount, tokenType);

        return remainingAmount_ - transferAmount;
    }

    /**
     * @dev Handle transfers with token type consideration (optimized structure only)
     */
    function _handleMultiTypeTransfer(address from, address to, uint256 amount, bool validateRestrictions) internal {
        // self-transfer 0 amount is allowed to convert timelock to simple tokens (holdings)
        if (amount == 0) {
            return;
        }
        if (from == to) {
            revert RestrictedLockupToken_SenderCannotBeRecipient(from);
        }

        // Process transfers for this token type
        uint256 remainingAmount = _processTransfers(
            from,
            to,
            amount,
            validateRestrictions
        );

        if (remainingAmount > 0) {
            revert RestrictedLockupToken_InsufficientTotalBalanceOf();
        }
    }

    /**
     * @dev Apply batched bitmap changes to a specific word
     * @dev This replaces multiple _setBitmapBit calls with a single OR operation
     */
    function _applyBitmaskToWord(
        address account,
        uint256 wordIndex,
        uint256 bitmaskToSet
    ) internal {
        // Ensure bitmap array is large enough
        while (walletIndexesByType[account].length <= wordIndex) {
            walletIndexesByType[account].push(0);
        }

        // Apply all bitmap changes for this word at once (major gas optimization)
        walletIndexesByType[account][wordIndex] |= bitmaskToSet;
    }

    function getWalletIndexesLength(address who_) public view returns (uint256) {
        return walletIndexesByType[who_].length;
    }

    function getWalletIndexes(address who_, uint256 index) public view returns (uint256) {
        return walletIndexesByType[who_][index];
    }

    /**
     * @dev Get total count of global holdings (each bucket contains slotsPerWord elements)
     * @return The total number of possible global holding indexes
     */
    function globalHoldingCount() public view returns (uint256) {
        return mintTimestampCount;
    }

    function setRecordMintTimestamp(bool enabled) external onlyTransferAdmin {
        if (enabled == recordMintTimestamp) {
            revert RestrictedLockupToken_AlreadySet();
        }

        // When disabling recordMintTimestamp, store the current daysAfterDeployment
        if (!enabled) {
            recordPausedOnDaysAfterDeployment = BitManipulationLib.calculateDaysAfterDeployment(
                VestingMath.toMidnightTimestamp(block.timestamp), 
                deploymentDay
            );
        }

        recordMintTimestamp = enabled;
    }

    /**
     * @dev Get token type and mint timestamp from global holding index
     * @param globalIndex The global holding index
     * @return tokenType The token type
     * @return mintTimestamp The mint timestamp
     */
    function getTokenTypeAndMintTimestampFromGlobalIndex(uint256 globalIndex) external view returns (uint256 tokenType, uint256 mintTimestamp) {
        return _getTokenTypeAndMintTimestampFromGlobalIndex(globalIndex);
    }
}

contracts/RestrictedLockupTokenExtension.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.8.28;

import {Context} from "@openzeppelin/contracts/utils/Context.sol";
import {ERC2771Context} from "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import {ERC20} from "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {BitScan} from "@solidity-bits/contracts/BitScan.sol";
import {Storage} from "./Storage.sol";
import {VestingMath} from "./libraries/VestingMath.sol";
import {BitManipulationLib} from "./libraries/BitManipulationLib.sol";
import {IIdentityRegistry} from "./interfaces/IIdentityRegistry.sol";
import "./AccessControlErrors.sol";

/**
 * @title RestrictedLockupTokenExtension
 * @notice Extension contract for holding management and burn operations
 * @dev This contract is called via delegatecall from RestrictedLockupToken
 * Following the fallback extension pattern with identical storage layout
 * Handles fundReleaseSchedule, mintReleaseSchedule, setMaxTotalSupply,
 * safeApprove and all burn operations
 */
contract RestrictedLockupTokenExtension is
    Storage,
    ERC20,
    ERC2771Context,
    ReentrancyGuard
{
    using BitScan for uint256;
    using BitManipulationLib for uint256;

    struct FundReleaseScheduleParams {
        address to;
        uint256 amount;
        uint256 commencementTimestamp;
        uint256 scheduleId;
        uint256 holdingIdx;
    }

    struct BurnParams {
        address from;
        uint256 globalIndex;
        uint256 remainingAmount;
        uint256 totalBurned;
        uint256 bitmaskToClear;
        uint256 bucketIndex;
        uint256 alignedBaseIndex;
        uint256 fromPackedBalances;
        uint256 packedTimestamps;
    }

    constructor(address trustedForwarder_, uint256 maxTotalSupply_)
        ERC20("Restricted Lockup Token Extension", "RLTE")
        ERC2771Context(trustedForwarder_)
    {
        if (trustedForwarder_ == address(0)) {
            revert RestrictedLockupToken_InvalidTrustedForwarder();
        }
        maxTotalSupply = maxTotalSupply_;
        // Initialize immutable slotsPerWord with the same value as the main contract
        slotsPerWord = BitManipulationLib.calculateSlotsPerWord(maxTotalSupply_);
        maxBalancePerSubIndex = BitManipulationLib.calculateMaxBalancePerSubIndex(slotsPerWord);
        elementBitSize = BitManipulationLib.calculateElementBitSize(slotsPerWord);
    }

    function _msgSender()
        internal
        view
        override(Context, ERC2771Context, Storage)
        returns (address sender)
    {
        return ERC2771Context._msgSender();
    }

    function _msgData()
        internal
        view
        override(Context, ERC2771Context)
        returns (bytes calldata)
    {
        return ERC2771Context._msgData();
    }

    function _contextSuffixLength()
        internal
        view
        override(Context, ERC2771Context)
        returns (uint256)
    {
        return ERC2771Context._contextSuffixLength();
    }

    // ============================================
    // HOLDING MANAGEMENT
    // ============================================

    /**
     * @notice Update the token type for a holding
     * @dev Only callable by reserve admin. Converts tokens from one type to another while preserving mint timestamp
     * @param wallet The wallet address whose holding is being updated
     * @param oldTokenType The current token type of the holding
     * @param newTokenType The new token type to assign
     * @param globalIndex The global index of the holding to update
     * @param amount The amount of tokens to update (must not exceed holding balance). Use 0 to convert entire holding balance.
     */
    function updateHoldingTokenType(
        address wallet,
        uint256 oldTokenType,
        uint256 newTokenType,
        uint256 globalIndex,
        uint256 amount
    ) external onlyReserveAdmin {
        if (oldTokenType == newTokenType) {
            revert RestrictedLockupToken_InvalidTokenType();
        }
        if (globalIndex >= mintTimestampCount) {
            revert RestrictedLockupToken_InvalidHolding();
        }
        (uint256 daysAfterDeployment, , uint256 finalAmount) = 
            _validateAndPrepareTokenTypeUpdate(wallet, oldTokenType, newTokenType, globalIndex, amount);

        // Remove from old token type
        _removeFromHoldings(wallet, finalAmount, globalIndex);
        // Add to new token type with same daysAfterDeployment
        _addToHoldingsByType(wallet, newTokenType, daysAfterDeployment, finalAmount);

        emit HoldingTokenTypeUpdated(
            _msgSender(),
            wallet,
            oldTokenType,
            newTokenType,
            BitManipulationLib.daysSinceDeployToTimestamp(daysAfterDeployment, deploymentDay),
            finalAmount
        );
    }

    /**
     * @dev Validate and prepare token type update parameters
     */
    function _validateAndPrepareTokenTypeUpdate(
        address wallet,
        uint256 oldTokenType,
        uint256 newTokenType,
        uint256 globalIndex,
        uint256 amount
    ) internal view returns (uint256 daysAfterDeployment, uint256 currentBalance, uint256 finalAmount) {
        daysAfterDeployment = _validateTokenTypeAndGetDays(oldTokenType, globalIndex);
        currentBalance = _getRealBalance(wallet, globalIndex);

        // If amount is 0, convert the entire balance of this holding
        finalAmount = amount == 0 ? currentBalance : amount;

        if (finalAmount == 0) {
            revert RestrictedLockupToken_InvalidAmount();
        }

        if (currentBalance < finalAmount) {
            revert RestrictedLockupToken_InsufficientTotalBalanceOf();
        }

        // Ensure the new token type is allowed for this wallet
        if (!transferRules.tokenTypeAllowed(newTokenType, wallet, identityRegistry)) {
            revert RestrictedLockupToken_TokenTypeNotAllowedForRecipient();
        }
    }

    /**
     * @dev Validate token type and get days after deployment
     */
    function _validateTokenTypeAndGetDays(
        uint256 expectedTokenType,
        uint256 globalIndex
    ) internal view returns (uint256 daysAfterDeployment) {
        uint256 packed = globalMintTimestamps[globalIndex / slotsPerWord];
        uint256 element = BitManipulationLib.getPackedElement(packed, globalIndex % slotsPerWord, elementBitSize);
        uint256 tokenType;
        (tokenType, daysAfterDeployment) = BitManipulationLib.unpackElement(element);

        if (tokenType != expectedTokenType) {
            revert RestrictedLockupToken_InvalidTokenType();
        }
    }

    /**
     * @dev Remove tokens from optimized holdings structure (bitmap-based)
     * @param account The account to remove tokens from
     * @param amount The amount to remove
     * @param holdingGlobalIdx The global index of the holding
     */
    function _removeFromHoldings(
        address account,
        uint256 amount,
        uint256 holdingGlobalIdx
    ) internal {
        // Get current balance from packed storage
        uint256 bucketIndex = holdingGlobalIdx / slotsPerWord;
        uint256 subIndex = holdingGlobalIdx % slotsPerWord;
        uint256 packedBalances = packedBalancesByTypeAndTime[account][bucketIndex];
        uint256 packedBalance = BitManipulationLib.getPackedBalance(packedBalances, subIndex, elementBitSize);

        // Get real balance (considering overflow)
        uint256 realBalance = packedBalance;
        if (packedBalance == maxBalancePerSubIndex) {
            realBalance = overflowBalances[account][holdingGlobalIdx];
        }

        if (realBalance < amount) {
            revert RestrictedLockupToken_InvalidAmount();
        }

        // Calculate new balance
        uint256 newBalance = realBalance - amount;

        // Update balance in packed storage and overflow mapping as needed
        if (newBalance == 0) {
            // Balance becomes zero, clear everything
            uint256 newPackedBalances = BitManipulationLib.setPackedBalance(packedBalances, subIndex, 0, elementBitSize);
            packedBalancesByTypeAndTime[account][bucketIndex] = newPackedBalances;
            // Clear any overflow balance
            if (packedBalance == maxBalancePerSubIndex) {
                delete overflowBalances[account][holdingGlobalIdx];
            }
            // Clear bitmap bit
            _clearBitmapBit(account, holdingGlobalIdx);
        } else if (newBalance < maxBalancePerSubIndex) {
            // New balance fits in uint32, store in packed storage
            uint256 newPackedBalances = BitManipulationLib.setPackedBalance(packedBalances, subIndex, newBalance, elementBitSize);
            packedBalancesByTypeAndTime[account][bucketIndex] = newPackedBalances;
            // Clear any existing overflow balance
            if (packedBalance == maxBalancePerSubIndex) {
                delete overflowBalances[account][holdingGlobalIdx];
            }
        } else {
            // New balance still exceeds uint32 max, keep max in packed storage and update overflow mapping
            overflowBalances[account][holdingGlobalIdx] = newBalance;
        }
    }

    function _superBalanceOf(address account) internal view returns (uint256) {
        return _queryBalance("superBalanceOf(address)", account);
    }

    // ============================================
    // BURN FUNCTIONS
    // ============================================

    /**
     * @dev Destroys tokens and removes them from the total supply. Can only be called by an address with a Reserve Admin role.
     * @notice The only burnable amount of tokens are the simple tokens owned by a wallet. Timelocked tokens are not burnable.
     * @notice Cancel a timelock prior to burning tokens if there is a desire to burn timelocked tokens.
     * @notice DOES NOT ACTUALLY TRANSFER TOKENS TO 0X0! Merely emits Transfer event and calls _update with recipient artificially set to 0x0.
     * @param from_ The address to destroy the tokens from.
     * @param value_ The number of tokens to destroy from the address.
     */
    function burn(
        address from_,
        uint256 value_
    ) external validAddress(from_) onlyReserveAdmin {
        if (_superBalanceOf(from_) < value_) {
            revert RestrictedLockupToken_InsufficientBurnableBalance();
        }
        _burnWithHoldingsDestroy(from_, value_);
    }

    function burnHolding(
        address from_,
        uint256 globalHoldingIdx,
        uint256 amount
    ) external validAddress(from_) onlyReserveAdmin {
        if (globalHoldingIdx >= mintTimestampCount) {
            revert RestrictedLockupToken_HoldingIndexOutOfBound();
        }

        _burnSingleHolding(from_, globalHoldingIdx, amount);
        _burn(from_, amount);
    }

    /**
     * @dev Burns tokens from an account using the soft burn mechanism.
     *      Can only be called by an address with the Soft Burn Admin role.
     *      Requires sufficient allowance and burnable balance.
     *      Burns tokens in FIFO order across all token types and holdings.
     * @param from_ The address to burn tokens from.
     * @param value_ The number of tokens to burn.
     */
    function softBurn(
        address from_,
        uint256 value_
    ) external onlySoftBurnAdmin {
        address spender = _msgSender();
        _spendAllowance(from_, spender, value_);

        if (_superBalanceOf(from_) < value_) {
            revert RestrictedLockupToken_InsufficientBurnableBalance();
        }
        _burnWithHoldingsDestroy(from_, value_);
    }

    /**
     * @dev Internal function to burn tokens and destroy holdings in FIFO order (optimized direct bitmap iteration)
     * @dev Gas optimization: Reduced local variables to avoid stack too deep, iterate bitmap directly
     * @param from_ The address to destroy the tokens from
     * @param value_ The number of tokens to destroy
     */
    function _burnWithHoldingsDestroy(address from_, uint256 value_) internal {
        _burnHoldings(from_, value_);

        // Perform standard ERC20 burn
        _burn(from_, value_);
    }

    /**
     * @dev Helper function to burn holdings for a specific token type
     * @dev Separated to avoid stack too deep issues
     * @param from_ The address to burn from
     * @param amount Amount left to burn
     */
    function _burnHoldings(
        address from_, 
        uint256 amount
    ) internal {
        uint256 remainingAmount = amount;

        // Iterate through bitmap words directly - no pre-allocation!
        for (uint256 wordIndex = 0; wordIndex < walletIndexesByType[from_].length && remainingAmount > 0; wordIndex++) {
            uint256 word = walletIndexesByType[from_][wordIndex];
            if (word == 0) continue;

            // Process each set bit in this word
            remainingAmount = _processBitmapWordForBurn(from_, word, wordIndex, remainingAmount);
        }
        // we have not validated that remaining amount is 0
        // because it is validated that superBalanceOf is greater than 
        // or equal to amount in burn and soft burn functions
    }

    /**
     * @dev Process a single bitmap word for burning
     * @dev Further separated to minimize stack usage
     */
    function _processBitmapWordForBurn(
        address from_,
        uint256 word_,
        uint256 wordIndex_,
        uint256 remainingAmount_
    ) internal returns (uint256) {
        uint256 bitmaskToClear = 0; // Collect all bits to clear for sender

        while (word_ != 0 && remainingAmount_ > 0) {
            uint256 globalIndex = wordIndex_ * 256 + word_.bitScanForward256();

            // Process entire bucket if not already processed and it exists
            if (globalIndex < mintTimestampCount) {
                uint256 totalBurned;
                uint256 bucketBitmaskToClear;
                (remainingAmount_, totalBurned, bucketBitmaskToClear) = _processBurnAlignedPackedHoldings(
                    from_, globalIndex, remainingAmount_
                );

                // Accumulate bitmasks from the processed bucket
                if (totalBurned > 0) {
                    bitmaskToClear |= bucketBitmaskToClear;
                }

                // Clear all bits that belong to this bucket and are in the current word
                word_ = BitManipulationLib.clearBucketBits(word_, globalIndex, wordIndex_, slotsPerWord);
            } else {
                // Index out of range, just clear current bit
                word_ &= word_ - 1;
            }
        }

        // Apply batched bitmap changes for this word (only if we have changes)
        if (bitmaskToClear > 0) {
            _applyBitmaskToClear(from_, wordIndex_, bitmaskToClear);
        }

        return remainingAmount_;
    }

    /**
     * @dev OPTIMIZED process burn from packed holdings (up to slotsPerWord balances at once)
     * @dev Uses new optimized globalMintTimestamps structure with slotsPerWord elements per bucket
     * @dev Returns remaining amount, total burned amount, and bitmap mask for efficient updates
     */
    function _processBurnAlignedPackedHoldings(
        address from,
        uint256 globalIndex,
        uint256 remainingAmount_
    ) internal returns (uint256, uint256, uint256) {
        BurnParams memory burnParams = BurnParams({
            from: from,
            globalIndex: globalIndex,
            remainingAmount: remainingAmount_,
            totalBurned: 0,
            bitmaskToClear: 0,
            bucketIndex: globalIndex / slotsPerWord,
            alignedBaseIndex: (globalIndex / slotsPerWord) * slotsPerWord,
            fromPackedBalances: packedBalancesByTypeAndTime[from][globalIndex / slotsPerWord],
            packedTimestamps: globalMintTimestamps[globalIndex / slotsPerWord]
        });

        // Process slotsPerWord consecutive holdings starting from bucket start
        // Align globalIndex to bucket start to process all holdings in the bucket
        for (uint256 i = 0; i < slotsPerWord && burnParams.remainingAmount > 0; i++) {
            // Only process holdings that are in the same word as the original globalIndex
            // This prevents processing holdings from buckets that span across word boundaries
            if (((globalIndex / slotsPerWord) * slotsPerWord + i) / 256 != globalIndex / 256) {
                continue;
            }
            burnParams = _processSingleBurnHolding(burnParams, i);
        }

        // Update storage only once if any burns occurred
        if (burnParams.totalBurned > 0) {
            packedBalancesByTypeAndTime[burnParams.from][burnParams.bucketIndex] = burnParams.fromPackedBalances;
        }

        return (burnParams.remainingAmount, burnParams.totalBurned, burnParams.bitmaskToClear);
    }

    /**
     * @dev Process a single burn holding to reduce stack depth
     */
    function _processSingleBurnHolding(
        BurnParams memory burnParams,
        uint256 i
    ) internal returns (BurnParams memory) {
        uint256 packedBalance = BitManipulationLib.getPackedBalance(burnParams.fromPackedBalances, i, elementBitSize);
        if (packedBalance == 0) return burnParams;

        // Get real balance and calculate burn amount
        uint256 currentGlobalIndex = burnParams.alignedBaseIndex + i;
        uint256 currentBalance = packedBalance == maxBalancePerSubIndex ? 
            overflowBalances[burnParams.from][currentGlobalIndex] : packedBalance;

        uint256 burnAmount = burnParams.remainingAmount > currentBalance ? 
            currentBalance : burnParams.remainingAmount;
        uint256 newFromBalance = currentBalance - burnAmount;

        // Update balance and handle overflow
        burnParams.fromPackedBalances = _updateBalance(
            burnParams.from,
            burnParams.fromPackedBalances,
            i,
            currentGlobalIndex,
            packedBalance,
            newFromBalance
        );

        // Update burn tracking
        burnParams.totalBurned += burnAmount;
        burnParams.remainingAmount -= burnAmount;

        // Update bitmask if balance becomes zero (matches transfer logic)
        // Only update bits that are in the current word to avoid cross-word issues
        if (newFromBalance == 0) {
            burnParams.bitmaskToClear |= (1 << (currentGlobalIndex % 256));
        }

        // Emit burn event
        uint256 element = (burnParams.packedTimestamps >> (i * elementBitSize)) & ((1 << elementBitSize) - 1);
        emit TokenTypeBurned(burnParams.from, burnAmount, BitManipulationLib.unpackTokenTypeElement(element));

        return burnParams;
    }

    /**
     * @dev Update balance for target address
     */
    function _updateBalance(
        address from,
        uint256 fromPackedBalances,
        uint256 i,
        uint256 currentGlobalIndex,
        uint256 packedBalance,
        uint256 newFromBalance
    ) internal returns (uint256) {
        if (newFromBalance == 0) {
            // Balance becomes zero, clear everything
            if (packedBalance == maxBalancePerSubIndex) {
                delete overflowBalances[from][currentGlobalIndex];
            }
            return BitManipulationLib.setPackedBalance(fromPackedBalances, i, 0, elementBitSize);
        } else if (newFromBalance < maxBalancePerSubIndex) {
            // New balance fits in uint32, store in packed storage
            if (packedBalance == maxBalancePerSubIndex) {
                delete overflowBalances[from][currentGlobalIndex];
            }
            return BitManipulationLib.setPackedBalance(fromPackedBalances, i, newFromBalance, elementBitSize);
        } else {
            // New balance still exceeds uint32 max, update overflow mapping
            overflowBalances[from][currentGlobalIndex] = newFromBalance;
            return BitManipulationLib.setPackedBalance(fromPackedBalances, i, maxBalancePerSubIndex, elementBitSize);
        }
    }

    /**
     * @dev Burn from a single holding
     * @dev Minimized to avoid stack issues
     */
    function _burnSingleHolding(
        address from_,
        uint256 globalIndex_,
        uint256 amount
    ) internal {
        // Get balance from packed storage
        uint256 packedKey = BitManipulationLib.getPackedBalanceKeyFromGlobalIndex(globalIndex_, slotsPerWord);
        uint256 subIndex = globalIndex_ % slotsPerWord;
        uint256 packedBalances = packedBalancesByTypeAndTime[from_][packedKey];
        uint256 currentBalance = BitManipulationLib.getPackedBalance(packedBalances, subIndex, elementBitSize);
        if (currentBalance == maxBalancePerSubIndex) {
            uint256 overflowBalance = overflowBalances[from_][globalIndex_];
            currentBalance = overflowBalance;
        }
        if (amount > currentBalance) {
            revert RestrictedLockupToken_NoItemWithEnoughBalance();
        }

        // Update packed balances
        uint256 newBalance = currentBalance - amount;

        packedBalances = _updateBalance(
            from_,
            packedBalances,
            subIndex,
            globalIndex_,
            currentBalance,
            newBalance
        );

        packedBalancesByTypeAndTime[from_][packedKey] = packedBalances;

        // Clear bitmap bit if balance becomes zero
        if (newBalance == 0) {
            _clearBitmapBit(from_, globalIndex_);
        }

        uint256 tokenType_ = _getTokenTypeFromGlobalIndex(globalIndex_);
        // Emit token type burn event
        emit TokenTypeBurned(from_, amount, tokenType_);
    }

    /**
     * @notice Create a release schedule template that can be used to generate many token timelocks
     * @param releaseCount Total number of releases including any initial "cliff'
     * @param delayUntilFirstReleaseInSeconds "cliff" or 0 for immediate release
     * @param initialReleasePortionInBips Portion to release in 100ths of 1% (10000 BIPS per 100%)
     * @param periodBetweenReleasesInSeconds After the delay and initial release
     * the remaining tokens will be distributed evenly across the remaining number of releases (releaseCount - 1)
     * @return unlockScheduleId The id used to refer to the release schedule at the time of funding the schedule
     */
    function createReleaseSchedule(
        uint256 releaseCount,
        uint256 delayUntilFirstReleaseInSeconds,
        uint256 initialReleasePortionInBips,
        uint256 periodBetweenReleasesInSeconds
    ) external anyAdmin returns (uint256 unlockScheduleId) {
        if (delayUntilFirstReleaseInSeconds > maxReleaseDelay) {
            revert RestrictedLockupToken_InvalidFirstRelease();
        }
        if (releaseCount == 0) {
            revert RestrictedLockupToken_InvalidNumberOfRelases();
        }
        if (initialReleasePortionInBips > VestingMath.BIPS_PRECISION) {
            revert RestrictedLockupToken_InvalidRInitialReleaseBIPS();
        }

        if (releaseCount > 1) {
            if (periodBetweenReleasesInSeconds == 0) {
                revert RestrictedLockupToken_InvalidReleasePeriod();
            }
            if (initialReleasePortionInBips == VestingMath.BIPS_PRECISION) {
                revert RestrictedLockupToken_CantVestAllForMultipleReleases();
            }
        } else {
            if (initialReleasePortionInBips != VestingMath.BIPS_PRECISION) {
                revert RestrictedLockupToken_InvalidReleasePortionForSingleRelease();
            }
            periodBetweenReleasesInSeconds = 0;
        }

        releaseSchedules.push(
            ReleaseSchedule(
                releaseCount,
                delayUntilFirstReleaseInSeconds,
                initialReleasePortionInBips,
                periodBetweenReleasesInSeconds
            )
        );

        unlockScheduleId = releaseSchedules.length - 1;
        emit ScheduleCreated(_msgSender(), unlockScheduleId);

        return unlockScheduleId;
    }

    function timelockCountOf(address wallet) internal view returns (uint256) {
        return timelocks[wallet].length;
    }

    /**
     * @notice Update the token type for a specific timelock
     * @dev Only callable by reserve admin. Updates token type classification for timelocked tokens
     * @param wallet The wallet address whose timelock is being updated
     * @param timelockIndex The index of the timelock to update
     * @param newTokenType The new token type to assign
     */
    function updateTimelockTokenType(
        address wallet,
        uint256 timelockIndex,
        uint256 newTokenType
    ) external onlyReserveAdmin {
        if (timelockIndex >= timelockCountOf(wallet)) {
            revert RestrictedLockupToken_InvalidTimelock();
        }

        Timelock storage timelock = timelocks[wallet][timelockIndex];
        (uint256 oldTokenType, uint256 mintTimestamp) = _getTokenTypeAndMintTimestampFromGlobalIndex(timelock.globalHoldingIndex);

        if (oldTokenType == newTokenType) {
            revert RestrictedLockupToken_InvalidTokenType();
        }

        // Ensure the new token type is allowed for this wallet
        if (!transferRules.tokenTypeAllowed(newTokenType, wallet, identityRegistry)) {
            revert RestrictedLockupToken_TokenTypeNotAllowedForRecipient();
        }

        // For timelock token type updates, we need to create a new global index
        _removeFromHoldings(wallet, 0, timelock.globalHoldingIndex);
        uint256 globalHoldingIndex = _addToHoldingsByType(
            wallet,
            newTokenType,
            BitManipulationLib.calculateDaysAfterDeployment(mintTimestamp, deploymentDay),
            0
        );
        timelock.globalHoldingIndex = globalHoldingIndex;

        emit TimelockTokenTypeUpdated(
            _msgSender(),
            wallet,
            timelockIndex,
            oldTokenType,
            newTokenType,
            timelock.totalAmount
        );
    }

    function _fundReleaseSchedule(
        FundReleaseScheduleParams memory params,
        address[] memory cancelableBy_
    ) internal returns (bool _success) {
        if (cancelableBy_.length > MAX_CANCELABLE_BY) {
            revert RestrictedLockupToken_MaxCancelersExceeded();
        }

        address _funder = _msgSender();
        uint256 _timelockId = _fund(
            params.to,
            params.amount,
            params.commencementTimestamp,
            params.scheduleId,
            0, // token type is not used for fundReleaseSchedule, it is got from the holdingIdx
            _funder,
            false,
            params.holdingIdx
        );

        if (cancelableBy_.length > 0) {
            timelocks[params.to][_timelockId].cancelableBy = cancelableBy_;
        }

        emit ScheduleFunded(
            _funder,
            params.to,
            params.scheduleId,
            params.amount,
            params.commencementTimestamp,
            _timelockId,
            cancelableBy_
        );
        return true;
    }

    /**
     * @notice Fund the programmatic release of tokens to a recipient with explicit parameters including holding index
     * @param params FundReleaseScheduleParams struct containing all necessary parameters
     * @param cancelableBy_ array of canceler addresses
     * @return _success Always returns true on completion so that a function calling it can revert if the required call did not succeed
     */
    function fundReleaseScheduleWithHolding(
        FundReleaseScheduleParams memory params,
        address[] memory cancelableBy_
    ) public nonReentrant anyAdmin returns (bool _success) {
        return _fundReleaseSchedule(params, cancelableBy_);
    }

    /**
     * @dev Find the first holding for a sender that has enough amount and is allowed to transfer to recipient
     * @dev Optimized to iterate only through set bits using bit manipulation
     * @param sender_ The address to transfer from
     * @param recipient_ The address to transfer to
     * @param amount_ The amount needed
     * @return globalIndex The global index of the holding, or type(uint256).max if not found
     * @return holdingAmount The amount available in this holding
     * @return tokenType The token type of the holding
     */
    function findHoldingFor(
        address sender_,
        address recipient_,
        uint256 amount_
    ) public view returns (
        uint256,
        uint256,
        uint256
    ) {
        // Get recipient identity for transfer validation
        IIdentityRegistry.IdentityInfo memory recipientIdentity = identityRegistry.identity(recipient_);
        bool isAmlKycPassed = identityRegistry.isAmlKycPassed(recipient_);

        // Iterate through all holdings for the sender
        for (uint256 wordIndex = 0; wordIndex < walletIndexesByType[sender_].length; wordIndex++) {
            uint256 word = walletIndexesByType[sender_][wordIndex];
            if (word == 0) continue;

            while (word != 0) {
                // Find the position of the lowest set bit
                uint256 currentGlobalIndex = wordIndex * 256 + word.bitScanForward256();

                // Get holding details
                uint256 element = BitManipulationLib.getPackedElement(
                    globalMintTimestamps[currentGlobalIndex / slotsPerWord],
                    currentGlobalIndex % slotsPerWord,
                    elementBitSize
                );
                // Get the actual balance for this holding
                uint256 currentAmount = _getRealBalance(sender_, currentGlobalIndex);

                // Check if this holding has enough amount
                if (currentAmount >= amount_) {
                    (uint256 currentTokenType, uint256 daysAfterDeployment) = BitManipulationLib.unpackElement(element);
                    uint256 currentMintTimestamp = BitManipulationLib.daysSinceDeployToTimestamp(daysAfterDeployment, deploymentDay);
                    // Check if transfer is allowed for this holding
                    uint256 restrictionCode = transferRules.detectTransferRestrictionForHolding(
                        currentTokenType,
                        currentMintTimestamp,
                        recipientIdentity,
                        isAmlKycPassed
                    );

                    // If transfer is allowed (restriction code is 0), return this holding
                    if (restrictionCode == 0) {
                        return (currentGlobalIndex, currentAmount, currentTokenType);
                    }
                }

                // Clear the lowest set bit for next iteration (Brian Kernighan's algorithm)
                word = word & (word - 1);
            }
        }
        return (type(uint256).max, 0, 0);
    }

    /**
     * @notice Fund a release schedule by finding a suitable holding from the funder and automatically determining token type.
     * This function finds the first holding with sufficient amount and uses its token type for the release schedule.
     * @param to_ recipient address that will have tokens unlocked on a release schedule
     * @param amount_ of tokens to transfer in base units (the smallest unit without the decimal point)
     * @param commencementTimestamp_ the time (in unixtime) the release schedule will start
     * @param scheduleId_ the id of the release schedule that will be used to release the tokens
     * @param cancelableBy_ array of canceler addresses
     * @return _success Always returns true on completion so that a function calling it can revert if the required call did not succeed
     */
    function fundReleaseSchedule(
        address to_,
        uint256 amount_,
        uint256 commencementTimestamp_,
        uint256 scheduleId_,
        address[] memory cancelableBy_
    ) public nonReentrant anyAdmin returns (bool _success) {
        address _funder = _msgSender();

        // Find a suitable holding from the funder using the existing findHoldingFor function
        (uint256 holdingIdx,,) = findHoldingFor(_funder, to_, amount_);

        if (holdingIdx == type(uint256).max) {
            revert RestrictedLockupToken_NoHoldingWithEnoughBalance();
        }

        FundReleaseScheduleParams memory params = FundReleaseScheduleParams({
            to: to_,
            amount: amount_,
            commencementTimestamp: commencementTimestamp_,
            scheduleId: scheduleId_,
            holdingIdx: holdingIdx
        });

        // Create FundReleaseScheduleParams with found values and call fundReleaseSchedule
        return _fundReleaseSchedule(
            params,
            cancelableBy_
        );
    }

    function _mintReleaseSchedule(
        address to_,
        uint256 amount_,
        uint256 commencementTimestamp_,
        uint256 scheduleId_,
        uint256 tokenType_,
        address[] memory cancelableBy_
    ) internal returns (bool _success) {
        if (cancelableBy_.length > MAX_CANCELABLE_BY) {
            revert RestrictedLockupToken_MaxCancelersExceeded();
        }

        address _funder = _msgSender();
        uint256 _timelockId = _fund(
            to_,
            amount_,
            commencementTimestamp_,
            scheduleId_,
            tokenType_,
            _funder,
            true,
            0 // holdingIdx is not used for mintReleaseSchedule
        );
        _registerTokenType(tokenType_);

        if (cancelableBy_.length > 0) {
            timelocks[to_][_timelockId].cancelableBy = cancelableBy_;
        }

        emit ScheduleFunded(
            _funder,
            to_,
            scheduleId_,
            amount_,
            commencementTimestamp_,
            _timelockId,
            cancelableBy_
        );
        return true;
    }

    /**
    * @notice Fund the programmatic release of tokens to a recipient by minting directly to them with explicit token type.
        WARNING: this function IS CANCELABLE by cancelableBy.
        If canceled the tokens that are locked at the time of the cancellation will be returned to the funder
        and unlocked tokens will be transferred to the recipient.
    * @param to_ recipient address that will have tokens unlocked on a release schedule
    * @param amount_ of tokens to transfer in base units (the smallest unit without the decimal point)
    * @param commencementTimestamp_ the time (in unixtime) the release schedule will start
    * @param scheduleId_ the id of the release schedule that will be used to release the tokens
    * @param tokenType_ the token type to assign to the minted tokens
    * @param cancelableBy_ array of canceler addresses
    * @return _success Always returns true on completion so that a function calling it can revert if the required call did not succeed
    */
    function mintReleaseScheduleTokenType(
        address to_,
        uint256 amount_,
        uint256 commencementTimestamp_,
        uint256 scheduleId_,
        uint256 tokenType_,
        address[] memory cancelableBy_
    ) public nonReentrant onlyReserveOrMintAdmin returns (bool _success) {
        return _mintReleaseSchedule(to_, amount_, commencementTimestamp_, scheduleId_, tokenType_, cancelableBy_);
    }

    /**
     * @notice Mint tokens directly to a recipient on a release schedule with automatic token type determination.
     * This is akin to token minting, it does not have to adhere to transfer restrictions, and is purely under the discretion of the Reserve Admin.
     * @param to_ recipient address that will have tokens unlocked on a release schedule
     * @param amount_ of tokens to transfer in base units (the smallest unit without the decimal point)
     * @param commencementTimestamp_ the time (in unixtime) the release schedule will start
     * @param scheduleId_ the id of the release schedule that will be used to release the tokens
     * @param cancelableBy_ array of canceler addresses
     * @return _success Always returns true on completion so that a function calling it can revert if the required call did not succeed
     */
    function mintReleaseSchedule(
        address to_,
        uint256 amount_,
        uint256 commencementTimestamp_,
        uint256 scheduleId_,
        address[] memory cancelableBy_
    ) public nonReentrant onlyReserveOrMintAdmin returns (bool _success) {
        // Determine token type based on recipient's identity
        uint256 tokenType_ = transferRules.determineTokenType(to_, identityRegistry);

        return _mintReleaseSchedule(to_, amount_, commencementTimestamp_, scheduleId_, tokenType_, cancelableBy_);
    }


    /**
     * @param to_ Address to
     * @param amount_ Amount of tokens
     * @param commencementTimestamp_ commencement timestamp
     * @param scheduleId_ schedule Id
     * @param funder_ funder address
     * @param isMintReleaseSchedule_ if this funding is via a mint release schedule
     * @return timelock Id
     */
    function _fund(
        address to_,
        uint256 amount_,
        uint256 commencementTimestamp_, // unix timestamp
        uint256 scheduleId_,
        uint256 tokenType_,
        address funder_,
        bool isMintReleaseSchedule_,
        uint256 globalHoldingIdx_
    ) internal returns (uint256) {
        if (timelocks[to_].length >= MAX_TIMELOCKS) {
            revert RestrictedLockupToken_MaxTimelocksExceeded();
        }
        if (amount_ < minTimelockAmount) {
            revert RestrictedLockupToken_InvalidFundAmount();
        }
        if (to_ == address(0)) {
            revert RestrictedLockupToken_InvalidFundAddress();
        }
        if (scheduleId_ >= releaseSchedules.length) {
            revert RestrictedLockupToken_InvalidScheduleId();
        }
        if (amount_ < releaseSchedules[scheduleId_].releaseCount) {
            revert RestrictedLockupToken_AmountLessThanReleaseCount();
        }
        if (
            commencementTimestamp_ +
                releaseSchedules[scheduleId_].delayUntilFirstReleaseInSeconds >
            block.timestamp + maxReleaseDelay
        ) {
            revert RestrictedLockupToken_InitialReleaseOutOfRange();
        }

        uint256 mintTimestamp = recordMintTimestamp ? 
            VestingMath.toMidnightTimestamp(block.timestamp) : 
            BitManipulationLib.daysSinceDeployToTimestamp(recordPausedOnDaysAfterDeployment, deploymentDay);

        uint256 globalIndex = 0; // Initialize global index

        if (isMintReleaseSchedule_) {
            uint256 daysAfterDeployment = BitManipulationLib.calculateDaysAfterDeployment(mintTimestamp, deploymentDay);
            // Get global index from _addToHoldings and store it in timelock
            globalIndex = _addToHoldingsByType(to_, tokenType_, daysAfterDeployment, 0);
            // Verify if the specified token type is allowed for the recipient
            if (!transferRules.tokenTypeAllowed(tokenType_, to_, identityRegistry)) {
                revert RestrictedLockupToken_TokenTypeNotAllowedForRecipient();
            }
            // we mint new tokens so no need to find anything
            // Perform standard ERC20 mint to maintain compatibility
            _mint(to_, amount_);
        } else {
            _enforceTransferRestrictions(funder_, to_, amount_);
            (mintTimestamp, tokenType_) = _updateHolding(funder_, to_, amount_, globalHoldingIdx_);
            // For fundReleaseSchedule, we need to get the global index from the existing holding
            // This will be handled by _updateHolding which should return the global index
            globalIndex = globalHoldingIdx_; // Use the holding index as global index for now

            emit TokenTypeTransferred(funder_, to_, amount_, tokenType_);
            super._transfer(funder_, to_, amount_);
        }

        Timelock memory _timelock;
        _timelock.scheduleId = scheduleId_;
        _timelock.commencementTimestamp = commencementTimestamp_;
        _timelock.totalAmount = amount_;
        _timelock.funder = funder_;
        _timelock.globalHoldingIndex = globalIndex;

        timelocks[to_].push(_timelock);
        return timelockCountOf(to_) - 1;
    }

    /**
     * @dev Updates the holding by decreasing the amount from the 'from' wallet's holding, but does NOT update the 'to' wallet.
     * This function only removes the specified amount from the sender's (from) holding for the given tokenType and holdingIdx.
     * The recipient's (to) holdings are not updated here.
     */
    function _updateHolding(
        address from,
        address to,
        uint256 amount,
        uint256 globalHoldingIdx
    ) private returns (uint256, uint256) {
        // Validate that holdingIdx is within bounds
        if (globalHoldingIdx >= mintTimestampCount) {
            revert RestrictedLockupToken_InvalidHoldingIndex();
        }

        uint256 packed = globalMintTimestamps[globalHoldingIdx / slotsPerWord];
        uint256 element = BitManipulationLib.getPackedElement(packed, globalHoldingIdx % slotsPerWord, elementBitSize);
        (uint256 _tokenType, uint256 daysAfterDeployment) = BitManipulationLib.unpackElement(element);
        uint256 _mintTimestamp = BitManipulationLib.daysSinceDeployToTimestamp(daysAfterDeployment, deploymentDay);
        _enforceTransferRestrictionsFor(_tokenType, _mintTimestamp, to);
        _removeFromHoldings(
            from,
            amount,
            globalHoldingIdx
        );

        return (_mintTimestamp, _tokenType);
    }

    /**
     * @dev update hook
     * @notice During a burn, this is invoked by the _burn function (ERC20.sol) which artificially sets `to` to the 0x0 address. Tokens are NOT actually transferred to 0x0 during a burn.
     * @param from_ from address
     * @param to_ to address
     * @param amount_ amount
     */
    function _update(
        address from_,
        address to_,
        uint256 amount_
    ) internal virtual override {
        if (snapshotsEnabled) {
            snapshotPeriods.onUpdate(address(this), from_, to_, amount_);
        }
        super._update(from_, to_, amount_); // Call parent hook

        /// @notice when to is 0x0, it's a burn (note - 0x0 is not actually transferred any tokens during burn)
        /// do NOT create a holder in that case
        if (!_addressHasHolder(to_) && to_ != address(0)) {
            _createHolderFromAddress(to_);
        }
    }

    /**
     *  @notice Batch version of fund cancelable release schedule with explicit parameters including holding index
     *  @param params An array of parameters for the release schedule
     *  @param cancelableBy_ An array of cancelables
     *  @return success Always returns true on completion so that a function calling it can revert if the required call did not succeed
     */
    function batchFundReleaseScheduleWithHolding(
        FundReleaseScheduleParams[] memory params,
        address[] memory cancelableBy_
    ) external anyAdmin returns (bool success) {
        for (uint256 i; i < params.length; ++i) {
            _fundReleaseSchedule(
                params[i],
                cancelableBy_
            );
        }

        return true;
    }

    /**
     *  @notice Batch version of fund cancelable release schedule with automatic holding and token type detection
     *  @param to_ An array of recipient addresses that will have tokens unlocked on a release schedule
     *  @param amounts_ An array of amounts of tokens to transfer in base units (the smallest unit without the decimal point)
     *  @param commencementTimestamps_ An array of the times the release schedules will start
     *  @param scheduleIds_ An array of the ids of the release schedules that will be used to release the tokens
     *  @param cancelableBy_ An array of cancelables
     *  @return success Always returns true on completion so that a function calling it can revert if the required call did not succeed
     */
    function batchFundReleaseSchedule(
        address[] calldata to_,
        uint256[] calldata amounts_,
        uint256[] calldata commencementTimestamps_,
        uint256[] calldata scheduleIds_,
        address[] calldata cancelableBy_
    ) external anyAdmin returns (bool success) {
         if (
            to_.length != amounts_.length ||
            to_.length != commencementTimestamps_.length ||
            to_.length != scheduleIds_.length
        ) {
            revert RestrictedLockupToken_MismatchedArrayLength();
        }

        for (uint256 i; i < to_.length; ++i) {
            fundReleaseSchedule(
                to_[i],
                amounts_[i],
                commencementTimestamps_[i],
                scheduleIds_[i],
                cancelableBy_
            );
        }

        return true;
    }

    /**
    *  @notice Batch version of mint cancelable release schedule with explicit token types
    *  @param to An array of recipient address that will have tokens unlocked on a release schedule
    *  @param amounts An array of amount of tokens to transfer in base units (the smallest unit without the decimal point)
    *  @param commencementTimestamps An array of the time the release schedule will start
    *  @param scheduleIds An array of the id of the release schedule that will be used to release the tokens
    *  @param tokenTypes An array of token types for each timelock
    *  @param cancelableBy An array of cancelables
    *  @return success Always returns true on completion so that a function calling it can revert if the required call did not succeed
    */
    function batchMintReleaseScheduleTokenType(
        address[] calldata to,
        uint256[] calldata amounts,
        uint256[] calldata commencementTimestamps,
        uint256[] calldata scheduleIds,
        uint256[] calldata tokenTypes,
        address[] calldata cancelableBy
    ) external onlyReserveOrMintAdmin returns (bool success) {
        if (
            to.length != amounts.length ||
            to.length != commencementTimestamps.length ||
            to.length != scheduleIds.length ||
            to.length != tokenTypes.length
        ) {
            revert RestrictedLockupToken_MismatchedArrayLength();
        }

        for (uint256 i; i < to.length; ++i) {
            _mintReleaseSchedule(
                to[i],
                amounts[i],
                commencementTimestamps[i],
                scheduleIds[i],
                tokenTypes[i],
                cancelableBy
            );
        }

        return true;
    }

    /**
    *  @notice Batch version of mint cancelable release schedule with automatic token type determination
    *  @param to An array of recipient address that will have tokens unlocked on a release schedule
    *  @param amounts An array of amount of tokens to transfer in base units (the smallest unit without the decimal point)
    *  @param commencementTimestamps An array of the time the release schedule will start
    *  @param scheduleIds An array of the id of the release schedule that will be used to release the tokens
    *  @param cancelableBy An array of cancelables
    *  @return success Always returns true on completion so that a function calling it can revert if the required call did not succeed
    */
    function batchMintReleaseSchedule(
        address[] calldata to,
        uint256[] calldata amounts,
        uint256[] calldata commencementTimestamps,
        uint256[] calldata scheduleIds,
        address[] calldata cancelableBy
    ) external onlyReserveOrMintAdmin returns (bool success) {
        if (
            to.length != amounts.length ||
            to.length != commencementTimestamps.length ||
            to.length != scheduleIds.length
        ) {
            revert RestrictedLockupToken_MismatchedArrayLength();
        }

        for (uint256 i; i < to.length; ++i) {
            mintReleaseSchedule(
                to[i],
                amounts[i],
                commencementTimestamps[i],
                scheduleIds[i],
                cancelableBy
            );
        }

        return true;
    }

    /**
     * @dev safeApprove should only be called when setting an initial allowance,
     * or when resetting it to zero.
     * @param spender_ spending address to approve
     * @param value_ amount to approve
     */
    function safeApprove(address spender_, uint256 value_) external {
        if (value_ != 0 && (allowance(address(_msgSender()), spender_) != 0)) {
            revert RestrictedLockupToken_SafeApprove();
        }
        approve(spender_, value_);
    }

    /**
     * @notice Sets a new maximum total supply for the token.
     * @dev Only callable by the reserve admin. The new max total supply must be greater than the current total supply.
     * @param maxTotalSupply_ The new maximum total supply to set.
     */
    function setMaxTotalSupply(
        uint256 maxTotalSupply_
    ) external onlyReserveAdmin {
        if (maxTotalSupply_ > _maxSafeSupply()) {
            revert RestrictedLockupToken_MaxTotalSupplyTooLarge();
        }
        if (maxTotalSupply_ <= totalSupply()) {
            revert RestrictedLockupToken_NewMaxTotalSupplyMustExceedCurrentTotalSupply();
        }

        maxTotalSupply = maxTotalSupply_;
        emit SetMaxTotalSupply(_msgSender(), maxTotalSupply_);
    }
}

contracts/RestrictedLockupTokenManagemen.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.8.28;

import {Context} from "@openzeppelin/contracts/utils/Context.sol";
import {IERC165} from "@openzeppelin/contracts/utils/introspection/ERC165.sol";
import {ERC2771Context} from "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {Storage} from "./Storage.sol";
import {BitManipulationLib} from "./libraries/BitManipulationLib.sol";
import {Popcount} from "@solidity-bits/contracts/Popcount.sol";
import {ITransferRules} from "./interfaces/ITransferRules.sol";
import {IIdentityRegistry} from "./interfaces/IIdentityRegistry.sol";
import "./AccessControlErrors.sol";

/**
 * @title RestrictedLockupTokenManagementExtension
 * @notice Extension contract for managing token holders, access control
 * @dev This contract is called via delegatecall from RestrictedLockupToken
 * Following the fallback extension pattern with identical storage layout
 */
contract RestrictedLockupTokenManagementExtension is
    Storage,
    Context,
    ERC2771Context,
    ReentrancyGuard
{
    using BitManipulationLib for uint256;
    using Popcount for uint256;

    // ============================================
    // HOLDER MANAGEMENT MODIFIERS
    // ============================================

    modifier onlyExistingHolder(uint256 holderId_) {
        if (!holderExists(holderId_)) {
            revert RestrictedLockupToken_HolderDoesNotExist();
        }
        _;
    }

    constructor(address trustedForwarder_, uint256 maxTotalSupply_)
        ERC2771Context(trustedForwarder_)
    {
        if (trustedForwarder_ == address(0)) {
            revert RestrictedLockupToken_InvalidTrustedForwarder();
        }
        maxTotalSupply = maxTotalSupply_;
        // Initialize immutable slotsPerWord with the same value as the main contract
        slotsPerWord = BitManipulationLib.calculateSlotsPerWord(maxTotalSupply_);
        maxBalancePerSubIndex = BitManipulationLib.calculateMaxBalancePerSubIndex(slotsPerWord);
        elementBitSize = BitManipulationLib.calculateElementBitSize(slotsPerWord);
    }

    function _msgSender()
        internal
        view
        override(Context, ERC2771Context, Storage)
        returns (address sender)
    {
        return ERC2771Context._msgSender();
    }

    function _msgData()
        internal
        view
        override(Context, ERC2771Context)
        returns (bytes calldata)
    {
        return ERC2771Context._msgData();
    }

    function _contextSuffixLength()
        internal
        view
        override(Context, ERC2771Context)
        returns (uint256)
    {
        return ERC2771Context._contextSuffixLength();
    }

    // ============================================
    // HOLDER MANAGEMENT VIEW FUNCTIONS
    // ============================================

    /**
     * @dev getHolderId
     * @param addr_ address of holder
     * @return holder Id from address
     */
    function getHolderId(address addr_) public view returns (uint256) {
        return holderIdByAddress[addr_];
    }

    /**
     * @dev check if address has holder
     * @param addr_ address to check
     * @return true if address has holder
     */
    function addressHasHolder(address addr_) public view returns (bool) {
        return _addressHasHolder(addr_);
    }

    /**
     * @dev check if holder exists
     * @param holderId_ id of holder to check
     * @return true if holderId exists
     * */
     function holderExists(uint256 holderId_) public view returns (bool) {
        return walletAddressesByHolderId[holderId_].length > 0;
    }

    /**
     * @dev get holder addresses by Id
     * @param holderId_ holder id
     * @return array of addresses
     */
    function getHolderAddresses(
        uint256 holderId_
    ) external view onlyExistingHolder(holderId_) returns (address[] memory) {
        return walletAddressesByHolderId[holderId_];
    }

    // ============================================
    // HOLDER MANAGEMENT FUNCTIONS
    // ============================================

    /**
     * @dev create Holder from a given Address
     * @param addr_ address of holder
     * @return _holderId id of holder
     */
    function createHolderFromAddress(
        address addr_
    ) public onlyWalletsAdminOrTransferAdmin validAddress(addr_) returns (uint256 _holderId) {
        if (addressHasHolder(addr_)) {
            revert RestrictedLockupToken_HolderAlreadyExists();
        }
        _holderId = _createHolderFromAddress(addr_);
    }

    /**
     * @dev Append a new wallet to existing Holder
     * @param addr_ address of holder
     * @param holderId_ id of holder
     */
    function appendHolderAddress(address addr_, uint256 holderId_) public {
        _appendHolderAddress(addr_, holderId_);
    }

    /**
     * @dev add a Holder with multiple wallet addresses.
     * @param addresses_ array of addresses
     * @return _holderId id of holder
     */
    function addHolderWithAddresses(
        address[] calldata addresses_
    ) external onlyWalletsAdminOrTransferAdmin returns (uint256 _holderId) {
        uint256 _addrLen = addresses_.length;
        if (_addrLen == 0) {
            revert RestrictedLockupToken_InvalidAddressArray();
        }
        if (addresses_.length > MAX_WALLETS_PER_HOLDER) {
            revert RestrictedLockupToken_MaxHolderAddressesReached();
        }

        _holderId = createHolderFromAddress(addresses_[0]);
        // use first entry in array to create Holder id
        for (uint256 i = 1; i < _addrLen; ++i) {
            _appendHolderAddress(addresses_[i], _holderId);
        }
    }

    /**
     * @dev set max number of holder addresses
     * @param holderMax_ max number of holder addresses
     */
    function setHolderMax(uint256 holderMax_) external onlyTransferAdmin {
        if (holderMax_ < holderCount) {
            revert RestrictedLockupToken_NewHolderMaxMustExceedCurrentHolderCount();
        }
        holderMax = holderMax_;

        emit SetHolderMax(_msgSender(), holderMax_);
    }

    /**
     * @dev removeHolder from the system. Delete their wallet address from holder state. Timelock info remains for the wallet address.
     * @notice Holder can only be removed if it has no active timelocks
     * @param holderId_ holder id
     */
    function removeHolder(
        uint256 holderId_
    ) external onlyWalletsAdminOrTransferAdmin onlyExistingHolder(holderId_) {
        address[] storage addresses = walletAddressesByHolderId[holderId_];
        uint256 len = addresses.length;
        for (uint256 i; i < len; ++i) {
            address addr = addresses[i];
            // Check if address has active timelocks by calling main contract function
            if (_queryBalance("lockedBalanceOf(address)", addr) > 0) {
                revert RestrictedLockupToken_CannotRemoveHolderWithActiveTimelocks();
            }
            delete holderIdByAddress[addr];
        }
        delete walletAddressesByHolderId[holderId_];
        holderCount--;

        emit RemoveHolder(_msgSender(), holderId_);
    }

    /**
     * @dev removeWalletFromHolder Remove wallet from a holderId association.
     * @dev use case - when a wallet is no longer owned by that holder.
     * @param addr_ address to remove
     */
    function removeWalletFromHolder(
        address addr_
    ) public onlyWalletsAdminOrTransferAdmin onlyExistingAddress(addr_) {
        uint256 _holderId = holderIdByAddress[addr_];
        address[] memory _holderWalletAddresses = walletAddressesByHolderId[
            _holderId
        ];
        uint256 _len = _holderWalletAddresses.length;
        if (_len == 1) {
            revert RestrictedLockupToken_CannotRemoveLastWallet();
        }

        address[] memory _newHolderWalletAddresses = new address[](_len - 1);
        uint256 _ind;
        for (uint8 i; i < _len; ++i) {
            if (_holderWalletAddresses[i] != addr_) {
                _newHolderWalletAddresses[_ind] = _holderWalletAddresses[i];
                _ind++;
            }
        }

        walletAddressesByHolderId[_holderId] = _newHolderWalletAddresses;
        delete holderIdByAddress[addr_];

        emit RemoveWalletFromHolder(_msgSender(), _holderId, addr_);
    }

    /**
     * @notice batch version of removeWalletFromHolder
     * @param addresses_ array of addresses to remove
     */
    function batchRemoveWalletFromHolder(
        address[] calldata addresses_
    ) external onlyWalletsAdminOrTransferAdmin {
        uint256 _len = addresses_.length;
        for (uint256 i; i < _len; ++i) {
            removeWalletFromHolder(addresses_[i]);
        }
    }

    /**
     * @dev Append a new wallet to existing Holder
     * @param addr_ address of holder
     * @param holderId_ id of holder
     */
    function _appendHolderAddress(
        address addr_,
        uint256 holderId_
    ) internal onlyExistingHolder(holderId_) onlyWalletsAdminOrTransferAdmin {
        if (addressHasHolder(addr_)) {
            revert RestrictedLockupToken_AddressAlreadyHasHolder();
        }
        if (walletAddressesByHolderId[holderId_].length >= MAX_WALLETS_PER_HOLDER) {
            revert RestrictedLockupToken_MaxHolderAddressesReached();
        }

        holderIdByAddress[addr_] = holderId_;
        walletAddressesByHolderId[holderId_].push(addr_);

        emit AppendHolderAddress(addr_, holderId_);
    }

    /**
     * @dev Allows the contract admin to pause transfers.
     * @param isPaused_ true to pause
     */
    function pause(bool isPaused_) external onlyContractAdminOrTransferAdmin {
        isPaused = isPaused_;
        emit Pause(_msgSender(), isPaused_);
    }

    /**
     * @dev Freezes or unfreezes an address.
     * Tokens in a frozen address cannot be transferred from until the address is unfrozen.
     * @param addr_ The address to be frozen.
     * @param status_ The frozenAddress status of the address. True means frozen false means not frozen.
     */
    function freeze(
        address addr_,
        bool status_
    ) public validAddress(addr_) onlyWalletsAdminOrTransferAdmin {
        frozenAddresses[addr_] = status_;
        emit AddressFrozen(_msgSender(), addr_, status_);
    }


    /**
    * @dev Count total holdings for an address by counting set bits in bitmap
    * @param who_ the address to get the holding count for
    * @return number of total unique holdings this wallet has across all token types
    */
    function holdingCountOf(address who_) external view returns (uint256) {
        uint256 count = 0;

        for (uint256 i = 0; i < walletIndexesByType[who_].length; i++) {
            count += walletIndexesByType[who_][i].popcount256B();
        }

        return count;
    }

    /**
     * @notice Get the struct details for an address's specific holding (optimized direct bitmap iteration)
     * @param who_ Address to check
     * @param index_ The index of the holding (position among wallet's holdings, not global index)
     * @return Struct with the attributes of the holding (balance, mintTimestamp, tokenType)
     */
    function holdingOf(
        address who_,
        uint256 index_
    ) public view returns (uint256, uint256, uint256) {
        // Find the global index for this wallet's targetIndex_-th holding
        uint256 globalIndex = _findGlobalIndexForWalletHolding(who_, index_);

        // If invalid index was provided, return zeros
        if (globalIndex == type(uint256).max) {
            return (0, 0, 0);
        }

        // Get element from global registry
        uint256 element = BitManipulationLib.getPackedElement(
            globalMintTimestamps[globalIndex / slotsPerWord],
            globalIndex % slotsPerWord,
            elementBitSize
        );
        (uint256 tokenType, uint256 daysAfterDeployment) = BitManipulationLib.unpackElement(element);

        // Get real balance (considering overflow)
        uint256 balance = _getRealBalance(who_, globalIndex);

        return (
            balance,
            BitManipulationLib.daysSinceDeployToTimestamp(daysAfterDeployment, deploymentDay),
            tokenType
        );
    }

    /**
     * @dev Find the global index for a wallet's Nth holding
     * @param who_ The wallet address
     * @param targetIndex_ The position among wallet's holdings (0-indexed)
     * @return globalIndex The global index, or type(uint256).max if invalid
     */
    function _findGlobalIndexForWalletHolding(
        address who_,
        uint256 targetIndex_
    ) internal view returns (uint256) {
        uint256 foundCount = 0;

        // Iterate through bitmap words to find the targetIndex_-th set bit
        for (uint256 wordIndex = 0; wordIndex < walletIndexesByType[who_].length; wordIndex++) {
            uint256 word = walletIndexesByType[who_][wordIndex];
            if (word == 0) continue;

            // Count set bits in this word
            uint256 bitsInWord = word.popcount256B();

            if (foundCount + bitsInWord > targetIndex_) {
                // The target bit is in this word
                uint256 targetBitInWord = targetIndex_ - foundCount;

                // Find the targetBitInWord-th set bit in this word
                for (uint256 bitIndex = 0; bitIndex < 256; bitIndex++) {
                    if ((word >> bitIndex) & 1 == 1) {
                        if (targetBitInWord == 0) {
                            // Found the target bit
                            return wordIndex * 256 + bitIndex;
                        }
                        targetBitInWord--;
                    }
                }
            }

            foundCount += bitsInWord;
        }

        // Index out of bounds
        return type(uint256).max;
    }

    /**
     * @dev Allows the contract admin to upgrade the transfer rules. onlyContractAdmin access.
     * The upgraded transfer rules must implement the ITransferRules interface which conforms to the ERC-1404 token standard.
     * @param newTransferRules The address of the deployed TransferRules contract.
     */
    function upgradeTransferRules(
        ITransferRules newTransferRules
    ) external onlyContractAdmin {
        address _newTransferRulesAddress = address(newTransferRules);
        if (_newTransferRulesAddress == address(0)) {
            revert RestrictedLockupToken_InvalidTransferRules();
        }
        if (
            !IERC165(_newTransferRulesAddress).supportsInterface(
                _ITRANSFER_RULES_INTERFACE_ID
            )
        ) {
            revert RestrictedLockupToken_NewTransferRulesContractDoesNotImplementITransferRules();
        }

        address oldRules = address(transferRules);

        transferRules = newTransferRules;
        emit Upgrade(_msgSender(), oldRules, _newTransferRulesAddress);
    }

    /**
     * @dev Allows the contract admin to upgrade the identity registry. onlyContractAdmin access.
     * The upgraded identity registry must implement the IIdentityRegistry interface.
     * @param newIdentityRegistry The address of the deployed IdentityRegistry contract.
     */
    function upgradeIdentityRegistry(
        IIdentityRegistry newIdentityRegistry
    ) external onlyContractAdmin {
        address _newIdentityRegistryAddress = address(newIdentityRegistry);
        if (_newIdentityRegistryAddress == address(0)) {
            revert RestrictedLockupToken_InvalidIdentityRegistry();
        }
        if (
            !IERC165(_newIdentityRegistryAddress).supportsInterface(
                _IIDENTITY_REGISTRY_INTERFACE_ID
            )
        ) {
            revert RestrictedLockupToken_NewIdentityRegistryContractDoesNotImplementIIdentityRegistry();
        }

        address oldIdentityRegistry = address(identityRegistry);

        identityRegistry = newIdentityRegistry;
        emit Upgrade(_msgSender(), oldIdentityRegistry, _newIdentityRegistryAddress);
    }

        /**
     * @dev Checks the status of an address to see if its frozen
     * @param addr_ The address to check
     * @return status Returns true if the address is frozen and false if its not frozen.
     */
    function getFrozenStatus(
        address addr_
    ) external view returns (bool status) {
        return frozenAddresses[addr_];
    }

    /**
     * @dev Get status of address
     * @param transferRulesAddr_ The address of the new transfer rules contract
     * @return _isValidTransferRules True if the transfer rules contract is valid
     */
    function isValidTransferRules(
        address transferRulesAddr_
    ) external view virtual returns (bool) {
        return
            IERC165(transferRulesAddr_).supportsInterface(
                _ITRANSFER_RULES_INTERFACE_ID
            );
    }

    /**
     * @dev Get status of identity registry address
     * @param identityRegistryAddr_ The address of the new identity registry contract
     * @return _isValidIdentityRegistry True if the identity registry contract is valid
     */
    function isValidIdentityRegistry(
        address identityRegistryAddr_
    ) external view virtual returns (bool) {
        return
            IERC165(identityRegistryAddr_).supportsInterface(
                _IIDENTITY_REGISTRY_INTERFACE_ID
            );
    }

    /**
     * @dev Get the count of existing token types
     * @return Number of token types that have been used
     */
    function existingTokenTypesCount() external view returns (uint256) {
        return _existingTokenTypes.length;
    }

    function existingTokenTypes(uint256 index) external view returns (uint256) {
        return _existingTokenTypes[index];
    }

    /**
     * @dev Check if a token type exists in the system
     * @param tokenType The token type to check
     * @return True if the token type has been used
     */
    function tokenTypeExists(uint256 tokenType) external view returns (bool) {
        return _tokenTypeExists[tokenType];
    }
}

contracts/RestrictedSwap.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.8.28;

import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import {IERC165, ERC165} from "@openzeppelin/contracts/utils/introspection/ERC165.sol";
import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ERC2771Context} from "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import {Context} from "@openzeppelin/contracts/utils/Context.sol";
import {IRestrictedSwap} from "./interfaces/IRestrictedSwap.sol";
import {RestrictedLockupToken} from "./RestrictedLockupToken.sol";
import {IAccessControl} from "./interfaces/IAccessControl.sol";
import {IERC1404} from "./interfaces/IERC1404.sol";
import {Pausable} from "@openzeppelin/contracts/utils/Pausable.sol";
import "./AccessControlErrors.sol";

contract RestrictedSwap is
    IRestrictedSwap,
    ReentrancyGuard,
    ERC165,
    Pausable,
    ERC2771Context
{
    RestrictedLockupToken public immutable restrictedLockupToken;
    IAccessControl public accessControl;

    using SafeERC20 for IERC20;

    /// @dev swap number
    uint256 public _swapNumber = 0;
    bytes4 public immutable INTERFACE_ID;

    /// @dev swap number => swap
    mapping(uint256 => Swap) private _swap;

    /// @dev userAddress => tokenAddress => the required allowance of tokens to swapContract by active swaps
    mapping(address => mapping(address => uint256)) private _requiredAllowance; // specific to configurer. Is a requirement!

    /// @dev userAddress => pending restricted tokens to buy - configured by another users
    mapping(address => uint256) private _pendingBuys;

    // @dev userAddress => pending restricted tokens to sell - configured by current user
    mapping(address => uint256) private _pendingSells;

    error RestrictedSwap_AlreadyCanceled();
    error RestrictedSwap_AlreadyCompleted();
    error RestrictedSwap_InvalidRestrictedTokenAmount();
    error RestrictedSwap_InvalidQuoteTokenAmount();
    error RestrictedSwap_QuoteTokenMustNotSupportIERC1404();
    error RestrictedSwap_InvalidQuoteTokenSender();
    error RestrictedSwap_InvalidQuoteToken();
    error RestrictedSwap_InvalidRestrictedTokenSender();
    error RestrictedSwap_InsufficientQuoteTokenAmount();
    error RestrictedSwap_InsufficientRestrictedTokenAmount();
    error RestrictedSwap_InvalidTokenSender();
    error RestrictedSwap_InvalidSwapStatus();
    error RestrictedSwap_InsufficientRestrictedTokenAllowance();
    error RestrictedSwap_InsufficientQuoteTokenAllowance();
    error RestrictedSwap_InconsistentQuoteTokenAmount();
    error RestrictedSwap_InconsistentRestrictedTokenAmount();
    error RestrictedSwap_SwapNotConfigured();
    error RestrictedSwap_InvalidCanceler();
    error RestrictedSwap_InvalidSwapRecord();
    error RestrictedSwap_InvalidAccessControl();
    error RestrictedSwap_InvalidRestrictedLockupToken();
    error RestrictedSwap_InvalidTrustedForwarder();
    error RestrictedSwap_SwapExpired();

    modifier onlyValidSwap(uint256 swapNumber_) {
        Swap memory swap = _swap[swapNumber_];
        _onlyActiveSwap(swap.status);
        // Check if swap has expired (deadline > 0 and current time > deadline)
        _onlyValidDeadline(swap.deadline);
        _;
    }

    modifier onlyActiveSwap(uint256 swapNumber_) {
        Swap memory swap = _swap[swapNumber_];
        _onlyActiveSwap(swap.status);
        _;
    }
    function _onlyActiveSwap(SwapStatus status_) internal view {
        if (status_ == SwapStatus.Canceled) {
            revert RestrictedSwap_AlreadyCanceled();
        }
        if (status_ == SwapStatus.Complete) {
            revert RestrictedSwap_AlreadyCompleted();
        }
    }

    modifier onlyValidDeadline(uint256 deadline_) {
        _onlyValidDeadline(deadline_);
        _;
    }
    function _onlyValidDeadline(uint256 deadline_) internal view {
        if (deadline_ > 0 && block.timestamp > deadline_) {
            revert RestrictedSwap_SwapExpired();
        }
    }

    constructor(
        address restrictedLockupTokenAddress_,
        address trustedForwarder_,
        address accessControl_
    ) 
        ReentrancyGuard() 
        ERC2771Context(trustedForwarder_)
    {
        if (accessControl_ == address(0)) {
            revert RestrictedSwap_InvalidAccessControl();
        }
        if (restrictedLockupTokenAddress_ == address(0)) {
            revert RestrictedSwap_InvalidRestrictedLockupToken();
        }
        if (trustedForwarder_ == address(0)) {
            revert RestrictedSwap_InvalidTrustedForwarder();
        }
        restrictedLockupToken = RestrictedLockupToken(
            restrictedLockupTokenAddress_
        );
        INTERFACE_ID = type(IRestrictedSwap).interfaceId;

        accessControl = IAccessControl(accessControl_);
    }

    function _msgSender()
        internal
        view
        override(Context, ERC2771Context)
        returns (address sender)
    {
        return ERC2771Context._msgSender();
    }

    function _msgData()
        internal
        view
        override(Context, ERC2771Context)
        returns (bytes calldata)
    {
        return ERC2771Context._msgData();
    }

    function _contextSuffixLength()
        internal
        view
        override(Context, ERC2771Context)
        returns (uint256)
    {
        return ERC2771Context._contextSuffixLength();
    }

    /**
     * Support of ERC165
     * @dev See https://eips.ethereum.org/EIPS/eip-165
     * @param interfaceId The interface identifier, as specified in ERC-165
     */
    function supportsInterface(
        bytes4 interfaceId
    ) public view override(ERC165, IERC165) returns (bool) {
        return
            interfaceId == INTERFACE_ID || super.supportsInterface(interfaceId);
    }

    /**
     * @dev pause contract. Only contract admin.
     */
    function pause(bool isPaused_) external onlyContractAdminOrTransferAdmin {
        if (isPaused_) {
            _pause();
        } else {
            _unpause();
        }
    }

    modifier onlyContractAdminOrTransferAdmin() {
        _onlyContractAdminOrTransferAdmin();
        _;
    }

    function _onlyContractAdminOrTransferAdmin() internal view {
        if (
            !accessControl.hasRole(_msgSender(), accessControl.CONTRACT_ADMIN_ROLE()) &&
            !accessControl.hasRole(_msgSender(), accessControl.TRANSFER_ADMIN_ROLE())
        ) {
            revert EasyAccessControl_DoesNotHaveContractOrTransferAdminRole(_msgSender());
        }
    }

    /**
     * @dev Get the swap number counter value
     */
    function swapNumber() external view returns (uint256) {
        return _swapNumber;
    }

    /**
     * @dev Get the allowance required for active swaps for the wallet address and token address.
            Can be used by UI client to calculate the required allowance before creating the swap
     * @param addr Wallet address
     * @param token ERC-20 token address
     */
    function requiredAllowance(
        address addr,
        address token
    ) external view returns (uint256) {
        return _requiredAllowance[addr][token];
    }


    /**
     * @dev Pending buy transactions for the wallet address
     * @param addr Buyer address
     * @return pending restricted tokens to buy
     */
    function pendingBuys(address addr) external view returns (uint256) {
        return _pendingBuys[addr];
    }

    /**
     * @dev Pending sell transactions for the wallet address
     * @param addr Seller address
     * @return pending restricted tokens to sell
     */
    function pendingSells(address addr) external view returns (uint256) {
        return _pendingSells[addr];
    }

    /**
     * @dev Calculate required allowance for counterparty across active swaps (paginated)
     * @param addr Counterparty address
     * @param token Token address
     * @param pageNumber Page number (0-based) to calculate allowance for
     * @param pageSize Number of swaps per page (recommended: 100-1000 for gas efficiency)
     * @return total Required allowance amount for the specified page of swaps
     */
    function calculateCounterpartyAllowance(
        address addr,
        address token,
        uint256 pageNumber,
        uint256 pageSize
    ) external view returns (uint256 total) {
        // Calculate pagination bounds
        if (pageSize == 0) {
            return 0; // Invalid page size
        }

        uint256 startSwap = pageNumber * pageSize + 1;
        uint256 endSwap = startSwap + pageSize - 1;

        // Ensure we don't exceed the total number of swaps
        if (endSwap > _swapNumber) {
            endSwap = _swapNumber;
        }

        // If startSwap is beyond total swaps, return 0
        if (startSwap > _swapNumber) {
            return 0;
        }

        // Iterate through the specified page range
        for (uint256 i = startSwap; i <= endSwap; i++) {
            Swap storage swap = _swap[i];
            if (swap.status == SwapStatus.SellConfigured) {
                // Check if addr is counterparty for quote token in sell swaps
                if (swap.quoteTokenSender == addr && swap.quoteToken == token) {
                    total += swap.quoteTokenAmount;
                }
            } else if (swap.status == SwapStatus.BuyConfigured) {
                // Check if addr is counterparty for restricted token in buy swaps
                if (swap.restrictedTokenSender == addr && token == address(restrictedLockupToken)) {
                    total += swap.restrictedTokenAmount;
                }
            }
        }
    }

    /**
     *  @dev Configure sell and emit an event with new swap number
     *       Restricted Tokens should be approved to this contract before calling this function
     *  @param restrictedTokenAmount the required amount for the erc1404Sender to send
     *  @param quoteToken the address of an erc1404 or erc20 that will be swapped
     *  @param quoteTokenSender the address that is approved to fund quoteToken
     *  @param quoteTokenAmount the required amount of quoteToken to swap
     *  @param deadline the deadline for swap expiration (0 means no deadline)
     */
    function configureSell(
        uint256 restrictedTokenAmount,
        address quoteToken,
        address quoteTokenSender,
        uint256 quoteTokenAmount,
        uint256 deadline
    ) external override whenNotPaused onlyValidDeadline(deadline) {
        if (quoteTokenSender == address(0)) {
            revert RestrictedSwap_InvalidQuoteTokenSender();
        }
        if (quoteToken == address(0)) {
            revert RestrictedSwap_InvalidQuoteToken();
        }
        address msgSender = _msgSender();
        if (
            restrictedLockupToken.allowance(msgSender, address(this)) <
            _requiredAllowance[msgSender][address(restrictedLockupToken)] +
                restrictedTokenAmount
        ) {
            revert RestrictedSwap_InsufficientRestrictedTokenAllowance();
        }

        _pendingSells[msgSender] += restrictedTokenAmount;

        _configureSwap(
            msgSender,
            quoteTokenSender,
            quoteToken,
            restrictedTokenAmount,
            quoteTokenAmount,
            SwapStatus.SellConfigured,
            deadline
        );
    }

    /**
     *  @dev Configure buy and emit an event with new swap number
     *  @param restrictedTokenAmount the required amount for the erc1404Sender to send
     *  @param restrictedTokenSender restricted token sender
     *  @param quoteToken the address of an erc1404 or erc20 that will be swapped
     *  @param quoteTokenAmount the required amount of quoteToken to swap
     *  @param deadline the deadline for swap expiration (0 means no deadline)
     */
    function configureBuy(
        uint256 restrictedTokenAmount,
        address restrictedTokenSender,
        address quoteToken,
        uint256 quoteTokenAmount,
        uint256 deadline
    ) external override whenNotPaused onlyValidDeadline(deadline) {
        if (restrictedTokenSender == address(0)) {
            revert RestrictedSwap_InvalidRestrictedTokenSender();
        }
        if (quoteToken == address(0)) {
            revert RestrictedSwap_InvalidQuoteToken();
        }
        address msgSender = _msgSender();
        if (IERC20(quoteToken).balanceOf(msgSender) < quoteTokenAmount) {
            revert RestrictedSwap_InsufficientQuoteTokenAmount();
        }
        if (
            IERC20(quoteToken).allowance(msgSender, address(this)) <
            _requiredAllowance[msgSender][quoteToken] + quoteTokenAmount
        ) {
            revert RestrictedSwap_InsufficientQuoteTokenAllowance();
        }

        _pendingBuys[restrictedTokenSender] += restrictedTokenAmount;

        _configureSwap(
            restrictedTokenSender,
            msgSender,
            quoteToken,
            restrictedTokenAmount,
            quoteTokenAmount,
            SwapStatus.BuyConfigured,
            deadline
        );
    }

    /**
     *  @dev Complete swap with quote token
     *  @param swapNumber_ swap number
     */
    function completeSwapWithQuoteToken(
        uint256 swapNumber_
    ) external override nonReentrant onlyValidSwap(swapNumber_) whenNotPaused {
        Swap memory swap = _swap[swapNumber_];

        if (swap.quoteTokenSender != _msgSender()) {
            revert RestrictedSwap_InvalidTokenSender();
        }
        if (swap.status != SwapStatus.SellConfigured) {
            revert RestrictedSwap_InvalidSwapStatus();
        }
        if (
            IERC20(swap.quoteToken).balanceOf(swap.quoteTokenSender) <
            swap.quoteTokenAmount
        ) {
            revert RestrictedSwap_InsufficientQuoteTokenAmount();
        }
        if (
            restrictedLockupToken.balanceOf(swap.restrictedTokenSender) <
            swap.restrictedTokenAmount
        ) {
            revert RestrictedSwap_InsufficientRestrictedTokenAmount();
        }

        uint256 code = restrictedLockupToken.detectTransferRestriction(
            swap.restrictedTokenSender,
            swap.quoteTokenSender,
            swap.restrictedTokenAmount
        );

        require(
            restrictedLockupToken.transferRules().checkSuccess(code),
            restrictedLockupToken.transferRules().messageForTransferRestriction(
                code
            )
        );

        _pendingSells[swap.restrictedTokenSender] -= swap.restrictedTokenAmount;

        _completeSwap(swapNumber_);
    }

    /**
     *  @dev Complete swap with restricted token
     *  @param swapNumber_ swap number
     */
    function completeSwapWithRestrictedToken(
        uint256 swapNumber_
    ) external override nonReentrant onlyValidSwap(swapNumber_) whenNotPaused {
        Swap memory swap = _swap[swapNumber_];

        if (swap.restrictedTokenSender != _msgSender()) {
            revert RestrictedSwap_InvalidTokenSender();
        }
        if (swap.status != SwapStatus.BuyConfigured) {
            revert RestrictedSwap_InvalidSwapStatus();
        }
        if (
            IERC20(swap.quoteToken).balanceOf(swap.quoteTokenSender) <
            swap.quoteTokenAmount
        ) {
            revert RestrictedSwap_InsufficientQuoteTokenAmount();
        }
        if (
            restrictedLockupToken.balanceOf(swap.restrictedTokenSender) <
            swap.restrictedTokenAmount
        ) {
            revert RestrictedSwap_InsufficientRestrictedTokenAmount();
        }

        uint256 code = restrictedLockupToken.detectTransferRestriction(
            swap.restrictedTokenSender,
            swap.quoteTokenSender,
            swap.restrictedTokenAmount
        );

        require(
            restrictedLockupToken.transferRules().checkSuccess(code),
            restrictedLockupToken.transferRules().messageForTransferRestriction(
                code
            )
        );

        _pendingBuys[swap.restrictedTokenSender] -= swap.restrictedTokenAmount;

        _completeSwap(swapNumber_);
    }

    /**
     *  @dev cancel swap
     *  @param swapNumber_ swap number
     */
    function cancelSwap(
        uint256 swapNumber_
    ) external override nonReentrant onlyActiveSwap(swapNumber_) {
        Swap memory swap = _swap[swapNumber_];

        if (
            swap.restrictedTokenSender == address(0) ||
            swap.quoteTokenSender == address(0)
        ) {
            revert RestrictedSwap_SwapNotConfigured();
        }

        // Check if swap has expired
        bool isExpired = swap.deadline > 0 && block.timestamp > swap.deadline;

        address msgSender = _msgSender();
        // Update pending amounts and required allowances
        if (swap.status == SwapStatus.SellConfigured) {
            if (!isExpired && msgSender != swap.restrictedTokenSender) {
                revert RestrictedSwap_InvalidCanceler();
            }
            _pendingSells[swap.restrictedTokenSender] -= swap
                .restrictedTokenAmount;
            _requiredAllowance[swap.restrictedTokenSender][
                address(restrictedLockupToken)
            ] -= swap.restrictedTokenAmount;
        } else if (swap.status == SwapStatus.BuyConfigured) {
            if (!isExpired && msgSender != swap.quoteTokenSender) {
                revert RestrictedSwap_InvalidCanceler();
            }
            _pendingBuys[swap.restrictedTokenSender] -= swap
                .restrictedTokenAmount;
            _requiredAllowance[swap.quoteTokenSender][swap.quoteToken] -= swap
                .quoteTokenAmount;
        }

        _swap[swapNumber_].status = SwapStatus.Canceled;

        emit SwapCanceled(msgSender, swapNumber_);
    }

    /**
     * @dev Returns the swap status if exists
     * @param swapNumber_ swap number
     * @return SwapStatus status of the swap record
     */
    function swapStatus(
        uint256 swapNumber_
    ) external view override returns (SwapStatus) {
        if (_swap[swapNumber_].restrictedTokenSender == address(0)) {
            revert RestrictedSwap_InvalidSwapRecord();
        }
        return _swap[swapNumber_].status;
    }

    /**
     * @dev Check if a swap has expired based on its deadline
     * @param swapNumber_ swap number
     * @return bool true if the swap has expired, false otherwise
     */
    function isSwapExpired(uint256 swapNumber_) external view override returns (bool) {
        Swap memory swap = _swap[swapNumber_];
        if (swap.restrictedTokenSender == address(0)) {
            revert RestrictedSwap_InvalidSwapRecord();
        }
        // Check if swap has expired (deadline > 0 and current time > deadline)
        return swap.deadline > 0 && block.timestamp > swap.deadline;
    }


    /**
     * @dev Configures swap and emits an event. This function does not fund tokens. Only for swap configuration.
     * @param restrictedTokenSender restricted token sender
     * @param quoteTokenSender quote token sender
     * @param quoteToken quote token
     * @param restrictedTokenAmount restricted token amount
     * @param quoteTokenAmount quote token amount
     * @param configuror initial status or configuration type for the swap
     * @param deadline the deadline for swap expiration (0 means no deadline)
     */
    function _configureSwap(
        address restrictedTokenSender,
        address quoteTokenSender,
        address quoteToken,
        uint256 restrictedTokenAmount,
        uint256 quoteTokenAmount,
        SwapStatus configuror,
        uint256 deadline
    ) private {
        if (restrictedTokenAmount == 0) {
            revert RestrictedSwap_InvalidRestrictedTokenAmount();
        }
        if (quoteTokenAmount == 0) {
            revert RestrictedSwap_InvalidQuoteTokenAmount();
        }

        uint256 code = restrictedLockupToken.detectTransferRestriction(
            restrictedTokenSender,
            quoteTokenSender,
            restrictedTokenAmount
        );

        string memory message = restrictedLockupToken
            .messageForTransferRestriction(code);

        require(
            restrictedLockupToken.transferRules().checkSuccess(code),
            message
        );

        try
            IERC165(quoteToken).supportsInterface(type(IERC1404).interfaceId)
        returns (bool supported1404) {
            if (supported1404) {
                revert RestrictedSwap_QuoteTokenMustNotSupportIERC1404();
            }
            // happy path, ie ERC1404 is not supported, even if ERC165 is supported
        } catch {
            // happy path, ie ERC165 is not supported. Most ERC-20 tokens do not support ERC-165
        }

        _swapNumber += 1;

        Swap storage swap = _swap[_swapNumber];
        swap.restrictedTokenSender = restrictedTokenSender;
        swap.restrictedTokenAmount = restrictedTokenAmount;
        swap.quoteTokenSender = quoteTokenSender;
        swap.quoteTokenAmount = quoteTokenAmount;
        swap.quoteToken = quoteToken;
        swap.status = configuror;
        swap.deadline = deadline;

        if (configuror == SwapStatus.SellConfigured) {
            _requiredAllowance[swap.restrictedTokenSender][
                address(restrictedLockupToken)
            ] += restrictedTokenAmount;
        } else {
            _requiredAllowance[swap.quoteTokenSender][
                quoteToken
            ] += quoteTokenAmount;
        }

        emit SwapConfigured(
            _swapNumber,
            restrictedTokenSender,
            restrictedTokenAmount,
            quoteToken,
            quoteTokenSender,
            quoteTokenAmount,
            deadline
        );
    }

    /**
     * @dev Complete swap and emit an event
     * @param swapNumber_ swap number
     */
    function _completeSwap(uint256 swapNumber_) private {
        Swap memory swap = _swap[swapNumber_];

        uint256 balanceBeforeTransfer = IERC20(swap.quoteToken).balanceOf(
            swap.restrictedTokenSender
        );

        IERC20(swap.quoteToken).safeTransferFrom(
            swap.quoteTokenSender,
            swap.restrictedTokenSender,
            swap.quoteTokenAmount
        );

        uint256 balanceAfterTransfer = IERC20(swap.quoteToken).balanceOf(
            swap.restrictedTokenSender
        );

        if (
            balanceAfterTransfer - balanceBeforeTransfer !=
            swap.quoteTokenAmount
        ) {
            revert RestrictedSwap_InconsistentQuoteTokenAmount();
        }

        uint256 _restrictedTokenBalanceBefore = restrictedLockupToken.balanceOf(
            swap.quoteTokenSender
        );
        restrictedLockupToken.transferFrom(
            swap.restrictedTokenSender,
            swap.quoteTokenSender,
            swap.restrictedTokenAmount
        );

        uint256 _restrictedTokenBalanceAfter = restrictedLockupToken.balanceOf(
            swap.quoteTokenSender
        );
        if (
            _restrictedTokenBalanceAfter - _restrictedTokenBalanceBefore !=
            swap.restrictedTokenAmount
        ) {
            revert RestrictedSwap_InconsistentRestrictedTokenAmount();
        }

        if (swap.status == SwapStatus.SellConfigured) {
            _requiredAllowance[swap.restrictedTokenSender][
                address(restrictedLockupToken)
            ] -= swap.restrictedTokenAmount;
        } else if (swap.status == SwapStatus.BuyConfigured) {
            _requiredAllowance[swap.quoteTokenSender][swap.quoteToken] -= swap
                .quoteTokenAmount;
        }

        _swap[swapNumber_].status = SwapStatus.Complete;

        emit SwapComplete(
            swapNumber_,
            swap.restrictedTokenSender,
            swap.restrictedTokenAmount,
            swap.quoteTokenSender,
            swap.quoteToken,
            swap.quoteTokenAmount,
            swap.deadline
        );
    }
}

contracts/SnapshotPeriods.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

import {RestrictedLockupToken} from "./RestrictedLockupToken.sol";
import {ISnapshotPeriods} from "./interfaces/ISnapshotPeriods.sol";
import {ERC165} from "@openzeppelin/contracts/utils/introspection/ERC165.sol";

contract SnapshotPeriods is ISnapshotPeriods, ERC165 {
    bytes4 public immutable INTERFACE_ID;

    mapping(address token => mapping(address account => WalletInfo))
        public walletInfo;
    mapping(address token => mapping(address account => Period[]))
        public walletPeriods;

    // total supply periods
    mapping(address token => Period[]) public totalSupplyPeriods;
    // total supply info
    mapping(address token => WalletInfo) public totalSupplyInfo;

    error SnapshotPeriods_InvalidToken();
    error SnapshotPeriods_UnauthorizedCaller();
    error SnapshotPeriods_TimestampInFuture();
    constructor() {
        INTERFACE_ID = type(ISnapshotPeriods).interfaceId;
    }

    /**
     * Support of ERC165
     * @dev See https://eips.ethereum.org/EIPS/eip-165
     * @param interfaceId The interface identifier, as specified in ERC-165
     */
    function supportsInterface(
        bytes4 interfaceId
    ) public view override returns (bool) {
        return
            interfaceId == INTERFACE_ID || super.supportsInterface(interfaceId);
    }

    /// @inheritdoc ISnapshotPeriods
    function getPastBalanceOf(
        address token,
        address account,
        uint256 timestamp
    ) public view returns (uint256) {
        if (timestamp >= block.timestamp) {
            revert SnapshotPeriods_TimestampInFuture();
        }
        return ownershipForPeriod(token, account, timestamp, timestamp + 1);
    }

    /// @inheritdoc ISnapshotPeriods
    function getPastTotalSupply(
        address token,
        uint256 timestamp
    ) public view returns (uint256) {
        if (timestamp >= block.timestamp) {
            revert SnapshotPeriods_TimestampInFuture();
        }
        return totalOwnershipForPeriod(token, timestamp, timestamp + 1);
    }

    /// @inheritdoc ISnapshotPeriods
    function onUpdate(
        address tokenAddress,
        address from,
        address to,
        uint256 amount
    ) external {
        if (msg.sender != tokenAddress) {
            revert SnapshotPeriods_UnauthorizedCaller();
        }
        if (amount == 0) {
            return;
        }

        if (from != address(0)) {
            _updatePeriods(tokenAddress, from, amount);
        }
        if (to != address(0)) {
            _updatePeriods(
                tokenAddress,
                to,
                0 // for recipient, we don't need to validate if new balance is 0
            );
        }
        // update total supply periods only for mint or burn when total supply is changed
        if (from == address(0) || to == address(0)) {
            _updateTotalSupplyPeriods(
                tokenAddress,
                to == address(0) ? amount : 0 // for burn, we need to clear latestAccrualTimestamp if new total supply is 0
            );
        }
    }

    function calculateOwnershipForPeriod(
        uint256 amount,
        uint256 periodStart,
        uint256 periodEnd
    ) public pure returns (uint256) {
        return amount * (periodEnd - periodStart);
    }

    function _updateTotalSupplyPeriods(
        address tokenAddress,
        uint256 amount
    ) internal {
        uint256 totalAccruedOwnership = totalSupplyInfo[tokenAddress]
            .totalAccruedOwnership;
        RestrictedLockupToken token = RestrictedLockupToken(tokenAddress);
        uint256 currentTimestamp = block.timestamp;
        if (
            totalSupplyInfo[tokenAddress].latestAccrualTimestamp >=
            currentTimestamp
        ) {
            return; // not need to update periods
        }

        uint256 curentTotalSupply = token.totalSupply();
        if (totalSupplyInfo[tokenAddress].latestAccrualTimestamp > 0) {
            uint256 periodOwnership = calculateOwnershipForPeriod(
                curentTotalSupply,
                totalSupplyInfo[tokenAddress].latestAccrualTimestamp,
                currentTimestamp
            );
            totalAccruedOwnership += periodOwnership;
            totalSupplyPeriods[tokenAddress].push(
                Period({
                    start: totalSupplyInfo[tokenAddress].latestAccrualTimestamp,
                    end: currentTimestamp,
                    totalAccruedOwnership: totalAccruedOwnership,
                    accruedOwnership: periodOwnership
                })
            );
            totalSupplyInfo[tokenAddress].periodCount++;
            totalSupplyInfo[tokenAddress]
                .totalAccruedOwnership = totalAccruedOwnership;
        }

        if (amount != 0 && curentTotalSupply == amount) {
            totalSupplyInfo[tokenAddress].latestAccrualTimestamp = 0;
        } else {
            totalSupplyInfo[tokenAddress]
                .latestAccrualTimestamp = currentTimestamp;
        }
    }

    function _updatePeriods(
        address tokenAddress,
        address account,
        uint256 amount
    ) internal {
        WalletInfo memory accountInfo = walletInfo[tokenAddress][account];

        uint256 totalAccruedOwnership = accountInfo.totalAccruedOwnership;
        RestrictedLockupToken token = RestrictedLockupToken(tokenAddress);
        uint256 currentTimestamp = block.timestamp;
        if (accountInfo.latestAccrualTimestamp >= currentTimestamp) {
            return; // not need to update periods
        }

        uint256 currentBalance = token.balanceOf(account);
        if (accountInfo.latestAccrualTimestamp > 0) {
            uint256 periodOwnership = calculateOwnershipForPeriod(
                currentBalance,
                accountInfo.latestAccrualTimestamp,
                currentTimestamp
            );
            totalAccruedOwnership += periodOwnership;
            walletPeriods[tokenAddress][account].push(
                Period({
                    start: accountInfo.latestAccrualTimestamp,
                    end: currentTimestamp,
                    totalAccruedOwnership: totalAccruedOwnership,
                    accruedOwnership: periodOwnership
                })
            );
            accountInfo.periodCount++;
            accountInfo.totalAccruedOwnership = totalAccruedOwnership;
        }

        if (amount != 0 && currentBalance == amount) {
            accountInfo.latestAccrualTimestamp = 0;
        } else {
            accountInfo.latestAccrualTimestamp = currentTimestamp;
        }

        walletInfo[tokenAddress][account] = accountInfo;
    }

    // @dev calculate total ownership at timestamp
    // @param token The token address
    // @param timestamp The timestamp to calculate the ownership at
    // @return ownership The ownership at the timestamp
    function totalOwnershipAt(
        address token,
        uint256 timestamp
    ) public view returns (uint256) {
        WalletInfo memory totalSupplyInfoNow = supplyInfo(token);
        if (
            totalSupplyInfoNow.periodCount == 0 &&
            totalSupplyInfoNow.latestAccrualTimestamp == 0
        ) {
            return 0;
        }
        // end timestamp can be before last account accrual timestamp
        // in this case, we should find period which includes timestamp and use previous period
        uint256 periodIdx = type(uint256).max;
        uint256 totalSupplyAccruedOwnership = totalSupplyInfoNow
            .totalAccruedOwnership;
        timestamp = timestamp > block.timestamp ? block.timestamp : timestamp;
        if (
            (timestamp <= totalSupplyInfoNow.latestAccrualTimestamp ||
                totalSupplyInfoNow.latestAccrualTimestamp == 0) &&
            totalSupplyInfoNow.periodCount > 0
        ) {
            periodIdx = findTotalSupplyPeriodIndexForTimestamp(
                token,
                timestamp
            );
            if (periodIdx == type(uint256).max) {
                // no previous period found -> no accrued ownership
                totalSupplyAccruedOwnership = 0;
            }
            if (periodIdx != type(uint256).max) {
                // we found previous period
                Period memory period = totalSupplyPeriodByIndex(
                    token,
                    periodIdx
                );
                totalSupplyAccruedOwnership = period.totalAccruedOwnership;
            }
        }

        bool isIncludedPeriodExists = false;
        // if included period already cached
        if (
            (periodIdx != type(uint256).max &&
                totalSupplyInfoNow.periodCount > periodIdx + 1) ||
            (periodIdx == type(uint256).max &&
                totalSupplyInfoNow.periodCount > 0)
        ) {
            Period memory period = totalSupplyPeriodByIndex(
                token,
                periodIdx == type(uint256).max ? 0 : periodIdx + 1
            );
            isIncludedPeriodExists =
                period.start < timestamp &&
                timestamp <= period.end;
            if (isIncludedPeriodExists) {
                uint256 portion = timestamp - period.start;
                uint256 portionOfOwnership = (period.accruedOwnership *
                    portion) / (period.end - period.start);
                totalSupplyAccruedOwnership += portionOfOwnership;
            }
        }

        // (   ](   ](   timestamp ..... now
        //           | latestAccrualTimestamp
        // if included period not cached - still ongoing
        if (
            totalSupplyInfoNow.latestAccrualTimestamp != 0 &&
            totalSupplyInfoNow.latestAccrualTimestamp < timestamp &&
            periodIdx == type(uint256).max
        ) {
            RestrictedLockupToken restrictedLockupToken = RestrictedLockupToken(
                token
            );
            uint256 ownershipAccrued = calculateOwnershipForPeriod(
                restrictedLockupToken.totalSupply(),
                totalSupplyInfoNow.latestAccrualTimestamp,
                timestamp
            );
            totalSupplyAccruedOwnership += ownershipAccrued;
        }

        return totalSupplyAccruedOwnership;
    }

    // @dev calculate ownership at timestamp
    // @param token The token address
    // @param account The account address
    // @param timestamp The timestamp to calculate the ownership at
    // @return ownership The ownership at the timestamp
    function ownershipAt(
        address token,
        address account,
        uint256 timestamp
    ) public view returns (uint256) {
        RestrictedLockupToken restrictedLockupToken = RestrictedLockupToken(
            token
        );
        WalletInfo memory accountInfo = addressInfo(token, account);
        if (
            accountInfo.periodCount == 0 &&
            accountInfo.latestAccrualTimestamp == 0
        ) {
            return 0;
        }
        // end timestamp can be before last account accrual timestamp
        // in this case, we should find period which includes timestamp and use previous period
        uint256 periodIdx = type(uint256).max;
        uint256 accountAccruedOwnership = accountInfo.totalAccruedOwnership;
        timestamp = timestamp > block.timestamp ? block.timestamp : timestamp;
        if (
            (timestamp <= accountInfo.latestAccrualTimestamp ||
                accountInfo.latestAccrualTimestamp == 0) &&
            accountInfo.periodCount > 0
        ) {
            periodIdx = findPeriodIndexForTimestamp(token, account, timestamp);
            if (periodIdx == type(uint256).max) {
                // no previous period found -> no accrued ownership
                accountAccruedOwnership = 0;
            }
            if (periodIdx != type(uint256).max) {
                // we found previous period
                Period memory period = walletPeriodByIndex(
                    token,
                    account,
                    periodIdx
                );
                accountAccruedOwnership = period.totalAccruedOwnership;
            }
        }

        bool isIncludedPeriodExists = false;
        // if included period already cached
        if (
            (periodIdx != type(uint256).max &&
                accountInfo.periodCount > periodIdx + 1) ||
            (periodIdx == type(uint256).max && accountInfo.periodCount > 0)
        ) {
            Period memory period = walletPeriodByIndex(
                token,
                account,
                periodIdx == type(uint256).max ? 0 : periodIdx + 1
            );
            isIncludedPeriodExists =
                period.start < timestamp &&
                timestamp <= period.end;
            if (isIncludedPeriodExists) {
                uint256 portion = timestamp - period.start;
                uint256 portionOfOwnership = (period.accruedOwnership *
                    portion) / (period.end - period.start);
                accountAccruedOwnership += portionOfOwnership;
            }
        }

        // (   ](   ](   timestamp ..... now
        //           | latestAccrualTimestamp
        // if included period not cached - still ongoing
        if (
            accountInfo.latestAccrualTimestamp != 0 &&
            accountInfo.latestAccrualTimestamp < timestamp &&
            (periodIdx == type(uint256).max)
        ) {
            uint256 ownershipAccrued = calculateOwnershipForPeriod(
                restrictedLockupToken.balanceOf(account),
                accountInfo.latestAccrualTimestamp,
                timestamp
            );
            accountAccruedOwnership += ownershipAccrued;
        }

        return accountAccruedOwnership;
    }

    function totalOwnershipForPeriod(
        address token,
        uint256 startTimestamp,
        uint256 endTimestamp
    ) public view returns (uint256) {
        if (startTimestamp >= endTimestamp) {
            return 0;
        }

        return
            totalOwnershipAt(token, endTimestamp) -
            totalOwnershipAt(token, startTimestamp);
    }

    function ownershipForPeriod(
        address token,
        address account,
        uint256 startTimestamp,
        uint256 endTimestamp
    ) public view returns (uint256) {
        if (startTimestamp >= endTimestamp) {
            return 0;
        }

        return
            ownershipAt(token, account, endTimestamp) -
            ownershipAt(token, account, startTimestamp);
    }

    function addressInfo(
        address token,
        address account
    ) public view returns (WalletInfo memory) {
        return walletInfo[token][account];
    }

    function supplyInfo(address token) public view returns (WalletInfo memory) {
        return totalSupplyInfo[token];
    }

    function walletPeriodByIndex(
        address token,
        address account,
        uint256 index
    ) public view returns (Period memory) {
        return walletPeriods[token][account][index];
    }

    function totalSupplyPeriodByIndex(
        address token,
        uint256 index
    ) public view returns (Period memory) {
        return totalSupplyPeriods[token][index];
    }

    /**
     * @dev Find the period index for a wallet address that the nearest period that ends before the timestamp
     * if no period includes it
     * @param token The token address
     * @param account The wallet address to check
     * @param timestamp The timestamp to find the period for
     * @return periodIndex The index of the period that nearest to the timestamp,
     * or type(uint256).max if no suitable period is found
     */
    function findPeriodIndexForTimestamp(
        address token,
        address account,
        uint256 timestamp
    ) public view returns (uint256 periodIndex) {
        WalletInfo memory accountWalletInfo = addressInfo(token, account);

        // If no periods exist for this wallet, return max value to indicate not found
        if (accountWalletInfo.periodCount == 0) {
            return type(uint256).max;
        }

        // Binary search to efficiently find the period
        uint256 low = 0;
        uint256 high = accountWalletInfo.periodCount - 1;
        uint256 nearestLeftPeriod = type(uint256).max;

        while (low <= high) {
            uint256 mid = (low + high) / 2;
            Period memory currentPeriod = walletPeriods[token][account][mid];

            // Check if timestamp is in this period (timestamp > start && timestamp <= end)
            if (
                timestamp > currentPeriod.start &&
                timestamp <= currentPeriod.end
            ) {
                return mid > 0 ? mid - 1 : type(uint256).max; // return previous period
            }

            // If timestamp is before this period's start, search in the lower half
            if (timestamp <= currentPeriod.start) {
                // If we're at index 0, we can't go lower
                if (mid == 0) {
                    break;
                }
                high = mid - 1;
            }
            // If timestamp is after this period's end, search in the upper half
            // and update the nearest left period if this period ends before the timestamp
            else {
                // This period ends before the timestamp, so it's a candidate for nearest left period
                if (
                    currentPeriod.end < timestamp &&
                    (nearestLeftPeriod == type(uint256).max ||
                        currentPeriod.end >
                        walletPeriods[token][account][nearestLeftPeriod].end)
                ) {
                    nearestLeftPeriod = mid;
                }
                low = mid + 1;
            }
        }

        // If we found a nearest left period, return it
        if (nearestLeftPeriod != type(uint256).max) {
            return nearestLeftPeriod;
        }

        // If we get here, no period includes the timestamp and no nearest left period was found
        return type(uint256).max;
    }

    /**
     * @dev Find the period index for the total supply that ends before the timestamp
     * @param token The token address
     * @param timestamp The timestamp to find the period for
     * @return periodIndex The index of the previous period if timestamp is within a period,
     * or the nearest period that ends before the timestamp if no period includes it,
     * or type(uint256).max if no suitable period is found
     */
    function findTotalSupplyPeriodIndexForTimestamp(
        address token,
        uint256 timestamp
    ) public view returns (uint256 periodIndex) {
        // If no periods exist for total supply, return max value to indicate not found
        if (totalSupplyInfo[token].periodCount == 0) {
            return type(uint256).max;
        }

        // Binary search to efficiently find the period
        uint256 low = 0;
        uint256 high = totalSupplyInfo[token].periodCount - 1;
        uint256 nearestLeftPeriod = type(uint256).max;

        while (low <= high) {
            uint256 mid = (low + high) / 2;
            Period memory currentPeriod = totalSupplyPeriods[token][mid];

            // Check if timestamp is in this period (timestamp > start && timestamp <= end)
            if (
                timestamp > currentPeriod.start &&
                timestamp <= currentPeriod.end
            ) {
                return mid > 0 ? mid - 1 : type(uint256).max; // return previous period
            }

            // If timestamp is before this period's start, search in the lower half
            if (timestamp <= currentPeriod.start) {
                // If we're at index 0, we can't go lower
                if (mid == 0) {
                    break;
                }
                high = mid - 1;
            }
            // If timestamp is after this period's end, search in the upper half
            // and update the nearest left period if this period ends before the timestamp
            else {
                // This period ends before the timestamp, so it's a candidate for nearest left period
                if (
                    currentPeriod.end < timestamp &&
                    (nearestLeftPeriod == type(uint256).max ||
                        currentPeriod.end >
                        totalSupplyPeriods[token][nearestLeftPeriod].end)
                ) {
                    nearestLeftPeriod = mid;
                }
                low = mid + 1;
            }
        }

        // If we found a nearest left period, return it
        if (nearestLeftPeriod != type(uint256).max) {
            return nearestLeftPeriod;
        }

        // If we get here, no period includes the timestamp and no nearest left period was found
        return type(uint256).max;
    }

    function walletPeriodCount(
        address token,
        address account
    ) public view returns (uint256) {
        return walletInfo[token][account].periodCount;
    }

    function totalSupplyPeriodCount(
        address token
    ) public view returns (uint256) {
        return totalSupplyInfo[token].periodCount;
    }

    function totalSupplyPeriodAccruedOwnership(
        address token,
        uint256 index
    ) public view returns (uint256) {
        return totalSupplyPeriods[token][index].totalAccruedOwnership;
    }

    function walletPeriodAccruedOwnership(
        address token,
        address account,
        uint256 index
    ) public view returns (uint256) {
        return walletPeriods[token][account][index].totalAccruedOwnership;
    }
}

contracts/Storage.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.8.28;

import {ITransferRules} from "./interfaces/ITransferRules.sol";
import {ISnapshotPeriods} from "./interfaces/ISnapshotPeriods.sol";
import {IIdentityRegistry} from "./interfaces/IIdentityRegistry.sol";
import {IAccessControl} from "./interfaces/IAccessControl.sol";
import {BitManipulationLib} from "./libraries/BitManipulationLib.sol";
import "./AccessControlErrors.sol";

/**
 * @title Storage
 * @notice Shared storage contract for RestrictedLockupToken and its extensions
 * @dev Both main contract and extensions inherit from this to ensure identical storage layout
 */
contract Storage {
    using BitManipulationLib for uint256;

    struct ReleaseSchedule {
        uint256 releaseCount;
        uint256 delayUntilFirstReleaseInSeconds;
        uint256 initialReleasePortionInBips;
        uint256 periodBetweenReleasesInSeconds;
    }

    struct Timelock {
        address funder;
        uint256 scheduleId;
        uint256 commencementTimestamp;
        uint256 tokensTransferred;
        uint256 totalAmount;
        uint256 globalHoldingIndex; // Global index for token type + daysAfterDeployment combination
        address[] cancelableBy; // not cancelable unless set at the time of funding
    }

    // ============================================
    // CORE CONTRACT REFERENCES
    // ============================================
    ITransferRules public transferRules;
    ISnapshotPeriods public snapshotPeriods;
    IIdentityRegistry public identityRegistry;
    address public restrictedLockupTokenManagementExtension;
    address public restrictedLockupTokenExtension;
    IAccessControl public accessControl; // external access control contract

    // ============================================
    // RELEASE SCHEDULES AND TIMELOCKS
    // ============================================
    ReleaseSchedule[] public releaseSchedules;
    // wallet address => timelock details
    mapping(address => Timelock[]) internal timelocks;
    uint256 public minTimelockAmount;
    bool public snapshotsEnabled;
    bool public recordMintTimestamp;
    uint256 public recordPausedOnDaysAfterDeployment;

    // ============================================
    // HOLDER MANAGEMENT STATE
    // ============================================
    uint256 internal holderIds; // starts at 1 for 1st holder
    uint256 public holderMax = 2 ** 255 - 1; // Maximum uint256 value - walletsMax
    uint256 public holderCount;
    // wallet address => holderId
    mapping(address => uint256) internal holderIdByAddress;
    // holderId => wallet addresses
    mapping(uint256 => address[]) internal walletAddressesByHolderId;

    // ============================================
    // TOKEN STATE
    // ============================================
    bool public isPaused;
    // address => isFrozen
    mapping(address => bool) internal frozenAddresses;
    uint256 public maxTotalSupply;

    // ============================================
    // SLOT CONFIGURATION
    // ============================================
    /// @dev Number of slots per 256-bit word, calculated based on maxTotalSupply and decimals
    /// @dev Determines how many balance values can fit in a single storage slot
    uint256 public immutable slotsPerWord;

    /// @dev Number of bits per element (tokenType + daysAfterDeployment) or balance
    /// @dev Calculated as 256 / slotsPerWord
    uint256 public immutable elementBitSize;

    uint256 public immutable maxBalancePerSubIndex;

    // ============================================
    // MULTI-TYPE TOKEN FUNCTIONALITY (OPTIMIZED)
    // ============================================

    // Deployment day rounded up to midnight for calculating days since deploy
    uint256 public deploymentDay;

    // Global registry of packed 256-bit structures, each containing slotsPerWord elements
    // Each uint256 stores slotsPerWord elements of: [8 bits: tokenType][elementBitSize-8 bits: daysAfterDeployment]
    // This creates direct 1:1 mapping to packedBalancesByTypeAndTime storage slots
    uint256[] public globalMintTimestamps;

    // Count of elements in globalMintTimestamps (for efficient validation)
    uint256 public mintTimestampCount;

    // Wallet ownership bitmaps: address => uint256[] (each uint256 = 256 bits)
    // Each bit represents ownership of a global TokenTypeMintTimestamp combination
    mapping(address => uint256[]) internal walletIndexesByType;

    // ============================================
    // PACKED BALANCE STORAGE OPTIMIZATION
    // ============================================

    // Packed balance storage: address => packed TokenTypeMintTimestamp (without subIndex) => packed balances
    // Each uint256 stores slotsPerWord balances for example for 8 elements
    // (uint32 each): [bal7][bal6][bal5][bal4][bal3][bal2][bal1][bal0]
    mapping(address => mapping(uint256 => uint256)) internal packedBalancesByTypeAndTime;

    // Overflow balance storage for amounts > uint32..64 max
    // Used when packed balance == maxBalancePerSubIndex (uint32..64 max)
    // Mapping: address => globalIndex => actual overflow amount
    mapping(address => mapping(uint256 => uint256)) internal overflowBalances;

    // Global registry of all token types that have been used
    uint256[] internal _existingTokenTypes;
    mapping(uint256 => bool) internal _tokenTypeExists;
    mapping(uint256 => uint256) internal _tokenTypeIndex; // tokenType => index in _existingTokenTypes array

    // ============================================
    // FALLBACK PATTERN STATE
    // ============================================

    uint256 public maxReleaseDelay;
    uint8 public constant MAX_CANCELABLE_BY = 10;
    uint256 internal constant MAX_TIMELOCKS = 10_000;
    uint256 public constant MAX_WALLETS_PER_HOLDER = 10;
    string public constant contractVersion = "5.0.0";
    bytes4 public constant _ITRANSFER_RULES_INTERFACE_ID =
        type(ITransferRules).interfaceId;
    bytes4 public constant _IIDENTITY_REGISTRY_INTERFACE_ID =
        type(IIdentityRegistry).interfaceId;

    // ============================================
    // EVENTS
    // ============================================

    // Multi-type token events
    event TokenTypeMinted(
        address indexed to,
        uint256 amount,
        uint256 indexed tokenType,
        uint256 timestamp
    );

    event TokenTypeTransferred(
        address indexed from,
        address indexed to,
        uint256 amount,
        uint256 indexed tokenType
    );

    event TokenTypeBurned(
        address indexed from,
        uint256 amount,
        uint256 indexed tokenType
    );

    event TokenHoldingsMerged(
        address indexed wallet,
        uint256 indexed tokenType,
        uint256 holdingsMerged,
        uint256 totalAmount,
        uint256 newMintTimestamp
    );

    /// @notice This event is emitted when a schedule is funded
    /// @param from The address of the funder
    /// @param to The address of the recipient of the tokens when schedule is released
    /// @param scheduleId The id of the release schedule
    /// @param amount The amount of tokens to be released
    /// @param commencementTimestamp The timestamp when the release schedule starts
    /// @param timelockId The id of the timelock
    /// @param cancelableBy The addresses that can cancel the timelock
    event ScheduleFunded(
        address indexed from,
        address indexed to,
        uint256 indexed scheduleId,
        uint256 amount,
        uint256 commencementTimestamp,
        uint256 timelockId,
        address[] cancelableBy
    );

    /// @notice This event is emitted when a timelock is canceled
    /// @param canceledBy The address of the canceller
    /// @param target The address of the recipient of the unlocked tokens
    /// @param timelockIndex The index of the timelock in the timelocks array
    /// @param reclaimTokenTo The address of the recipient of the locked tokens
    /// @param canceledAmount The total amount of canceled tokens
    /// @param paidAmount The amount of paid tokens to target
    event TimelockCanceled(
        address indexed canceledBy,
        address indexed target,
        uint256 indexed timelockIndex,
        address reclaimTokenTo,
        uint256 canceledAmount,
        uint256 paidAmount
    );

    /// @notice This event is emitted when a transfer rules is updated
    /// @param admin The address of the admin
    /// @param oldRules The old transfer rules contract address
    /// @param newRules The new transfer rules contract address
    event Upgrade(
        address indexed admin,
        address indexed oldRules,
        address indexed newRules
    );

    /// @notice This event is emitted when a force transfer between wallets is executed by admin
    /// @param admin The address of the admin
    /// @param from The address of the sender
    /// @param to The address of the recipient
    /// @param amount The amount of tokens to transfer
    event ForceTransferBetween(
        address indexed admin,
        address indexed from,
        address indexed to,
        uint256 amount
    );

    /// @notice This event is emitted when an updated max total supply
    /// @param admin The address of the admin
    /// @param maxTotalSupply The new max total supply
    event SetMaxTotalSupply(address indexed admin, uint256 maxTotalSupply);

    /// @notice This event is emitted when a holder is created
    /// @param holderId The id of the holder
    /// @param addr The primary address of the holder
    event HolderCreated(uint256 indexed holderId, address indexed addr);

    /// @notice This event is emitted when an append new wallet address to existing holder
    /// @param addr The address of the wallet
    /// @param holderId The id of the holder
    event AppendHolderAddress(address indexed addr, uint256 indexed holderId);

    /// @notice This event is emitted when an updated holder max limit
    /// @param admin The address of the admin
    /// @param holderMax The new holder max limit
    event SetHolderMax(address indexed admin, uint256 holderMax);

    /// @notice This event is emitted when a holder is removed
    /// @param admin The address of the admin
    /// @param holderId The id of the holder
    event RemoveHolder(address indexed admin, uint256 indexed holderId);

    /// @notice This event is emitted when a wallet address is removed from a given holderId
    /// @param admin The address of the tx sender
    /// @param holderId The id of the holder
    /// @param addr The primary address of the holder to be removed
    event RemoveWalletFromHolder(
        address indexed admin,
        uint256 indexed holderId,
        address indexed addr
    );

    /// @notice This event is emitted when a new release schedule is created
    /// @param from The address of the schedule creator
    /// @param scheduleId The id of the new release schedule
    event ScheduleCreated(address indexed from, uint256 indexed scheduleId);

    /// @notice This event is emitted when a holding's token type is updated
    /// @param admin The address of the admin performing the update
    /// @param wallet The wallet address whose holding is being updated
    /// @param oldTokenType The previous token type
    /// @param newTokenType The new token type
    /// @param mintTimestamp The mint timestamp of the holding
    /// @param amount The amount of tokens in the holding
    event HoldingTokenTypeUpdated(
        address indexed admin,
        address indexed wallet,
        uint256 indexed oldTokenType,
        uint256 newTokenType,
        uint256 mintTimestamp,
        uint256 amount
    );

    /// @notice This event is emitted when a timelock's token type is updated
    /// @param admin The address of the admin performing the update
    /// @param wallet The wallet address whose timelock is being updated
    /// @param timelockIndex The index of the timelock
    /// @param oldTokenType The previous token type
    /// @param newTokenType The new token type
    /// @param amount The total amount of tokens in the timelock
    event TimelockTokenTypeUpdated(
        address indexed admin,
        address indexed wallet,
        uint256 indexed timelockIndex,
        uint256 oldTokenType,
        uint256 newTokenType,
        uint256 amount
    );

    /// @notice This event is emitted when a address is frozen or unfrozen
    /// @param admin The address of the admin
    /// @param addr The (un)frozen address
    /// @param status true - frozen, false - unfrozen
    event AddressFrozen(
        address indexed admin,
        address indexed addr,
        bool indexed status
    );

    /// @notice This event is emitted when a contract is paused or unpaused
    /// @param admin The address of the admin
    /// @param status true - paused, false - unpaused
    event Pause(address indexed admin, bool indexed status);

    // ============================================
    // TOKENTYPE-TIMESTAMP PACKING UTILITIES
    // ============================================

    // Constants moved to BitManipulationLib - keeping references for compatibility
    uint256 internal constant TOKEN_TYPE_BITS = BitManipulationLib.TOKEN_TYPE_BITS;
    uint256 internal constant TOKEN_TYPE_MASK = BitManipulationLib.TOKEN_TYPE_MASK;

    // ============================================
    // WRAPPER FUNCTIONS REMOVED - USE BitManipulationLib DIRECTLY
    // ============================================

    /**
     * @dev Get token type from global index
     * @param globalIndex The global index
     * @return tokenType The token type
     */
    function _getTokenTypeFromGlobalIndex(uint256 globalIndex) internal view returns (uint256 tokenType) {
        uint256 packed = globalMintTimestamps[globalIndex / slotsPerWord];
        uint256 element = BitManipulationLib.getPackedElement(packed, globalIndex % slotsPerWord, elementBitSize);
        (tokenType, ) = BitManipulationLib.unpackElement(element);
    }

    /**
     * @dev Get token type and mint timestamp from global index
     * @param globalIndex The global index
     * @return tokenType The token type
     * @return mintTimestamp The mint timestamp
     */
    function _getTokenTypeAndMintTimestampFromGlobalIndex(uint256 globalIndex) internal view returns (uint256 tokenType, uint256 mintTimestamp) {
        uint256 packed = globalMintTimestamps[globalIndex / slotsPerWord];
        uint256 element = BitManipulationLib.getPackedElement(packed, globalIndex % slotsPerWord, elementBitSize);
        uint256 daysAfterDeployment;
        (tokenType, daysAfterDeployment) = BitManipulationLib.unpackElement(element);
        mintTimestamp = BitManipulationLib.daysSinceDeployToTimestamp(daysAfterDeployment, deploymentDay);
    }

    // ============================================
    // RESTRICTED LOCKUP TOKEN ERRORS
    // ============================================

    error RestrictedLockupToken_HolderAlreadyExists();
    error RestrictedLockupToken_AddressAlreadyHasHolder();
    error RestrictedLockupToken_MaxHolderAddressesReached();
    error RestrictedLockupToken_NewHolderMaxMustExceedCurrentHolderCount();
    error RestrictedLockupToken_MaxHolderCountReached();
    error RestrictedLockupToken_HolderAddressDoesNotExist();
    error RestrictedLockupToken_HolderDoesNotExist();
    error RestrictedLockupToken_InvalidName();
    error RestrictedLockupToken_InvalidSymbol();
    error RestrictedLockupToken_InvalidTransferRules();
    error RestrictedLockupToken_InvalidAccessControl();
    error RestrictedLockupToken_InvalidMinTimelockAmount();
    error RestrictedLockupToken_InvalidNumberOfRelases();
    error RestrictedLockupToken_InvalidRInitialReleaseBIPS();
    error RestrictedLockupToken_InvalidReleasePeriod();
    error RestrictedLockupToken_InvalidReleasePortionForSingleRelease();
    error RestrictedLockupToken_RecipientAndAmountLengthsShouldMatch();
    error RestrictedLockupToken_NewTransferRulesContractDoesNotImplementITransferRules();
    error RestrictedLockupToken_NewIdentityRegistryContractDoesNotImplementIIdentityRegistry();
    error RestrictedLockupToken_MismatchedArrayLength();
    error RestrictedLockupToken_SenderCannotBeRecipient(address sender);
    error RestrictedLockupToken_InvalidAmount();
    error RestrictedLockupToken_InvalidZeroAddress();
    error RestrictedLockupToken_CannotExceedMaxTotalSupply();
    error RestrictedLockupToken_MaxCancelersExceeded();
    error RestrictedLockupToken_InvalidAddressArray();
    error RestrictedLockupToken_NewMaxTotalSupplyMustExceedCurrentTotalSupply();
    error RestrictedLockupToken_SafeApprove();
    error RestrictedLockupToken_InvalidFirstRelease();
    error RestrictedLockupToken_InvalidTimelock();
    error RestrictedLockupToken_InvalidReclaimTo();
    error RestrictedLockupToken_TimelockCannotBeCanceled();
    error RestrictedLockupToken_ScheduleIdDoesNotMatch();
    error RestrictedLockupToken_CommencementTimestampDoesNotMatch();
    error RestrictedLockupToken_TotalAmountDoesNotMatch();
    error RestrictedLockupToken_TimelockHasNoValueRemaining();
    error RestrictedLockupToken_AmountExceedsUnlockedBalance();
    error RestrictedLockupToken_InsufficientTotalBalanceOf();
    error RestrictedLockupToken_NoHoldingWithEnoughBalance();
    error RestrictedLockupToken_MaxTimelocksExceeded();
    error RestrictedLockupToken_InvalidFundAmount();
    error RestrictedLockupToken_InvalidFundAddress();
    error RestrictedLockupToken_InvalidScheduleId();
    error RestrictedLockupToken_AmountLessThanReleaseCount();
    error RestrictedLockupToken_InitialReleaseOutOfRange();
    error RestrictedLockupToken_CannotRemoveLastWallet();
    error RestrictedLockupToken_InvalidTrustedForwarder();
    error RestrictedLockupToken_InvalidIdentityRegistry();
    error RestrictedLockupToken_ExtensionSlotsPerWordMismatch(uint256 expected, uint256 actual);
    error RestrictedLockupToken_InvalidRestrictedLockupTokenExtension();
    error RestrictedLockupToken_InvalidRestrictedLockupTokenManagementExtension();
    error RestrictedLockupToken_CannotRemoveHolderWithActiveTimelocks();
    error RestrictedLockupToken_InsufficientBurnableBalance();
    error RestrictedLockupToken_CantVestAllForMultipleReleases();
    error RestrictedLockupToken_InvalidTokenType();
    error RestrictedLockupToken_NoItemWithEnoughBalance();
    error RestrictedLockupToken_HoldingIndexOutOfBound();
    error RestrictedLockupToken_InvalidHolding();
    error RestrictedLockupToken_InvalidHoldingIndex();
    error RestrictedLockupToken_InvalidZeroAmount();
    error RestrictedLockupToken_MaxTotalSupplyTooLarge();
    error RestrictedLockupToken_TokenTypeNotAllowedForRecipient();
    error RestrictedLockupToken_AlreadySet();
    error RestrictedLockupToken_BalanceCheckFailed();

    // ============================================
    // INTERNAL FUNCTIONS
    // ============================================

    function _maxSafeSupply() internal pure returns (uint256) {
        return type(uint240).max;
    }

    /**
     * @dev Find or create optimized global index for TokenType + DaysAfterDeployment
     * @param tokenType The token type (0-255)
     * @param daysAfterDeployment The days after deployment
     * @return globalIndex The global index for this combination
     */
    function _findOrCreateOptimizedGlobalIndex(uint256 tokenType, uint256 daysAfterDeployment) internal returns (uint256) {
        // Create element for this token type and days
        uint256 element = BitManipulationLib.packElement(tokenType, daysAfterDeployment, elementBitSize);

        // Search from end to beginning to find same token type and daysAfterDeployment
        // Break early if we find a daysAfterDeployment > current (chronologically older)
        // Use direct bit manipulation instead of unpacking to save gas
        for (uint256 bucketIndex = globalMintTimestamps.length; bucketIndex > 0; bucketIndex--) {
            uint256 actualBucketIndex = bucketIndex - 1; // Convert to 0-based index
            uint256 packed = globalMintTimestamps[actualBucketIndex];

            // Check each element in this bucket (reverse order for better efficiency)
            // Work directly with packed bits instead of unpacking
            for (uint256 subIndex = slotsPerWord; subIndex > 0; subIndex--) {
                uint256 actualSubIndex = subIndex - 1; // Convert to 0-based index

                // Extract element directly from packed data using bit shifting
                uint256 currentElement = (packed >> (actualSubIndex * elementBitSize)) & ((1 << elementBitSize) - 1);

                if (currentElement == 0) {
                    continue; // Skip empty slots
                }

                if (currentElement == element) {
                    // Found existing combination - return its global index
                    return actualBucketIndex * slotsPerWord + actualSubIndex;
                }

                // Extract daysAfterDeployment directly from current element using bit manipulation
                uint256 currentDays = currentElement >> TOKEN_TYPE_BITS;

                // If current days > target days,
                // we can break early since items are generally added in chronological order
                if (currentDays < daysAfterDeployment) {
                    bucketIndex = 1; // Set to 1 so that outer for loop will terminate after decrement
                    break; // No point searching further, older entries won't match
                }
            }
        }

        // Element not found, add new item to the last available subindex or create new bucket
        if (globalMintTimestamps.length > 0) {
            // Try to add to the last bucket first
            uint256 lastBucketIndex = globalMintTimestamps.length - 1;
            uint256 packed = globalMintTimestamps[lastBucketIndex];

            // Find the first available slot in the last bucket using direct bit manipulation
            for (uint256 subIndex = 0; subIndex < slotsPerWord; subIndex++) {
                // Extract element directly from packed data
                uint256 currentElement = (packed >> (subIndex * elementBitSize)) & ((1 << elementBitSize) - 1);

                if (currentElement == 0) {
                    // Found empty slot in last bucket, use it
                    // Set the element directly in the packed data using bit manipulation
                    uint256 updatedPacked = packed | (element << (subIndex * elementBitSize));
                    globalMintTimestamps[lastBucketIndex] = updatedPacked;
                    mintTimestampCount++;
                    return lastBucketIndex * slotsPerWord + subIndex;
                }
            }
        }

        // Last bucket is full or no buckets exist, create new bucket with subindex 0
        // Use direct bit manipulation instead of array creation
        uint256 newBucketIndex = globalMintTimestamps.length;
        uint256 newPacked = element; // element goes to subIndex 0, all other slots are 0
        globalMintTimestamps.push(newPacked);
        mintTimestampCount++;

        return newBucketIndex * slotsPerWord; // subIndex = 0 for first element
    }

        /**
     * @dev Set a bit in the wallet's bitmap
     * @param account The wallet address
     * @param globalIndex The global index to set
     */
    function _setBitmapBit(address account, uint256 globalIndex) internal {
        uint256 wordIndex = globalIndex / 256;
        uint256 bitIndex = globalIndex % 256;

        // Ensure bitmap array is large enough
        while (walletIndexesByType[account].length <= wordIndex) {
            walletIndexesByType[account].push(0);
        }

        // Set the bit
        walletIndexesByType[account][wordIndex] |= (1 << bitIndex);
    }

    /**
     * @dev Register a token type in the global registry if it doesn't exist
     * @param tokenType The token type to register
     */
    function _registerTokenType(uint256 tokenType) internal {
        if (!_tokenTypeExists[tokenType]) {
            _tokenTypeIndex[tokenType] = _existingTokenTypes.length;
            _existingTokenTypes.push(tokenType);
            _tokenTypeExists[tokenType] = true;
        }
    }
    /**
     * @dev Adds a specified amount to the holdings of a given account at a specific global holding index.
     *      Handles packed storage and overflow for balances exceeding the maximum per sub-index.
     * @param account The address of the account to update holdings for
     * @param globalHoldingIndex The global index representing the token type and mint timestamp
     * @param amount The amount to add to the holdings
     */
    function _addToHoldingsByIndex(
        address account,
        uint256 globalHoldingIndex,
        uint256 amount
    ) internal {
        // Calculate subIndex from globalHoldingIndex
        uint256 subIndex = globalHoldingIndex % slotsPerWord;

        // Calculate bucket index (which globalMintTimestamps entry to use)
        uint256 bucketIndex = globalHoldingIndex / slotsPerWord;

        // Get current packed balances for this bucket
        uint256 currentPackedBalances = packedBalancesByTypeAndTime[account][bucketIndex];

        // Get current balance for this subIndex
        uint256 currentBalance = BitManipulationLib.getPackedBalance(currentPackedBalances, subIndex, elementBitSize);

        // Handle overflow balances: if current balance is max uint32, get real balance from overflow mapping
        uint256 realCurrentBalance = currentBalance;
        if (currentBalance == maxBalancePerSubIndex) {
            realCurrentBalance = overflowBalances[account][globalHoldingIndex];
        }

        // If this combination doesn't exist for this wallet yet, set bitmap bit
        if (currentBalance == 0) {
            // Set bitmap bit for this wallet
            _setBitmapBit(account, globalHoldingIndex);
        }

        // Calculate new total balance
        uint256 newTotalBalance = realCurrentBalance + amount;

        // Update balance in packed storage and overflow mapping as needed
        if (newTotalBalance < maxBalancePerSubIndex) {
            // Balance fits in uint32, store in packed storage
            packedBalancesByTypeAndTime[account][bucketIndex] = BitManipulationLib.setPackedBalance(
                currentPackedBalances,
                subIndex,
                newTotalBalance,
                elementBitSize
            );
            // Clear any existing overflow balance
            if (currentBalance == maxBalancePerSubIndex) {
                delete overflowBalances[account][globalHoldingIndex];
            }
        } else {
            // Balance exceeds uint32 max, store max in packed storage and real amount in overflow mapping
            packedBalancesByTypeAndTime[account][bucketIndex] = BitManipulationLib.setPackedBalance(
                currentPackedBalances,
                subIndex,
                maxBalancePerSubIndex,
                elementBitSize
            );
            overflowBalances[account][globalHoldingIndex] = newTotalBalance;
        }
    }

    /**
     * @dev Add tokens to holdings structure using optimized packed balance system
     * @param account The account to add tokens to
     * @param tokenType The type of tokens (0-255, uses 8 bits)
     * @param daysAfterDeployment The days after deployment of the tokens
     * @param amount The amount to add
     * @return globalIndex The global index for this token type + daysAfterDeployment combination
     */
    function _addToHoldingsByType(
        address account,
        uint256 tokenType,
        uint256 daysAfterDeployment,
        uint256 amount
    ) internal returns (uint256 globalIndex) {
        // Register token type globally if it doesn't exist
        _registerTokenType(tokenType);

        // Find or create the global index for this combination
        globalIndex = _findOrCreateOptimizedGlobalIndex(
            tokenType,
            daysAfterDeployment
        );

        _addToHoldingsByIndex(account, globalIndex, amount);
        return globalIndex;
    }

    /**
     * @dev Get the real balance for a specific holding, considering overflow storage
     * @param account The account to check
     * @param globalIndex The global index of the holding
     * @return balance The real balance (from packed storage or overflow mapping)
     */
    function _getRealBalance(address account, uint256 globalIndex) internal view returns (uint256) {
        uint256 subIndex = globalIndex % slotsPerWord;
        uint256 bucketIndex = globalIndex / slotsPerWord;

        uint256 currentPackedBalances = packedBalancesByTypeAndTime[account][bucketIndex];
        uint256 packedBalance = BitManipulationLib.getPackedBalance(currentPackedBalances, subIndex, elementBitSize);

        // If packed balance is max uint32, get real balance from overflow mapping
        if (packedBalance == maxBalancePerSubIndex) {
            return overflowBalances[account][globalIndex];
        }

        return packedBalance;
    }

    /**
    * @dev Clear a bit in the wallet's bitmap for a token type
    * @param account The wallet address
    * @param globalIndex The global index to clear
    */
    function _clearBitmapBit(address account, uint256 globalIndex) internal {
        uint256 wordIndex = globalIndex / 256;
        uint256 bitIndex = globalIndex % 256;

        if (wordIndex < walletIndexesByType[account].length) {
            walletIndexesByType[account][wordIndex] &= ~(1 << bitIndex);
        }
    }


    /**
     * @dev Enforces transfer restrictions managed using the ERC-1404 standard functions.
     * The TransferRules contract defines what the rules are. The data inputs to those rules remains in the RestrictedToken contract.
     * TransferRules is a separate contract so its logic can be upgraded.
     * @param from_ The address the tokens are transferred from
     * @param to_ The address the tokens would be transferred to
     * @param value_ the quantity of tokens to be transferred
     */
    function _enforceTransferRestrictions(
        address from_,
        address to_,
        uint256 value_
    ) internal view {
        uint256 _restrictionCode = transferRules.detectTransferRestrictionBasic(
            address(this),
            from_,
            to_,
            value_
        );
        // if (!transferRules.checkSuccess(_restrictionCode)) revert TransferRestricted(_restrictionCode);
        require(
            transferRules.checkSuccess(_restrictionCode),
            transferRules.messageForTransferRestriction(_restrictionCode)
        );
    }

    function _enforceTransferRestrictionsFor(
        uint256 tokenType_,
        uint256 mintTimestamp_,
        address recipient_
    ) internal view {
        IIdentityRegistry.IdentityInfo memory recipientIdentity = identityRegistry.identity(recipient_);
        bool isAmlKycPassed_ = identityRegistry.isAmlKycPassed(recipient_);
        uint256 _restrictionCode = transferRules.detectTransferRestrictionForHolding(
            tokenType_,
            mintTimestamp_,
            recipientIdentity,
            isAmlKycPassed_
        );
        require(
            transferRules.checkSuccess(_restrictionCode),
            transferRules.messageForTransferRestriction(_restrictionCode)
        );
    }

    /**
     * @dev Apply batched bitmap clearing to a specific word
     * @dev This replaces multiple _clearBitmapBit calls with a single AND operation
     */
    function _applyBitmaskToClear(
        address account,
        uint256 wordIndex,
        uint256 bitmaskToClear
    ) internal {
        if (wordIndex < walletIndexesByType[account].length) {
            // Clear all bitmap bits for this word at once (major gas optimization)
            walletIndexesByType[account][wordIndex] &= ~bitmaskToClear;
        }
    }

    /**
     * @dev check if address has holder
     * @param addr_ address to check
     * @return true if address has holder
     */
    function _addressHasHolder(address addr_) internal view returns (bool) {
        return holderIdByAddress[addr_] > 0;
    }

    /**
     * @param addr_ address to associate with holderId. First holder has holderId = 1.
     * @return _holderId holder id
     */
    function _createHolderFromAddress(
        address addr_
    ) internal returns (uint256 _holderId) {
        if (holderCount >= holderMax) {
            revert RestrictedLockupToken_MaxHolderCountReached();
        }
        holderCount++;
        holderIds += 1;
        _holderId = holderIds;

        holderIdByAddress[addr_] = _holderId;
        walletAddressesByHolderId[_holderId].push(addr_);

        emit HolderCreated(_holderId, addr_);
    }

    /**
     * @dev Generic helper for balance query staticcalls with consistent error handling
     * @param functionSignature The function signature to call (e.g., "superBalanceOf(address)")
     * @param account The account to query
     * @return balance The balance result
     */
    function _queryBalance(string memory functionSignature, address account) internal view returns (uint256 balance) {
        (bool success, bytes memory data) = address(this).staticcall(
            abi.encodeWithSignature(functionSignature, account)
        );
        if (!success) {
            revert RestrictedLockupToken_BalanceCheckFailed();
        }
        if (data.length < 32) {
            revert RestrictedLockupToken_BalanceCheckFailed();
        }
        return abi.decode(data, (uint256));
    }

    modifier validAddress(address addr_) {
        if (addr_ == address(0)) {
            revert EasyAccessControl_InvalidZeroAddress();
        }
        _;
    }

    modifier onlyExistingAddress(address addr_) {
        if (!_addressHasHolder(addr_)) {
            revert RestrictedLockupToken_HolderAddressDoesNotExist();
        }
        _;
    }

    modifier onlyReserveAdmin() {
        _onlyReserveAdmin();
        _;
    }

    modifier onlyTransferAdmin() {
        _onlyTransferAdmin();
        _;
    }

    modifier onlyReserveOrMintAdmin() {
        _onlyReserveOrMintAdmin();
        _;
    }

    modifier onlySoftBurnAdmin() {
        _onlySoftBurnAdmin();
        _;
    }

    modifier anyAdmin() {
        _anyAdmin();
        _;
    }

    modifier onlyWalletsAdminOrTransferAdmin() {
        _onlyWalletsAdminOrTransferAdmin();
        _;
    }

    modifier onlyContractAdminOrTransferAdmin() {
        _onlyContractAdminOrTransferAdmin();
        _;
    }

    modifier onlyContractAdmin() {
        _onlyContractAdmin();
        _;
    }

    function _anyAdmin() internal view {
        if (
            !accessControl.hasRole(_msgSender(), accessControl.RESERVE_ADMIN_ROLE()) &&
            !accessControl.hasRole(_msgSender(), accessControl.WALLETS_ADMIN_ROLE()) &&
            !accessControl.hasRole(_msgSender(), accessControl.TRANSFER_ADMIN_ROLE()) &&
            !accessControl.hasRole(_msgSender(), accessControl.CONTRACT_ADMIN_ROLE())
        ) {
            revert EasyAccessControl_DoesNotHaveAdminRole(_msgSender());
        }
    }

    function _onlyReserveAdmin() internal view {
        if (!accessControl.hasRole(_msgSender(), accessControl.RESERVE_ADMIN_ROLE())) {
            revert EasyAccessControl_DoesNotHaveReserveAdminRole(_msgSender());
        }
    }

    function _onlySoftBurnAdmin() internal view {
        if (!accessControl.hasRole(_msgSender(), accessControl.SOFT_BURN_ADMIN_ROLE())) {
            revert EasyAccessControl_DoesNotHaveSoftBurnAdminRole(_msgSender());
        }
    }

    function _onlyReserveOrMintAdmin() internal view {
        if (
            !accessControl.hasRole(_msgSender(), accessControl.RESERVE_ADMIN_ROLE()) &&
            !accessControl.hasRole(_msgSender(), accessControl.MINT_ADMIN_ROLE())
        ) {
            revert EasyAccessControl_DoesNotHaveAdminRole(_msgSender());
        }
    }

    function _onlyTransferAdmin() internal view {
        if (!accessControl.hasRole(_msgSender(), accessControl.TRANSFER_ADMIN_ROLE())) {
            revert EasyAccessControl_DoesNotHaveTransferAdminRole(_msgSender());
        }
    }

    function _onlyWalletsAdminOrTransferAdmin() internal view {
        if (
            !accessControl.hasRole(_msgSender(), accessControl.WALLETS_ADMIN_ROLE()) &&
            !accessControl.hasRole(_msgSender(), accessControl.TRANSFER_ADMIN_ROLE())
        ) {
            revert EasyAccessControl_DoesNotHaveAdminRole(_msgSender());
        }
    }

    function _onlyContractAdminOrTransferAdmin() internal view {
        if (
            !accessControl.hasRole(_msgSender(), accessControl.CONTRACT_ADMIN_ROLE()) &&
            !accessControl.hasRole(_msgSender(), accessControl.TRANSFER_ADMIN_ROLE())
        ) {
            revert EasyAccessControl_DoesNotHaveContractOrTransferAdminRole(_msgSender());
        }
    }

    function _onlyContractAdmin() internal view {
        if (!accessControl.hasRole(_msgSender(), accessControl.CONTRACT_ADMIN_ROLE())) {
            revert EasyAccessControl_DoesNotHaveContractAdminRole(_msgSender());
        }
    }

    /// @dev This function is intended to be overridden in child contracts (e.g., for ERC2771Context support)
    function _msgSender() internal view virtual returns (address) {
        return msg.sender;
    }
}

contracts/TransferRules.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.8.28;
import {ERC165} from "@openzeppelin/contracts/utils/introspection/ERC165.sol";
import {ITransferRules} from "./interfaces/ITransferRules.sol";
import {IIdentityRegistry} from "./interfaces/IIdentityRegistry.sol";
import {IRestrictedLockupToken} from "./interfaces/IRestrictedLockupToken.sol";
import {IAccessControl} from "./interfaces/IAccessControl.sol";
import {Context} from "@openzeppelin/contracts/utils/Context.sol";
import {ERC2771Context} from "@openzeppelin/contracts/metatx/ERC2771Context.sol";
import {IERC1404} from "./interfaces/IERC1404.sol";
import {AccessControl} from "./AccessControl.sol";
import "./AccessControlErrors.sol";

contract TransferRules is ITransferRules, ERC165, ERC2771Context {
    // ============================================
    // ORIGINAL TRANSFER RULES CONSTANTS & STORAGE
    // ============================================

    mapping(uint256 => string) internal errorMessage;

    uint256 public constant SUCCESS = 0;
    uint256 public constant GREATER_THAN_RECIPIENT_MAX_BALANCE = 1;
    uint256 public constant SENDER_TOKENS_TIME_LOCKED = 2;
    uint256 public constant DO_NOT_SEND_TO_TOKEN_CONTRACT = 3;
    uint256 public constant DO_NOT_SEND_TO_EMPTY_ADDRESS = 4;
    uint256 public constant SENDER_ADDRESS_FROZEN = 5;
    uint256 public constant ALL_TRANSFERS_PAUSED = 6;
    uint256 public constant RECIPIENT_ADDRESS_FROZEN = 7;
    uint256 public constant LOWER_THAN_RECIPIENT_MIN_BALANCE = 8;
    uint256 public constant INSUFFICIENT_BALANCE_OF_SENDER = 9;
    uint256 public constant SENDER_NOT_AMLKYCPASSED = 10;
    uint256 public constant RECIPIENT_NOT_AMLKYCPASSED = 11;
    uint256 public constant HOLDING_PERIOD_NOT_MET = 12;
    uint256 public constant NO_RULE_FOR_RECIPIENT = 13;
    uint256 public constant RECIPIENT_NOT_QUALIFIED = 14;

    uint256 public constant MAX_RESTRICTION_CODE = 14;

    bytes4 public immutable INTERFACE_ID;

    // ============================================
    // TOKEN TYPE RULES ENGINE STORAGE
    // ============================================

    // Constants for predefined token types
    uint256 public constant TOKEN_TYPE_GENERIC = 0;  // Generic/Default

    // Efficient lockup table: region -> accreditation -> TokenTypeRule
    mapping(uint256 => mapping(uint256 => TokenTypeRule)) private _tokenTypeRules;
    TokenTypeRule private _defaultTokenTypeRule;

    // ============================================
    // TOKEN TYPE TRANSFER RULES STORAGE
    // ============================================

    // Bit manipulation constants for packed TransferRule
    uint256 private constant IS_ACTIVE_MASK = 0x1;           // 0000...0001
    uint256 private constant REQUIRES_AML_KYC_MASK = 0x2;    // 0000...0010
    uint256 private constant FLAGS_MASK = 0x3;               // 0000...0011
    uint256 private constant LOCK_DURATION_SHIFT = 2;

    // Packed storage: tokenType -> region -> accreditation -> uint256 (packed TransferRule)
    // Bit layout: bits 0-1 = flags (isActive, requiresAmlKyc), bits 2-255 = lockDurationSeconds
    mapping(uint256 => mapping(uint256 => mapping(uint256 => uint256))) private _packedRules;


    modifier onlyTransferAdmin() {
        _onlyTransferAdmin();
        _;
    }
    function _onlyTransferAdmin() internal view {
        if (!accessControl.hasRole(_msgSender(), accessControl.TRANSFER_ADMIN_ROLE())) {
            revert EasyAccessControl_DoesNotHaveTransferAdminRole(_msgSender());
        }
    }

    // ============================================
    // PACKED TRANSFERRULE HELPER FUNCTIONS
    // ============================================

    /**
     * @dev Pack a TransferRule into a single uint256
     * @param lockDurationSeconds The lock duration in seconds
     * @param requiresAmlKyc Whether AML/KYC is required
     * @param isActive Whether the rule is active
     * @return packed The packed uint256 value
     */
    function _packRule(
        uint256 lockDurationSeconds,
        bool requiresAmlKyc,
        bool isActive
    ) private pure returns (uint256 packed) {
        packed = lockDurationSeconds << LOCK_DURATION_SHIFT;
        if (isActive) packed |= IS_ACTIVE_MASK;
        if (requiresAmlKyc) packed |= REQUIRES_AML_KYC_MASK;
    }

    /**
     * @dev Unpack a uint256 into TransferRule components
     * @param packed The packed uint256 value
     * @return lockDurationSeconds The lock duration in seconds
     * @return requiresAmlKyc Whether AML/KYC is required
     * @return isActive Whether the rule is active
     */
    function _unpackRule(uint256 packed) private pure returns (
        uint256 lockDurationSeconds,
        bool requiresAmlKyc,
        bool isActive
    ) {
        lockDurationSeconds = packed >> LOCK_DURATION_SHIFT;
        requiresAmlKyc = (packed & REQUIRES_AML_KYC_MASK) != 0;
        isActive = (packed & IS_ACTIVE_MASK) != 0;
    }

    // ============================================
    // ERRORS
    // ============================================

    error TransferRules_BadRestrictionCode();
    error TransferRules_InvalidAccessControl();
    error TransferRules_InvalidTrustedForwarder();
    error TransferRules_TokenTypeRuleNotFound();
    error TransferRules_RecipientNotAmlKycPassed();
    error TransferRules_InvalidTokenType();
    error TransferRules_InvalidArrayLengths();

    IAccessControl public accessControl;

    constructor(
        address trustedForwarder_,
        address accessControl_
    ) ERC2771Context(trustedForwarder_) {
        if (accessControl_ == address(0)) {
            revert TransferRules_InvalidAccessControl();
        } 
        if (trustedForwarder_ == address(0)) {
            revert TransferRules_InvalidTrustedForwarder();
        }
        // Initialize error messages
        errorMessage[SUCCESS] = "SUCCESS";
        errorMessage[
            LOWER_THAN_RECIPIENT_MIN_BALANCE
        ] = "LOWER THAN RECIPIENT MIN BALANCE";
        errorMessage[
            GREATER_THAN_RECIPIENT_MAX_BALANCE
        ] = "GREATER THAN RECIPIENT MAX BALANCE";
        errorMessage[SENDER_TOKENS_TIME_LOCKED] = "SENDER TOKENS LOCKED";
        errorMessage[
            DO_NOT_SEND_TO_TOKEN_CONTRACT
        ] = "DO NOT SEND TO TOKEN CONTRACT";
        errorMessage[
            DO_NOT_SEND_TO_EMPTY_ADDRESS
        ] = "DO NOT SEND TO EMPTY ADDRESS";
        errorMessage[SENDER_ADDRESS_FROZEN] = "SENDER ADDRESS IS FROZEN";
        errorMessage[ALL_TRANSFERS_PAUSED] = "ALL TRANSFERS PAUSED";
        errorMessage[RECIPIENT_ADDRESS_FROZEN] = "RECIPIENT ADDRESS IS FROZEN";
        errorMessage[
            INSUFFICIENT_BALANCE_OF_SENDER
        ] = "INSUFFICIENT BALANCE OF SENDER";
        errorMessage[SENDER_NOT_AMLKYCPASSED] = "SENDER NOT AMLKYCPASSED";
        errorMessage[RECIPIENT_NOT_AMLKYCPASSED] = "RECIPIENT NOT AMLKYCPASSED";
        errorMessage[HOLDING_PERIOD_NOT_MET] = "HOLDING PERIOD NOT MET";
        errorMessage[NO_RULE_FOR_RECIPIENT] = "NO RULE FOR RECIPIENT";
        errorMessage[RECIPIENT_NOT_QUALIFIED] = "RECIPIENT NOT QUALIFIED";

        INTERFACE_ID = type(ITransferRules).interfaceId;

        accessControl = IAccessControl(accessControl_);
    }

    /**
     * Support of ERC165
     * @dev See https://eips.ethereum.org/EIPS/eip-165
     * @param interfaceId The interface identifier, as specified in ERC-165
     */
    function supportsInterface(
        bytes4 interfaceId
    ) public view override returns (bool) {
        return
            interfaceId == INTERFACE_ID || super.supportsInterface(interfaceId);
    }

    /// @inheritdoc ITransferRules
    function detectTransferRestrictionBasic(
        address tokenAddr,
        address from,
        address to,
        uint256 value
    ) public view override returns (uint256) {
        IRestrictedLockupToken token = IRestrictedLockupToken(tokenAddr);

        // ============================================
        // TRADITIONAL TRANSFER RESTRICTION CHECKS
        // ============================================
        if (token.isPaused()) return ALL_TRANSFERS_PAUSED;
        if (to == address(0)) return DO_NOT_SEND_TO_EMPTY_ADDRESS;
        if (to == address(token)) return DO_NOT_SEND_TO_TOKEN_CONTRACT;
        if (token.getFrozenStatus(from)) return SENDER_ADDRESS_FROZEN;
        if (token.getFrozenStatus(to)) return RECIPIENT_ADDRESS_FROZEN;

        if (!token.isAmlKycPassed(from)) return SENDER_NOT_AMLKYCPASSED;
        // recipient is aml kyc passed is checked on holdingtransfer rule level

        if (token.balanceOf(from) < value)
            return INSUFFICIENT_BALANCE_OF_SENDER;
        if (token.unlockedTotalBalanceOf(from) < value)
            return SENDER_TOKENS_TIME_LOCKED;

        return SUCCESS;
    }

    /// @inheritdoc ITransferRules
    function detectTransferRestriction(
        address tokenAddr,
        address from,
        address to,
        uint256 value
    ) external view override returns (uint256) {
        uint256 restrictionCode = detectTransferRestrictionBasic(tokenAddr, from, to, value);
        if (restrictionCode != SUCCESS) return restrictionCode;

        IRestrictedLockupToken token = IRestrictedLockupToken(tokenAddr);
        IIdentityRegistry identityRegistry = token.identityRegistry();
        uint256 transferableAmount = _calculateTransferableFromTimelocks(
            token,
            from,
            to,
            identityRegistry,
            value
        );
        if (transferableAmount >= value) return SUCCESS;

        uint256 amountToTransferFromHoldings = value - transferableAmount;
        uint256 transferableAmountFromHoldings = _calculateTransferableFromHoldings(
            token,
            from,
            to,
            identityRegistry,
            amountToTransferFromHoldings
        );

        if (transferableAmountFromHoldings < amountToTransferFromHoldings) return HOLDING_PERIOD_NOT_MET;

        return SUCCESS;
    }


    /**
     * @dev Calculates the transferable amount from token holdings considering holding periods
     * @param token The token contract
     * @param from The sender address
     * @param to The recipient address
     * @param identityRegistry The identity registry for checking holding periods
     * @param expectedTransferableAmount The expected amount needed (0 = calculate all available)
     * @return transferableAmount The amount that can be transferred from holdings
     */
    // TODO: Optimize this function with bitmask indexing
    function _calculateTransferableFromHoldings(
        IRestrictedLockupToken token,
        address from,
        address to,
        IIdentityRegistry identityRegistry,
        uint256 expectedTransferableAmount
    ) internal view returns (uint256 transferableAmount) {
        // Check holdings for transferable tokens without loading entire array into memory
        IIdentityRegistry.IdentityInfo memory recipientIdentity = identityRegistry.identity(to);
        bool isAmlKycPassed = token.isAmlKycPassed(to);

        for (uint256 j = 0; j < token.holdingCountOf(from); j++) {
            (uint256 amount, uint256 mintTimestamp, uint256 tokenType) = token.holdingOf(from, j);
            if (amount == 0) continue;

            // Check if this holding can be transferred based on holding period rules
            uint256 tokenTypeRestriction = detectTransferRestrictionForHolding(
                tokenType,
                mintTimestamp,
                recipientIdentity,
                isAmlKycPassed
            );
            if (tokenTypeRestriction != 0) {
                continue; // skip this holding
            }

            transferableAmount += amount;

            // Early termination if we have enough and expectedTransferableAmount > 0
            if (expectedTransferableAmount > 0 && transferableAmount >= expectedTransferableAmount) {
                break;
            }
        }
    }

    /**
     * @dev Calculates the transferable amount from timelocks
     * @param token The token contract
     * @param from The sender address
     * @param expectedTransferableAmount The expected amount needed (0 = calculate all available)
     * @return transferableAmount The amount that can be transferred from timelocks
     */
    function _calculateTransferableFromTimelocks(
        IRestrictedLockupToken token,
        address from,
        address to,
        IIdentityRegistry identityRegistry,
        uint256 expectedTransferableAmount
    ) internal view returns (uint256 transferableAmount) {
        // Check timelocks for unlocked tokens
        IIdentityRegistry.IdentityInfo memory recipientIdentity = identityRegistry.identity(to);
        bool isAmlKycPassed = token.isAmlKycPassed(to);
        for (uint256 i = 0; i < token.timelockCountOf(from); i++) {
            IRestrictedLockupToken.Timelock memory timelock = token.timelockOf(from, i);
            if (timelock.totalAmount == timelock.tokensTransferred) continue;

            // Get token type and mint timestamp from global holding index
            (uint256 tokenType, uint256 mintTimestamp) = token.getTokenTypeAndMintTimestampFromGlobalIndex(timelock.globalHoldingIndex);

            uint256 tokenTypeRestriction = detectTransferRestrictionForHolding(
                tokenType,
                mintTimestamp,
                recipientIdentity,
                isAmlKycPassed
            );
            if (tokenTypeRestriction != 0) {
                continue; // skip this timelock
            }
            transferableAmount += token.unlockedBalanceOfTimelock(from, i);

            // Early termination if we have enough and expectedTransferableAmount > 0
            if (expectedTransferableAmount > 0 && transferableAmount >= expectedTransferableAmount) {
                break;
            }
        }
    }

    /// @inheritdoc ITransferRules
    function messageForTransferRestriction(
        uint256 restrictionCode
    ) external view override returns (string memory) {
        if (restrictionCode > MAX_RESTRICTION_CODE) {
            revert TransferRules_BadRestrictionCode();
        }
        return errorMessage[restrictionCode];
    }

    /// @notice a method for checking a response code to determine if a transfer was succesful.
    /// Defining this separately from the token contract allows it to be upgraded.
    /// For instance this method would need to be upgraded if the SUCCESS code was changed to 1
    /// as specified in ERC-1066 instead of 0 as specified in ERC-1404.
    /// @param restrictionCode The code to check.
    /// @return isSuccess A boolean indicating if the code is the SUCCESS code.
    function checkSuccess(
        uint256 restrictionCode
    ) external pure override returns (bool isSuccess) {
        return restrictionCode == SUCCESS;
    }

    // ============================================
    // TOKEN TYPE RULES ENGINE FUNCTIONALITY
    // ============================================

    /// @inheritdoc ITransferRules
    function determineTokenType(
        address wallet,
        IIdentityRegistry identityRegistry
    ) external view override returns (uint256 tokenType) {
        // Get wallet identity
        IIdentityRegistry.IdentityInfo memory identity = identityRegistry.identity(wallet);

        // Check each region in the array to find the first matching rule
        for (uint256 i = 0; i < identity.regions.length; i++) {
            TokenTypeRule memory rule = _tokenTypeRules[identity.regions[i]][identity.accreditationType];

            if (rule.isActive) {
                if (rule.requiresAmlKyc && !identityRegistry.isAmlKycPassed(wallet)) {
                    continue;
                }

                return rule.tokenType;
            }
        }

        if (_defaultTokenTypeRule.isActive) {
            if (_defaultTokenTypeRule.requiresAmlKyc && !identityRegistry.isAmlKycPassed(wallet)) {
                revert TransferRules_RecipientNotAmlKycPassed();
            }

            return _defaultTokenTypeRule.tokenType;
        }

        revert TransferRules_TokenTypeRuleNotFound();
    }

    /// @inheritdoc ITransferRules
    function tokenTypeAllowed(
        uint256 tokenType,
        address wallet,
        IIdentityRegistry identityRegistry
    ) external view override returns (bool) {
        IIdentityRegistry.IdentityInfo memory identity = identityRegistry.identity(wallet);
        for (uint256 i = 0; i < identity.regions.length; i++) {
            TokenTypeRule memory rule = _tokenTypeRules[identity.regions[i]][identity.accreditationType];
            if (rule.isActive && rule.tokenType == tokenType) {
                if (!rule.requiresAmlKyc) {
                    return true;
                }
                if (identityRegistry.isAmlKycPassed(wallet)) {
                    return true;
                }
            }
        }

        if (_defaultTokenTypeRule.isActive && _defaultTokenTypeRule.tokenType == tokenType) {
            if (!_defaultTokenTypeRule.requiresAmlKyc) {
                return true;
            }

            return identityRegistry.isAmlKycPassed(wallet);
        }

        return false;
    }

    /// @inheritdoc ITransferRules
    function setTokenTypeRule(
        uint256 region,
        uint256 accreditation,
        uint256 tokenType,
        bool requiresAmlKyc,
        bool isActive
    ) public override onlyTransferAdmin {
        _tokenTypeRules[region][accreditation] = TokenTypeRule({
            tokenType: tokenType,
            requiresAmlKyc: requiresAmlKyc,
            isActive: isActive
        });

        emit TokenTypeRuleSet(
            region,
            accreditation,
            tokenType,
            requiresAmlKyc,
            isActive
        );
    }

    function setDefaultTokenTypeRule(
        uint256 tokenType,
        bool requiresAmlKyc,
        bool isActive
    ) public override onlyTransferAdmin {
        _defaultTokenTypeRule = TokenTypeRule({
            tokenType: tokenType,
            requiresAmlKyc: requiresAmlKyc,
            isActive: isActive
        });

        emit DefaultTokenTypeRuleSet(tokenType, requiresAmlKyc, isActive);
    }

    function resetDefaultTokenTypeRule() public override onlyTransferAdmin {
        _defaultTokenTypeRule = TokenTypeRule({
            tokenType: TOKEN_TYPE_GENERIC,
            requiresAmlKyc: false,
            isActive: false
        });

        emit DefaultTokenTypeRuleSet(TOKEN_TYPE_GENERIC, false, false);
    }

    function defaultTokenTypeRule() public view override returns (TokenTypeRule memory) {
        return _defaultTokenTypeRule;
    }

    /// @inheritdoc ITransferRules
    function removeTokenTypeRule(
        uint256 region,
        uint256 accreditation
    ) public override onlyTransferAdmin {
        delete _tokenTypeRules[region][accreditation];

        emit TokenTypeRuleRemoved(region, accreditation);
    }

    /// @inheritdoc ITransferRules
    function getTokenTypeRule(
        uint256 region,
        uint256 accreditation
    ) external view override returns (TokenTypeRule memory) {
        return _tokenTypeRules[region][accreditation];
    }

    /// @inheritdoc ITransferRules
    function batchSetTokenTypeRules(
        uint256[] calldata regions,
        uint256[] calldata accreditations,
        uint256[] calldata tokenTypes,
        bool[] calldata requiresAmlKycFlags,
        bool[] calldata isActiveFlags
    ) external override onlyTransferAdmin {
        if (
            regions.length != accreditations.length ||
            regions.length != tokenTypes.length ||
            regions.length != requiresAmlKycFlags.length ||
            regions.length != isActiveFlags.length
        ) {
            revert TransferRules_InvalidArrayLengths();
        }

        for (uint256 i = 0; i < regions.length; i++) {
            setTokenTypeRule(regions[i], accreditations[i], tokenTypes[i], requiresAmlKycFlags[i], isActiveFlags[i]);
        }
    }

    // ============================================
    // TOKEN TYPE TRANSFER RULES FUNCTIONALITY
    // ============================================

    /// @inheritdoc ITransferRules
    function detectTransferRestrictionForHolding(
        uint256 tokenType,
        uint256 mintTimestamp,
        IIdentityRegistry.IdentityInfo memory recipientIdentity,
        bool isAmlKycPassed
    ) public view override returns (uint256 restrictionCode) {
        restrictionCode = NO_RULE_FOR_RECIPIENT;

        // Check each region in the recipient's regions array
        for (uint256 i = 0; i < recipientIdentity.regions.length; i++) {
            // Single SLOAD - get packed rule (major gas optimization)
            uint256 packedRule = _packedRules[tokenType][recipientIdentity.regions[i]][recipientIdentity.accreditationType];

            // Quick check: is rule active? (single bitwise operation)
            if ((packedRule & IS_ACTIVE_MASK) == 0) continue;

            // Check AML/KYC requirement (single bitwise operation)
            if ((packedRule & REQUIRES_AML_KYC_MASK) != 0 && !isAmlKycPassed) {
                restrictionCode = RECIPIENT_NOT_AMLKYCPASSED;
                continue; // This region requires AML/KYC but recipient doesn't have it, try next region
            }

            // Check holding period (single shift operation)
            uint256 lockDuration = (packedRule >> LOCK_DURATION_SHIFT);
            if (lockDuration != 0 && mintTimestamp + lockDuration > block.timestamp) {
                restrictionCode = HOLDING_PERIOD_NOT_MET;
                continue; // This region's holding period not met, try next region
            }
            // If we reach here, this region allows the transfer
            return SUCCESS;
        }

        return restrictionCode;
    }

    /// @inheritdoc ITransferRules
    function setTransferRule(
        uint256 tokenType,
        uint256 recipientRegion,
        uint256 recipientAccreditation,
        TransferRule memory _rule
    ) public override onlyTransferAdmin {
        // Pack the rule into single uint256 for gas-efficient storage
        uint256 packed = _packRule(
            _rule.lockDurationSeconds,
            _rule.requiresAmlKyc,
            _rule.isActive
        );

        // Single SSTORE operation (major gas optimization)
        _packedRules[tokenType][recipientRegion][recipientAccreditation] = packed;

        emit TransferRuleSet(
            tokenType,
            recipientRegion,
            recipientAccreditation,
            _rule.lockDurationSeconds,
            _rule.requiresAmlKyc,
            _rule.isActive
        );
    }

    /// @inheritdoc ITransferRules
    function removeTransferRule(
        uint256 tokenType, 
        uint256 recipientRegion, 
        uint256 recipientAccreditation
    ) external override onlyTransferAdmin {
        delete _packedRules[tokenType][recipientRegion][recipientAccreditation];

        emit TransferRuleRemoved(tokenType, recipientRegion, recipientAccreditation);
    }

    /// @inheritdoc ITransferRules
    function getUnlockTimestamp(
        uint256 tokenType,
        uint256 mintTimestamp,
        address recipient,
        IIdentityRegistry identityRegistry
    ) external view override returns (uint256 unlockTimestamp) {
        IIdentityRegistry.IdentityInfo memory recipientIdentity = identityRegistry.identity(recipient);

        // Check each region in the recipient's regions array and return the earliest unlock timestamp
        uint256 earliestUnlockTimestamp = type(uint256).max;
        bool foundRule = false;

        for (uint256 i = 0; i < recipientIdentity.regions.length; i++) {
            // Direct packed storage access for better gas efficiency
            uint256 packedRule = _packedRules[tokenType][recipientIdentity.regions[i]][recipientIdentity.accreditationType];

            // Quick check: is rule active? (single bitwise operation)
            if ((packedRule & IS_ACTIVE_MASK) != 0) {
                foundRule = true;
                uint256 regionUnlockTimestamp = mintTimestamp + (packedRule >> LOCK_DURATION_SHIFT);

                if (regionUnlockTimestamp < earliestUnlockTimestamp) {
                    earliestUnlockTimestamp = regionUnlockTimestamp;
                }
            }
        }

        if (!foundRule) {
            return 0; // No rule means no restriction
        }

        return earliestUnlockTimestamp;
    }

    /// @inheritdoc ITransferRules
    function batchSetTransferRules(
        uint256[] calldata tokenType,
        uint256[] calldata recipientRegion,
        uint256[] calldata recipientAccreditation,
        TransferRule[] calldata rules
    ) external override onlyTransferAdmin {
        if (
            tokenType.length != recipientRegion.length ||
            tokenType.length != recipientAccreditation.length ||
            tokenType.length != rules.length
        ) {
            revert TransferRules_InvalidArrayLengths();
        }

        for (uint256 i = 0; i < rules.length; i++) {
            setTransferRule(tokenType[i], recipientRegion[i], recipientAccreditation[i], rules[i]);
        }
    }

    /// @inheritdoc ITransferRules
    function transferRuleFor(
        uint256 tokenType,
        uint256 recipientRegion,
        uint256 recipientAccreditation
    ) public view override returns (TransferRule memory rule) {
        uint256 packed = _packedRules[tokenType][recipientRegion][recipientAccreditation];
        (rule.lockDurationSeconds, rule.requiresAmlKyc, rule.isActive) = _unpackRule(packed);
    }

    function _msgSender()
        internal
        view
        override(ERC2771Context)
        returns (address sender)
    {
        return ERC2771Context._msgSender();
    }

    function _msgData()
        internal
        view
        override(ERC2771Context)
        returns (bytes calldata)
    {
        return ERC2771Context._msgData();
    }

    function _contextSuffixLength()
        internal
        view
        override(ERC2771Context)
        returns (uint256)
    {
        return ERC2771Context._contextSuffixLength();
    }
}

contracts/interfaces/IAccessControl.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity 0.8.28;

interface IAccessControl {
    // ============================================
    // EVENTS
    // ============================================

    /// @notice This event is emitted when a new role is granted or revoked to a user
    /// @param grantor The address of admin who granted the role
    /// @param grantee The address of user who received the role
    /// @param role The role that was granted as a bitmask
    /// @param status The status of the role (true = granted, false = revoked)
    event RoleChange(
        address indexed grantor,
        address indexed grantee,
        uint8 role,
        bool indexed status
    );

    // Note: Errors are defined in AccessControlErrors.sol to avoid duplicate declarations

    // ============================================
    // VIEW FUNCTIONS
    // ============================================

    // View role checks
    function hasRole(address addr, uint8 role) external view returns (bool);
    function roles(address addr) external view returns (uint8);
    function contractAdminCount() external view returns (uint8);

    // Role constants
    function CONTRACT_ADMIN_ROLE() external view returns (uint8);
    function TRANSFER_ADMIN_ROLE() external view returns (uint8);
    function RESERVE_ADMIN_ROLE() external view returns (uint8);
    function WALLETS_ADMIN_ROLE() external view returns (uint8);
    function SOFT_BURN_ADMIN_ROLE() external view returns (uint8);
    function MINT_ADMIN_ROLE() external view returns (uint8);

    // ============================================
    // STATE-CHANGING FUNCTIONS
    // ============================================

    // Role management
    function grantRole(address addr, uint8 role) external;
    function batchGrantRoles(address[] calldata addresses, uint8[] calldata roles_) external;
    function revokeRole(address addr, uint8 role) external;
    function batchRevokeRoles(address[] calldata addresses, uint8[] calldata roles_) external;
}

contracts/interfaces/IDividends.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.8.28;

interface IDividends {
    /**
     * @title Functions
     */

    /// @dev Get unused ERC-20 tokens on timestamp
    /// @param token ERC-20 token address
    /// @param timestamp Timestamp for historical data
    /// @return amount of ERC-20 tokens
    function tokensAt(
        address token,
        uint256 timestamp
    ) external view returns (uint256);

    /**
     * @dev Fund any ERC-20 tokens into current contract
     * Tokens can be claimed by holders of RestrictedLockup Token uses claimDividends method
     * @param token ERC-20 token address
     * @param amount amount of tokens to fund
     * @param timestamp timestamp for dividend distribution
     */
    function fundDividend(
        address token,
        uint256 amount,
        uint256 timestamp
    ) external;

    /**
     * @dev Reclaim ERC-20 tokens from a specific dividend snapshot
     * Can only be done if no dividends have been claimed for this snapshot (unusedFunds == totalFunds)
     * If amount is 0, reclaims all available funds
     * @param token ERC-20 token address
     * @param amount amount of tokens to reclaim (0 = reclaim all)
     * @param timestamp timestamp for dividend distribution
     */
    function reclaimTotalDividend(
        address token,
        uint256 amount,
        uint256 timestamp
    ) external;

    /**
     * @dev Reclaim dividends for a specific target address and send to contract reclaimer
     * Can only be called by transfer admin
     * @param token ERC-20 token address
     * @param targetAddress Address to reclaim dividends for
     * @param timestamp timestamp for dividend distribution
     * @param amount amount of tokens to reclaim (0 = reclaim all)
     */
    function reclaimDividend(
        address token,
        address targetAddress,
        uint256 timestamp,
        uint256 amount
    ) external;

    /**
     * @dev Get balance of ERC-20 tokens funded at timestamp
     * @param token ERC-20 token address
     * @param timestamp timestamp for historical data
     * @return amount of ERC-20 tokens
     */
    function fundsAt(
        address token,
        uint256 timestamp
    ) external view returns (uint256);

    /**
     * @dev Amount of ERC-20 tokens distributed to the holder of RestrictedLockup Token at timestamp
     * @param token ERC-20 token address
     * @param receiver RestrictedLockup Token's holder address
     * @param timestamp timestamp for historical data
     * @return amount of total ERC-20 tokens distributed to the receiver
     */
    function totalAwardedBalanceAt(
        address token,
        address receiver,
        uint256 timestamp
    ) external view returns (uint256);

    /**
     * @dev Amount of ERC-20 tokens claimed by the holder of RestrictedLockup Token at timestamp
     * @param token ERC-20 token address
     * @param receiver RestrictedLockup Token's holder address
     * @param timestamp timestamp for historical data
     * @return amount of claimed ERC-20 tokens
     */
    function claimedBalanceAt(
        address token,
        address receiver,
        uint256 timestamp
    ) external view returns (uint256);

    /**
     * @dev Amount of ERC-20 tokens that can be claimed by the holder of RestrictedLockup Token at timestamp
     * @param token ERC-20 token address
     * @param receiver RestrictedLockup Token's holder address
     * @param timestamp timestamp for historical data
     * @return amount of can be claimed ERC-20 tokens
     */
    function unclaimedBalanceAt(
        address token,
        address receiver,
        uint256 timestamp
    ) external view returns (uint256);

    /**
     * @dev Claim ERC-20 tokens (dividends) by RestrictedLockup Tokens holder
     * Tokens can be claimed when its allowed by unclaimedBalanceAt
     * @param token ERC-20 token address
     * @param timestamp timestamp for dividend claim
     * @param amount amount of tokens to reclaim (0 = reclaim all)
     */
    function claimDividend(address token, uint256 timestamp, uint256 amount) external;

    /**
     * @dev Claim ERC-20 tokens (dividends) by RestrictedLockup Tokens holder, across multiple timestamps
     * Tokens can be claimed when its allowed by unclaimedBalanceAt
     * @param token ERC-20 token address
     * @param timestamps timestamps for dividend claims
     * @param amounts amounts of tokens to reclaim (0 = reclaim all)
     */
    function batchClaimDividend(
        address token,
        uint256[] calldata timestamps,
        uint256[] calldata amounts
    ) external;

    /**
     * @title Events
     */

    /// @notice This event is emitted when a timestamp is funded with ERC-20 tokens
    /// @param payer address of the payer
    /// @param token ERC-20 token address
    /// @param amount amount of ERC-20 tokens
    /// @param timestamp timestamp for dividend distribution
    event DividendFunded(
        address indexed payer,
        address indexed token,
        uint256 amount,
        uint256 indexed timestamp
    );

    /// @notice This event is emitted when a holder of RestrictedLockup Token claims ERC-20 tokens
    /// @param payee address of the receiver
    /// @param token ERC-20 token address
    /// @param amount amount of ERC-20 tokens
    /// @param timestamp timestamp for dividend claim
    event DividendClaimed(
        address indexed payee,
        address indexed token,
        uint256 amount,
        uint256 indexed timestamp
    );

    /// @notice This event is emitted when all ERC-20 tokens are reclaimed from a dividend snapshot
    /// @param payee address of the payee
    /// @param target address of the target
    /// @param token ERC-20 token address
    /// @param amount amount of ERC-20 tokens reclaimed
    /// @param timestamp timestamp for dividend distribution
    event DividendReclaimed(
        address indexed payee,
        address indexed target,
        address indexed token,
        uint256 amount,
        uint256 timestamp
    );
}

