contracts/interfaces/IIdentityRegistry.s.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.8.28;
import "@openzeppelin/contracts/utils/introspection/IERC165.sol";

interface IIdentityRegistry {
    struct IdentityInfo {
        uint256[] regions;
        uint256 accreditationType;
        uint256 lastAmlKycChangeTimestamp;
        uint256 lastAccreditationChangeTimestamp;
        bool amlKycPassed;
    }

    /**
     * @dev Sets the validity duration for AML/KYC status in seconds.
     * @param amlKycValidityDuration The duration in seconds for which AML/KYC status remains valid
     */
    function setAmlKycValidityDuration(uint256 amlKycValidityDuration) external;

    /**
     * @dev Sets or updates the complete identity information for a wallet address.
     * @param owner The wallet address to set identity for
     * @param info The complete identity information structure
     */
    function setIdentity(address owner, IdentityInfo memory info) external;

    /**
     * @dev Sets or updates the complete identity information for a wallet address.
     * @param owners The wallet addresses to set identity for
     * @param info The complete identity information structure
     */
    function batchSetIdentity(address[] memory owners, IdentityInfo memory info) external;

    /**
     * @dev Removes all identity information for a wallet address.
     * @param owner The wallet address to remove identity from
     */
    function removeIdentity(address owner) external;

    /**
     * @dev Retrieves the complete identity information for a wallet address.
     * @param owner The wallet address to query
     * @return The complete identity information structure
     */
    function identity(
        address owner
    ) external view returns (IdentityInfo memory);

    /**
     * @dev Sets the regions for a wallet address.
     * @param owner The wallet address to set regions for
     * @param regions The array of region identifiers
     */
    function setRegions(address owner, uint256[] memory regions) external;

    /**
     * @dev Adds a region to a wallet address.
     * @param owner The wallet address to add region to
     * @param region The region identifier to add
     */
    function addRegion(address owner, uint256 region) external;

    /**
     * @dev Removes a region from a wallet address.
     * @param owner The wallet address to remove region from
     * @param region The region identifier to remove
     */
    function removeRegion(address owner, uint256 region) external;

    /**
     * @dev Grants AML/KYC approval for a wallet address.
     * @param owner The wallet address to grant AML/KYC for
     * @param amlKycTimestamp The timestamp when AML/KYC was granted (0 for current timestamp)
     */
    function grantAmlKyc(address owner, uint256 amlKycTimestamp) external;

    /**
     * @dev Revokes AML/KYC approval for a wallet address.
     * @param owner The wallet address to revoke AML/KYC from
     * @param amlKycTimestamp The timestamp when AML/KYC was revoked (0 for current timestamp)
     */
    function revokeAmlKyc(address owner, uint256 amlKycTimestamp) external;

    /**
     * @dev Grants accreditation level for a wallet address.
     * @param owner The wallet address to grant accreditation for
     * @param accreditationType The type/level of accreditation to grant
     * @param accreditationTimestamp The timestamp when accreditation was granted (0 for current timestamp)
     */
    function grantAccreditation(address owner, uint256 accreditationType, uint256 accreditationTimestamp) external;

    /**
     * @dev Revokes accreditation for a wallet address.
     * @param owner The wallet address to revoke accreditation from
     * @param accreditationTimestamp The timestamp when accreditation was revoked (0 for current timestamp)
     */
    function revokeAccreditation(address owner, uint256 accreditationTimestamp) external;

    /**
     * @dev Retrieves the regions for a wallet address.
     * @param owner The wallet address to query
     * @return The array of region identifiers
     */
    function regions(address owner) external view returns (uint256[] memory);

    /**
     * @dev Checks if a wallet address has a specific region.
     * @param owner The wallet address to check
     * @param region The region identifier to check
     * @return True if the wallet has the region, false otherwise
     */
    function hasRegion(address owner, uint256 region) external view returns (bool);

    /**
     * @dev Retrieves the accreditation type for a wallet address.
     * @param owner The wallet address to query
     * @return The accreditation type/level
     */
    function accreditationType(address owner) external view returns (uint256);

    /**
     * @dev Checks if a wallet address has valid AML/KYC approval.
     * @param owner The wallet address to check
     * @return True if AML/KYC is passed and still valid, false otherwise
     */
    function isAmlKycPassed(address owner) external view returns (bool);

    /**
     * @dev Retrieves the current AML/KYC validity duration in seconds.
     * @return The validity duration in seconds
     */
    function amlKycValidityDuration() external view returns (uint256);

    // Events
    event IdentityCreated(address indexed authority, address indexed owner);
    event IdentityRemoved(address indexed authority, address indexed owner);
    event RegionsSet(address indexed authority, address indexed owner, uint256[] regions);
    event RegionAdded(address indexed authority, address indexed owner, uint256 region);
    event RegionRemoved(address indexed authority, address indexed owner, uint256 region);
    event AmlKycPassed(address indexed authority, address indexed owner, uint256 amlKycTimestamp);
    event AmlKycFailed(address indexed authority, address indexed owner, uint256 amlKycTimestamp);
    event AccreditationGranted(address indexed authority, address indexed owner, uint256 newAccreditationLevel, uint256 accreditationTimestamp);
    event AccreditationRevoked(address indexed authority, address indexed owner, uint256 revokedAccreditationLevel, uint256 accreditationTimestamp);
    event AmlKycValidityDurationSet(address indexed authority, uint256 oldAmlKycValidityDuration, uint256 newAmlKycValidityDuration);
}

contracts/interfaces/IInterestPayment.so.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.8.28;

/**
 * @title IInterestPayment
 * @notice Interface for managing interest payments for loans backed by RestrictedLockupToken
 * @dev Defines functions for tracking interest accrual based on token holdings and claiming interest payments
 */
interface IInterestPayment {
    /// @notice This event is emitted when a payment interest period is funded with ERC-20 tokens
    /// @param payer address of the payer who funded the interest
    /// @param amount amount of ERC-20 tokens funded
    event Funded(address indexed payer, uint256 amount);

    /// @notice This event is emitted when a payment period is created
    /// @param creator address of the creator who created the payment period
    /// @param paymentPeriodIdx payment period index
    /// @param startTimestamp start timestamp
    /// @param endTimestamp end timestamp
    /// @param interestRate interest rate
    event PaymentPeriodCreated(
        address indexed creator,
        uint256 indexed paymentPeriodIdx,
        uint256 startTimestamp,
        uint256 endTimestamp,
        uint256 interestRate
    );

    /// @notice This event is emitted when a interest rate is updated
    /// @param creator address of the creator who updated the interest rate
    /// @param paymentPeriodIdx payment period index
    /// @param interestRate interest rate
    event InterestRateUpdated(
        address indexed creator,
        uint256 indexed paymentPeriodIdx,
        uint256 interestRate
    );

    /// @notice This event is emitted when a holder of RestrictedLockup Token claims interests
    /// @param payee address of the receiver who claimed the interest
    /// @param amount amount of ERC-20 tokens claimed
    /// @param periodIdx period index for which interest was claimed
    event Claimed(
        address indexed payee,
        uint256 amount,
        uint256 indexed periodIdx
    );

    /// @notice This event is emitted when interest is reclaimed from a specific wallet
    /// @param payee address that reclaimed the interest
    /// @param target address from which interest was reclaimed
    /// @param amount amount of ERC-20 tokens reclaimed
    /// @param periodIdx period index for which interest was reclaimed
    event Reclaimed(
        address indexed payee,
        address indexed target,
        uint256 amount,
        uint256 periodIdx
    );

    /// @notice This event is emitted when all unclaimed interest for a period is reclaimed
    /// @param payee address that reclaimed the interest
    /// @param amount total amount of ERC-20 tokens reclaimed
    /// @param periodIdx period index for which all interest was reclaimed
    event ReclaimedAll(
        address indexed payee,
        uint256 amount,
        uint256 indexed periodIdx
    );

    /// @notice This event is emitted when principal amount is reclaimed
    /// @param payee address that reclaimed the principal
    /// @param amount amount of ERC-20 tokens reclaimed as principal
    event PrincipalReclaimed(address indexed payee, uint256 amount);

    /// @notice This event is emitted when principal amount is funded
    /// @param payer address of the payer who funded the principal
    /// @param amount amount of ERC-20 tokens funded as principal
    event PrincipalFunded(address indexed payer, uint256 amount);

    /// @notice This event is emitted when principal amount is claimed
    /// @param payee address of the receiver who claimed the principal
    /// @param amount amount of ERC-20 tokens claimed as principal
    event PrincipalClaimed(address indexed payee, uint256 amount);

    /// @notice This event is emitted when the reclaimer address is changed
    /// @param admin address of the admin who changed the reclaimer
    /// @param newReclaimer address of the new reclaimer
    event ReclaimerAddressChanged(
        address indexed admin,
        address indexed newReclaimer
    );

    /// @notice This event is emitted when the interest accrual end timestamp is changed
    /// @param admin address of the admin who changed the interest accrual end timestamp
    /// @param newInterestAccrualEndTimestamp new timestamp for the interest accrual end timestamp
    event InterestAccrualEndShifted(
        address indexed admin,
        uint256 newInterestAccrualEndTimestamp
    );

    /// @notice This event is emitted when a payment period is paused
    /// @param admin address of the admin who paused the period
    /// @param periodIdx period index that was paused
    event PeriodPaused(address indexed admin, uint256 indexed periodIdx);

    /// @notice This event is emitted when a payment period is unpaused
    /// @param admin address of the admin who unpaused the period
    /// @param periodIdx period index that was unpaused
    event PeriodUnpaused(address indexed admin, uint256 indexed periodIdx);

    /// @notice This event is emitted when a payment period is paused after a specific timestamp
    /// @param timestamp The timestamp after which payments are paused
    event PaymentPausedAfter(uint256 timestamp);

    /// @notice This event is emitted when a payments is unpaused
    event PaymentUnpausedAfter();

    /// @notice This event is emitted when a payments is paused after a specific timestamp
    /// @param admin address of the admin who paused the payments
    /// @param timestamp The timestamp after which payments are paused
    event EarlyRepayment(address indexed admin, uint256 timestamp);

    /// @notice This event is emitted when an admin force claims interest for a wallet
    /// @param admin address of the admin who force claimed
    /// @param wallet address of the wallet for which interest was claimed
    /// @param amount amount of ERC-20 tokens claimed
    /// @param periodIdx period index for which interest was claimed
    event ForceClaimed(
        address indexed admin,
        address indexed wallet,
        uint256 amount,
        uint256 indexed periodIdx
    );

    /// @notice This event is emitted when the max interest rate is set
    /// @param admin address of the admin who set the max interest rate
    /// @param maxInterestRate the new max interest rate
    event SetMaxInterestRate(address indexed admin, uint256 maxInterestRate);

    /// @notice Checks if a specific payment period is paused
    /// @param periodIdx The period index to check
    /// @return A boolean indicating if the period is paused (true) or active (false)
    function paymentPeriodPaused(
        uint256 periodIdx
    ) external view returns (bool);

    /// @notice Pauses payments for a specific period
    /// @param periodIdx The period index to pause
    function pausePaymentPeriod(uint256 periodIdx) external;

    /// @notice Unpauses payments for a specific period
    /// @param periodIdx The period index to unpause
    function unpausePaymentPeriod(uint256 periodIdx) external;

    /// @notice Pauses or unpauses the entire contract
    /// @param isPaused_ Whether to pause (true) or unpause (false) the contract
    function pause(bool isPaused_) external;

    /// @notice Pauses payment after a specific timestamp
    /// @param timestamp The timestamp after which payments will be paused
    function pausePaymentAfter(uint256 timestamp) external;

    /// @notice Unpauses payment after being paused with pausePaymentAfter
    function unpausePaymentAfter() external;

    /// @notice Sets the address that can reclaim unclaimed interest
    /// @param reclaimerAddress_ The new reclaimer address
    function setReclaimerAddress(address reclaimerAddress_) external;

    /// @notice Shifts the interest accrual end timestamp
    /// @param newInterestAccrualEndTimestamp The new interest accrual end timestamp
    function shiftInterestAccrualEnd(
        uint256 newInterestAccrualEndTimestamp
    ) external;

    /// @notice Calculates accrued interest for an account at the current time
    /// @param account The account address to check interest for
    /// @return The amount of accrued interest in the specified token
    function accruedInterest(address account) external view returns (uint256);

    /// @notice Calculates accrued interest for an account at a specific timestamp
    /// @param account The account address to check interest for
    /// @param timestamp The timestamp at which to calculate the accrued interest
    /// @return The amount of accrued interest at the given timestamp
    function accruedInterestAt(
        address account,
        uint256 timestamp
    ) external view returns (uint256);

    /// @notice Shows total funded interest
    /// @return The total funded interest
    function totalInterestAmountFunded() external view returns (uint256);

    /// @notice Shows total claimed interest
    /// @return The total claimed interest
    function totalInterestAmountClaimed() external view returns (uint256);

    /// @notice Shows total reclaimed interest
    /// @return The total reclaimed interest
    function totalInterestAmountReclaimed() external view returns (uint256);

    /// @notice Shows total unused interest
    /// @return The total unused interest
    function totalInterestAmountUnused() external view returns (uint256);

    /// @notice Gets the nearest interest payment timestamp at a given timestamp
    /// @param timestamp The reference timestamp
    /// @return The nearest interest payment timestamp (rounded to period boundaries)
    function nearestInterestPaymentTimestampAt(
        uint256 timestamp
    ) external view returns (uint256);

    /// @notice Finds the index of a funded payment period that covers the specified time range
    /// @param startTimestamp The start timestamp of the period to find
    /// @param endTimestamp The end timestamp of the period to find
    /// @return The period index or max uint256 if no matching period is found
    function findPaymentPeriodIndex(
        uint256 startTimestamp,
        uint256 endTimestamp
    ) external view returns (uint256);

    /// @notice Creates a payment period
    /// @param startTimestamp The start timestamp of the period
    /// @param endTimestamp The end timestamp of the period
    /// @param interestRate The interest rate for the period
    /// @param interestRatePeriodDuration The duration of the interest rate period
    function createPaymentPeriod(
        uint256 startTimestamp,
        uint256 endTimestamp,
        uint256 interestRate,
        uint256 interestRatePeriodDuration
    ) external;

    /// @notice Funds interest
    /// @param amount The amount of tokens to fund
    function fundInterest(uint256 amount) external;

    /// @notice Claims interest for a specific period
    /// @param paymentPeriodIdx The payment period index to claim interest for
    /// @param amount The amount to claim, capped at available claimable amount
    function claimInterestForPeriod(
        uint256 paymentPeriodIdx,
        uint256 amount
    ) external;

    /// @notice Claims interest for multiple periods
    /// @param paymentPeriodIdxs The payment period indexes to claim interest for
    /// @param amount The amount to claim, capped at available claimable amount
    function batchClaimInterestForPeriods(
        uint256[] memory paymentPeriodIdxs,
        uint256 amount
    ) external;

    /// @notice Claims interest for all available periods
    /// @param amount The amount to claim, capped at available claimable amount
    function claimInterest(uint256 amount) external;

    /// @notice Force claim interest for an account for a specific period
    /// @param wallet The wallet address to claim interest for
    /// @param paymentPeriodIdx The payment period index to claim interest for
    /// @param amount The amount to claim, capped at available claimable amount
    function forceClaimForPeriod(
        address wallet,
        uint256 paymentPeriodIdx,
        uint256 amount
    ) external;

    /// @notice Batch force claim interest for specific periods for a wallet
    /// @param wallet The wallet address to claim interest for
    /// @param paymentPeriodIdxs Array of payment period indices to claim interest from
    /// @param amount The maximum amount to claim, or 0 for all available funds
    function batchForceClaimInterest(
        address wallet,
        uint256[] memory paymentPeriodIdxs,
        uint256 amount
    ) external;

    /// @notice Gets the total number of payment periods
    /// @return The number of payment periods
    function paymentPeriodsCount() external view returns (uint256);

    /// @notice Gets the available interest for a specific period
    /// @param periodIdx The period index to check
    /// @return The available interest for the specified period
    function periodAvailableInterest(
        uint256 periodIdx
    ) external view returns (uint256);

    /// @notice Gets the duration of a specific period in seconds
    /// @param periodIdx The period index to check
    /// @return The period duration in seconds
    function periodDuration(uint256 periodIdx) external view returns (uint256);

    /// @notice Calculates unclaimed amount for a receiver at a specific period
    /// @param receiver_ The receiver address to check
    /// @param paymentPeriodIdx_ The payment period index to check
    /// @return The unclaimed amount for the specified parameters
    function unclaimedAmountForPeriod(
        address receiver_,
        uint256 paymentPeriodIdx_
    ) external view returns (uint256);

    /// @notice Gets claimed amount for a receiver at a specific period
    /// @param receiver_ The receiver address to check
    /// @param paymentPeriodIdx_ The payment period index to check
    /// @return The claimed amount for the specified parameters
    function claimedAmountForPeriod(
        address receiver_,
        uint256 paymentPeriodIdx_
    ) external view returns (uint256);

    /// @notice Reclaims interest for a specific period from a specific wallet
    /// @param wallet The wallet address from which to reclaim interest
    /// @param paymentPeriodIdx_ The payment period index to reclaim interest from
    /// @param amount The amount to reclaim, capped at available reclaimable amount
    function reclaimInterestForPeriod(
        address wallet,
        uint256 paymentPeriodIdx_,
        uint256 amount
    ) external;

    /// @notice Reclaims interest for all recipients for a specific period
    /// @param paymentPeriodIdx_ The payment period index to reclaim all interest from
    function reclaimInterestForAllRecipients(
        uint256 paymentPeriodIdx_
    ) external;

    /// @notice Reclaims interest for a specific period from a specific wallet
    /// @param wallet The wallet address from which to reclaim interest
    /// @param amount The amount to reclaim, capped at available reclaimable amount
    function reclaimInterest(address wallet, uint256 amount) external;

    /// @notice Reclaims interest for multiple periods from a specific wallet
    /// @param wallet The wallet address from which to reclaim interest
    /// @param paymentPeriodIdxs The payment period indexes to reclaim interest from
    /// @param amount The amount to reclaim, capped at available reclaimable amount
    function batchReclaimInterest(
        address wallet,
        uint256[] memory paymentPeriodIdxs,
        uint256 amount
    ) external;

    /// @notice Reclaims total unused interest without regard to periods or wallets
    /// @param amount The amount to reclaim from total unused interest
    function reclaimTotalInterest(uint256 amount) external;

    /// @notice Funds principal amount in payment token
    /// @param amount The amount of tokens to fund as principal
    function fundPrincipal(uint256 amount) external;

    /// @notice Claims principal amount in payment token
    /// @param amount The amount to claim, or 0 for all available principal
    function claimPrincipal(uint256 amount) external;

    /// @notice Force claim principal for a specific wallet address
    /// @param wallet The wallet address to claim principal for
    /// @param amount The amount to claim, or 0 for all available principal
    function forceClaimPrincipal(address wallet, uint256 amount) external;

    /// @notice Reclaims principal amount in payment token
    /// @param amount The amount to reclaim, or 0 for all available principal
    function reclaimPrincipal(uint256 amount) external;

    /// @notice Gets the available principal amount for a specific account
    /// @param account The account address to check
    /// @return The available principal amount for the specified account
    function availablePrincipalAmount(
        address account
    ) external view returns (uint256);

    /// @notice Gets the total principal funded
    /// @return The total principal funded
    function fundedPrincipalAmount() external view returns (uint256);

    /// @notice Gets the total principal reclaimed
    /// @return The total principal reclaimed
    function reclaimedPrincipalAmount() external view returns (uint256);

    /// @notice Gets the total principal claimed
    /// @return The total principal claimed
    function claimedPrincipalAmount() external view returns (uint256);

    /// @notice Gets the total available principal
    /// @return The total available principal
    function totalAvailablePrincipalAmount() external view returns (uint256);

    /// @notice Gets the total accrued interest at the block timestamp
    /// @return The total accrued interest
    function totalAccruedInterest() external view returns (uint256);

    /// @notice Gets the total accrued interest at a specific timestamp
    /// @param timestamp The timestamp to get the accrued interest for
    /// @return The total accrued interest
    function totalAccruedInterestAt(
        uint256 timestamp
    ) external view returns (uint256);

    /// @notice Triggers early repayment by pausing payments and setting accrual end to a specific timestamp
    /// @param timestamp The timestamp to set the accrual end to
    function earlyRepayment(uint256 timestamp) external;

    /// @notice Sets the maximum interest rate
    /// @param maxInterestRate_ The new maximum interest rate in basis points
    function setMaxInterestRate(uint256 maxInterestRate_) external;

    /// @notice Updates the interest rate for a specific period
    /// @param periodIdx The period index to update
    /// @param interestRate_ The new interest rate in basis points
    /// @param interestRatePeriodDuration The duration of the interest rate period
    function updateInterestRateForPeriod(
        uint256 periodIdx,
        uint256 interestRate_,
        uint256 interestRatePeriodDuration
    ) external;

    /// @notice Gets the restricted lockup token contract
    /// @return The restricted lockup token contract
    function restrictedLockupToken() external view returns (address);

    /// @notice Gets the payment token contract
    /// @return The payment token contract
    function paymentToken() external view returns (address);

    /// @notice Gets the principal amount per token
    /// @return The principal amount per token
    function principalAmountPerToken() external view returns (uint256);
}

contracts/interfaces/IRestrictedLockupTo.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.8.28;

import "./IIdentityRegistry.sol";
import "./IAccessControl.sol";

// Interface for integration with Restricted Lockup Token
interface IRestrictedLockupToken {
    struct Timelock {
        address funder;
        uint256 scheduleId;
        uint256 commencementTimestamp;
        uint256 tokensTransferred;
        uint256 totalAmount;
        uint256 globalHoldingIndex; // Global index for token type + daysAfterDeployment combination
        address[] cancelableBy; // not cancelable unless set at the time of funding
    }
    struct FundReleaseScheduleParams {
        address to;
        uint256 amount;
        uint256 commencementTimestamp;
        uint256 scheduleId;
        uint256 holdingIdx;
    }
    // Holdings (wallet-scoped)
    function holdingOf(address who_, uint256 index_) external view returns (uint256, uint256, uint256);
    function holdingCountOf(address who_) external view returns (uint256);

    // Global holdings introspection (token-type scoped)
    function globalHoldingCount() external view returns (uint256);
    function getWalletIndexesLength(address who_) external view returns (uint256);
    function getWalletIndexes(address who_, uint256 index) external view returns (uint256);

    // Identity/registry
    function isAmlKycPassed(address who_) external view returns (bool);
    function identityRegistry() external view returns (IIdentityRegistry);
    function isValidIdentityRegistry(address identityRegistry) external view returns (bool);

    // Balances
    function balanceOf(address who_) external view returns (uint256);
    function unlockedTotalBalanceOf(address who_) external view returns (uint256);
    function unlockedBalanceOfTimelock(address who_, uint256 index_) external view returns (uint256);
    function isPaused() external view returns (bool);
    function getFrozenStatus(address who_) external view returns (bool);

    // Timelocks
    function timelockCountOf(address who_) external view returns (uint256);
    function timelockOf(address who_, uint256 index_) external view returns (Timelock memory);

    // Administrative token type updates
    function updateHoldingTokenType(address wallet, uint256 oldTokenType, uint256 newTokenType, uint256 mintTimestamp, uint256 amount) external;
    function updateTimelockTokenType(address wallet, uint256 timelockIndex, uint256 newTokenType) external;

    // Burn functions
    function burn(address from_, uint256 value_) external;
    function softBurn(address from_, uint256 value_) external;
    function burnHolding(address from_, uint256 globalHoldingIdx, uint256 amount) external;

    function snapshotPeriodsAddress() external view returns (address);

    function totalSupply() external view returns (uint256);
    function decimals() external view returns (uint8);

    // Mint functions
    function mint(address to, uint256 amount) external;
    function mintTokenType(address to, uint256 amount, uint256 tokenType) external;

    // Transfer functions
    function transfer(address to, uint256 amount) external;
    function batchTransfer(address[] calldata to, uint256[] calldata amounts) external;
    function transferFrom(address from, address to, uint256 amount) external;
    function forceTransferBetween(address from, address to, uint256 amount) external;
    function transferHolding(address from, address to, uint256 amount) external;

    // Max total supply
    function setMaxTotalSupply(uint256 maxTotalSupply) external;

    // Transfer rules
    function transferRules() external view returns (address);
    function isValidTransferRules(address transferRules) external view returns (bool);
    function accessControl() external view returns (IAccessControl);
    function restrictedLockupTokenExtension() external view returns (address);
    function restrictedLockupTokenManagementExtension() external view returns (address);

    // token type view functions
    function existingTokenTypesCount() external view returns (uint256);
    function existingTokenTypes(uint256 index) external view returns (uint256);
    function tokenTypeExists(uint256 tokenType) external view returns (bool);

    // Holder Management Functions
    function createHolderFromAddress(address addr_) external returns (uint256);
    function appendHolderAddress(address addr_, uint256 holderId_) external;
    function addHolderWithAddresses(address[] calldata addresses_) external returns (uint256);
    function removeHolder(uint256 holderId_) external;
    function removeWalletFromHolder(address addr_) external;
    function batchRemoveWalletFromHolder(address[] calldata addresses_) external;
    function getHolderAddresses(uint256 holderId_) external view returns (address[] memory);
    function getHolderId(address addr_) external view returns (uint256);
    function addressHasHolder(address addr_) external view returns (bool);
    function holderExists(uint256 holderId_) external view returns (bool);
    function setHolderMax(uint256 holderMax_) external;

    // Admin Functions
    function pause(bool isPaused_) external;
    function freeze(address addr_, bool status_) external;

    // Upgrade Functions
    function upgradeTransferRules(address newTransferRules) external;
    function upgradeIdentityRegistry(address newIdentityRegistry) external;

    // Release Schedule Functions
    function createReleaseSchedule(
        uint256 releaseCount,
        uint256 delayUntilFirstReleaseInSeconds,
        uint256 initialReleasePortionInBips,
        uint256 periodBetweenReleasesInSeconds
    ) external returns (uint256);

    function fundReleaseScheduleWithHolding(
        FundReleaseScheduleParams memory params,
        address[] memory cancelableBy_
    ) external returns (bool);

    function fundReleaseSchedule(
        address to_,
        uint256 amount_,
        uint256 commencementTimestamp_,
        uint256 scheduleId_,
        address[] memory cancelableBy_
    ) external returns (bool);

    function batchFundReleaseScheduleWithHolding(
        FundReleaseScheduleParams[] memory params,
        address[] memory cancelableBy_
    ) external returns (bool);

    function batchFundReleaseSchedule(
        address[] memory to_,
        uint256[] memory amounts_,
        uint256[] memory commencementTimestamps_,
        uint256[] memory scheduleIds_,
        address[] memory cancelableBy_
    ) external returns (bool);

    function mintReleaseScheduleTokenType(
        address to_,
        uint256 amount_,
        uint256 commencementTimestamp_,
        uint256 scheduleId_,
        uint256 tokenType_,
        address[] memory cancelableBy_
    ) external returns (bool);

    function mintReleaseSchedule(
        address to_,
        uint256 amount_,
        uint256 commencementTimestamp_,
        uint256 scheduleId_,
        address[] memory cancelableBy_
    ) external returns (bool);

    function batchMintReleaseScheduleTokenType(
        address[] calldata to,
        uint256[] calldata amounts,
        uint256[] calldata commencementTimestamps,
        uint256[] calldata scheduleIds,
        uint256[] calldata tokenTypes,
        address[] calldata cancelableBy
    ) external returns (bool);

    function batchMintReleaseSchedule(
        address[] calldata to,
        uint256[] calldata amounts,
        uint256[] calldata commencementTimestamps,
        uint256[] calldata scheduleIds,
        address[] calldata cancelableBy
    ) external returns (bool);

    // Additional Functions
    function safeApprove(address spender_, uint256 value_) external;

    // Supply Functions
    function maxTotalSupply() external view returns (uint256);
    function circulatingTokenSupply() external view returns (uint256);
    function unissuedTokenSupply() external view returns (uint256);

    // Token Type Functions
    function determineTokenType(address wallet) external view returns (uint256);
    function totalBalanceOf(address account) external view returns (uint256);

    // Transfer Restriction Functions
    function detectTransferRestriction(address from, address to, uint256 value) external view returns (uint8);
    function detectTransferRestrictionFor(uint256 tokenType, uint256 mintTimestamp, address to) external view returns (uint8);
    function messageForTransferRestriction(uint8 restrictionCode) external pure returns (string memory);

    // Timelock Functions
    function balanceOfTimelock(address who_, uint256 index_) external view returns (uint256);
    function cancelTimelock(address who_, uint256 timelockIndex_, uint256 scheduleId_, uint256 commencementTimestamp_, uint256 totalAmount_, address reclaimTokenTo_) external;
    function transferTimelock(address to, uint256 value, uint256 timelockId) external;

    // Schedule Functions
    function scheduleCount() external view returns (uint256);

    // Configuration Functions
    function setRecordMintTimestamp(bool enabled) external;

    /**
     * @dev Get token type and mint timestamp from global holding index
     * @param globalIndex The global holding index
     * @return tokenType The token type
     * @return mintTimestamp The mint timestamp
     */
    function getTokenTypeAndMintTimestampFromGlobalIndex(uint256 globalIndex) external view returns (uint256 tokenType, uint256 mintTimestamp);  
}

