pragma solidity 0.8.28;
import "@openzeppelin/contracts/utils/introspection/IERC165.sol";
interface ISnapshotPeriods {
    struct Period {
        uint256 start;
        uint256 end;
        uint256 totalAccruedOwnership;
        uint256 accruedOwnership;
    }

    struct WalletInfo {
        uint256 latestAccrualTimestamp;
        uint256 totalAccruedOwnership;
        uint256 periodCount;
    }

    function onUpdate(
        address token,
        address from,
        address to,
        uint256 amount
    ) external;

    function addressInfo(
        address token,
        address account
    ) external view returns (WalletInfo memory);

    function supplyInfo(
        address token
    ) external view returns (WalletInfo memory);

    function walletPeriodByIndex(
        address token,
        address account,
        uint256 index
    ) external view returns (Period memory);

    function totalSupplyPeriodByIndex(
        address token,
        uint256 index
    ) external view returns (Period memory);

    function findPeriodIndexForTimestamp(
        address token,
        address account,
        uint256 timestamp
    ) external view returns (uint256 periodIndex);

    function findTotalSupplyPeriodIndexForTimestamp(
        address token,
        uint256 timestamp
    ) external view returns (uint256 periodIndex);

    function calculateOwnershipForPeriod(
        uint256 amount,
        uint256 periodStart,
        uint256 periodEnd
    ) external view returns (uint256 ownership);

    function totalOwnershipForPeriod(
        address token,
        uint256 startTimestamp,
        uint256 endTimestamp
    ) external view returns (uint256);

    function ownershipForPeriod(
        address token,
        address account,
        uint256 startTimestamp,
        uint256 endTimestamp
    ) external view returns (uint256);

    function totalOwnershipAt(
        address token,
        uint256 timestamp
    ) external view returns (uint256);

    function ownershipAt(
        address token,
        address account,
        uint256 timestamp
    ) external view returns (uint256);

    function walletPeriodCount(
        address token,
        address account
    ) external view returns (uint256);

    function totalSupplyPeriodCount(
        address token
    ) external view returns (uint256);

    /**
     * @dev Returns the balanceOf that `account` had at a specific moment in the past
     * @param token The address of the token
     * @param account The address of the account
     * @param timestamp The timestamp of the past balance
     * @return The balance of `account` at `timestamp`
     */
    function getPastBalanceOf(
        address token,
        address account,
        uint256 timestamp
    ) external view returns (uint256);

    /**
     * @dev Returns the total supply available at a specific moment in the past.
     * @param token The address of the token
     * @param timestamp The timestamp of the past total supply
     * @return The total supply of `token` at `timestamp`
     */
    function getPastTotalSupply(
        address token,
        uint256 timestamp
    ) external view returns (uint256);
}

contracts/interfaces/ITransferRules.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity 0.8.28;
import "@openzeppelin/contracts/utils/introspection/IERC165.sol";
import "./IIdentityRegistry.sol";

interface ITransferRules {
    // ============================================
    // ORIGINAL TRANSFER RULES FUNCTIONALITY
    // ============================================

    /// @notice Detects if a transfer will be reverted and if so returns an appropriate reference code
    /// validates sufficient balance of each holdings and timelocks of sender to recipient 
    /// @param token address of the token
    /// @param from Sending address
    /// @param to Receiving address
    /// @param value Amount of tokens being transferred
    /// @return Code by which to reference message for rejection reasoning
    function detectTransferRestriction(
        address token,
        address from,
        address to,
        uint256 value
    ) external view returns (uint256);

    /// @notice Detects if a transfer will be reverted and if so returns an appropriate reference code
    /// @param token address of the token
    /// @param from Sending address
    /// @param to Receiving address
    /// @param value Amount of tokens being transferred
    /// @return Code by which to reference message for rejection reasoning
    function detectTransferRestrictionBasic(
        address token,
        address from,
        address to,
        uint256 value
    ) external view returns (uint256);

    /// @notice Returns a human-readable message for a given restriction code
    /// @param restrictionCode Identifier for looking up a message
    /// @return Text showing the restriction's reasoning
    function messageForTransferRestriction(
        uint256 restrictionCode
    ) external view returns (string memory);

    function checkSuccess(uint256 restrictionCode) external view returns (bool);

    // ============================================
    // TOKEN TYPE RULES ENGINE FUNCTIONALITY
    // ============================================

    /**
     * @dev Structure for efficient lockup table entries
     */
    struct TokenTypeRule {
        uint256 tokenType;           // Token type to assign
        bool requiresAmlKyc;         // Whether AML/KYC is required
        bool isActive;               // Whether this rule is active
    }

    /**
     * @dev Determine the token type for a wallet based on their identity
     * @param wallet The wallet address to check
     * @param identityRegistry The identity registry to query
     * @return tokenType The determined token type (TOKEN_TYPE_GENERIC if no match)
     */
    function determineTokenType(
        address wallet,
        IIdentityRegistry identityRegistry
    ) external view returns (uint256 tokenType);


    function tokenTypeAllowed(
        uint256 tokenType,
        address wallet,
        IIdentityRegistry identityRegistry
    ) external view returns (bool);

    /**
     * @dev Set a lockup rule directly in the efficient lockup table
     * @param region The region code (0 for any region)
     * @param accreditation The accreditation level (0 for any accreditation)
     * @param tokenType The token type to assign
     * @param requiresAmlKyc Whether AML/KYC is required
     * @param isActive Whether the rule is active
     */
    function setTokenTypeRule(
        uint256 region,
        uint256 accreditation,
        uint256 tokenType,
        bool requiresAmlKyc,
        bool isActive
    ) external;

    /**
     * @dev Remove a lockup rule from the table
     * @param region The region code
     * @param accreditation The accreditation level
     */
    function removeTokenTypeRule(
        uint256 region,
        uint256 accreditation
    ) external;

    /**
     * @dev Set the default token type rule
     * @param tokenType The token type to assign
     * @param requiresAmlKyc Whether AML/KYC is required
     * @param isActive Whether the rule is active
     */
    function setDefaultTokenTypeRule(
        uint256 tokenType,
        bool requiresAmlKyc,
        bool isActive
    ) external;

    /**
     * @dev Reset the default token type rule
     */
    function resetDefaultTokenTypeRule() external;

    /**
     * @dev Get the current default token type rule
     */
    function defaultTokenTypeRule() external view returns (TokenTypeRule memory);

    /**
     * @dev Get a lockup rule from the table
     * @param region The region code
     * @param accreditation The accreditation level
     * @return rule The lockup rule
     */
    function getTokenTypeRule(
        uint256 region,
        uint256 accreditation
    ) external view returns (TokenTypeRule memory rule);

    /**
     * @dev Batch set multiple lockup rules
     * @param regions Array of region codes
     * @param accreditations Array of accreditation levels
     * @param tokenTypes Array of token types
     * @param requiresAmlKycFlags Array of AML/KYC requirement flags
     * @param isActiveFlags Array of active flags
     */
    function batchSetTokenTypeRules(
        uint256[] calldata regions,
        uint256[] calldata accreditations,
        uint256[] calldata tokenTypes,
        bool[] calldata requiresAmlKycFlags,
        bool[] calldata isActiveFlags
    ) external;

    // ============================================
    // TOKEN TYPE TRANSFER RULES FUNCTIONALITY  
    // ============================================

    /**
     * @dev Structure to define transfer restrictions by token type and recipient identity
     */
    struct TransferRule {
        uint256 lockDurationSeconds;    // Holding period in seconds from mint timestamp
        bool requiresAmlKyc;            // Whether recipient must have AML/KYC
        bool isActive;                  // Whether this rule is currently active
    }

    /**
     * @dev Detects if a token holding can be transferred based on all applicable rules
     * @param tokenType The type of token being transferred
     * @param mintTimestamp When the tokens were originally minted
     * @param recipientIdentity The identity of the recipient
     * @param isAmlKycPassed Whether the recipient has passed AML/KYC
     * @return restrictionCode Error code if transfer is blocked (0 if allowed)
     */
    function detectTransferRestrictionForHolding(
        uint256 tokenType,
        uint256 mintTimestamp,
        IIdentityRegistry.IdentityInfo memory recipientIdentity,
        bool isAmlKycPassed
    ) external view returns (uint256 restrictionCode);

    /**
     * @dev Add or update a transfer rule
     * @param tokenType The token type this rule applies to (1=RegS, 2=RegD, etc.)
     * @param recipientRegion The required recipient region (0 = any region)
     * @param recipientAccreditation The required recipient accreditation (0 = any accreditation)
     * @param rule The transfer rule to add/update
     */
    function setTransferRule(
        uint256 tokenType,
        uint256 recipientRegion,
        uint256 recipientAccreditation,
        TransferRule memory rule
    ) external;

    /**
     * @dev Remove a transfer rule
     * @param tokenType The token type to remove the rule for
     * @param recipientRegion The region to remove the rule for
     * @param recipientAccreditation The accreditation to remove the rule for
     */
    function removeTransferRule(uint256 tokenType, uint256 recipientRegion, uint256 recipientAccreditation) external;

    /**
     * @dev Get the transfer rule for a specific token type, recipient region, and recipient accreditation
     * @param tokenType The token type to query rules for
     * @param recipientRegion The recipient region to query rules for
     * @param recipientAccreditation The recipient accreditation to query rules for
     * @return rule The transfer rule
     */
    function transferRuleFor(
        uint256 tokenType,
        uint256 recipientRegion,
        uint256 recipientAccreditation
    ) external view returns (TransferRule memory rule);

    /**
     * @dev Get the unlock timestamp for a specific token holding
     * @param tokenType The type of token
     * @param mintTimestamp When the tokens were minted
     * @param recipient The intended recipient
     * @param identityRegistry The identity registry to query
     * @return unlockTimestamp When the tokens can be transferred (0 if never)
     */
    function getUnlockTimestamp(
        uint256 tokenType,
        uint256 mintTimestamp,
        address recipient,
        IIdentityRegistry identityRegistry
    ) external view returns (uint256 unlockTimestamp);

    /**
     * @dev Batch create multiple rules
     * @param rules Array of transfer rules to create
     */
    function batchSetTransferRules(
        uint256[] calldata tokenType,
        uint256[] calldata recipientRegion,
        uint256[] calldata recipientAccreditation,
        TransferRule[] calldata rules
    ) external;

    // ============================================
    // EVENTS
    // ============================================

    // Token Type Rules Engine Events
    event TokenTypeRuleSet(
        uint256 indexed region,
        uint256 indexed accreditation,
        uint256 indexed tokenType,
        bool requiresAmlKyc,
        bool isActive
    );

    event DefaultTokenTypeRuleSet(
        uint256 indexed tokenType,
        bool requiresAmlKyc,
        bool isActive
    );

    event TokenTypeRuleRemoved(
        uint256 indexed region,
        uint256 indexed accreditation
    );

    // Transfer Rules Events
    event TransferRuleSet(
        uint256 indexed tokenType,
        uint256 recipientRegion,
        uint256 recipientAccreditation,
        uint256 lockDurationSeconds,
        bool requiresAmlKyc,
        bool isActive
    );

    event TransferRuleRemoved(uint256 indexed tokenType, uint256 indexed recipientRegion, uint256 indexed recipientAccreditation);
}

