// SPDX-License-Identifier: MIT

pragma solidity 0.8.28;

/**
 * @title BitManipulationLib
 * @notice Library for complex bit manipulation operations used in token storage optimization
 * @dev Extracted from Storage.sol to reduce contract size and improve modularity
 */
library BitManipulationLib {
    // ============================================
    // CONSTANTS
    // ============================================

    // Element packing constants (8-element packing)
    uint256 internal constant TOKEN_TYPE_BITS = 8;                // Token type uses 8 bits (supports 0-255)
    uint256 internal constant TOKEN_TYPE_MASK = (1 << TOKEN_TYPE_BITS) - 1; // 0xFF

    // ============================================
    // ELEMENT PACKING FUNCTIONS
    // ============================================

    /**
     * @dev Pack a single element (tokenType + daysAfterDeployment) into dynamic bits
     * @param tokenType The token type (0-255, uses 8 bits)
     * @param daysAfterDeployment The days after deployment (uses remaining bits)
     * @param elementBitSize The total bits per element
     * @return packed The packed element
     */
    function packElement(uint256 tokenType, uint256 daysAfterDeployment, uint256 elementBitSize) 
        internal 
        pure 
        returns (uint256 packed) 
    {
        require(tokenType <= TOKEN_TYPE_MASK, "TokenType exceeds 8-bit max");
        uint256 daysBitSize = elementBitSize - TOKEN_TYPE_BITS;
        uint256 daysMask = (1 << daysBitSize) - 1;
        require(daysAfterDeployment <= daysMask, "Days exceeds available bits");

        // Pack: [daysBitSize bits: daysAfterDeployment][8 bits: tokenType]
        packed = (daysAfterDeployment << TOKEN_TYPE_BITS) | tokenType;
    }

    /**
     * @dev Unpack a dynamic-bit element into tokenType and daysAfterDeployment
     * @param packed The packed element
     * @return tokenType The token type
     * @return daysAfterDeployment The days after deployment
     */
    function unpackElement(uint256 packed) 
        internal 
        pure 
        returns (uint256 tokenType, uint256 daysAfterDeployment) 
    {
        tokenType = packed & TOKEN_TYPE_MASK;                    // Extract lower 8 bits
        daysAfterDeployment = packed >> TOKEN_TYPE_BITS;         // Extract upper bits
    }

    /**
     * @dev Unpack tokenType from a packed 32-bit element
     * @param packedElement The packed 32-bit element
     * @return tokenType The token type (lower 8 bits)
     */
    function unpackTokenTypeElement(uint256 packedElement) 
        internal 
        pure 
        returns (uint256 tokenType) 
    {
        tokenType = packedElement & TOKEN_TYPE_MASK;
    }

    /**
     * @dev Get a single element from packed structure
     * @param packed The packed 256-bit value
     * @param subIndex The subIndex (0 to slotsPerWord-1)
     * @param elementBitSize The number of bits per element
     * @return element The element at the specified subIndex
     */
    function getPackedElement(uint256 packed, uint256 subIndex, uint256 elementBitSize) 
        internal 
        pure 
        returns (uint256 element) 
    {
        element = (packed >> (subIndex * elementBitSize)) & ((1 << elementBitSize) - 1);
    }

    // ============================================
    // BALANCE PACKING FUNCTIONS
    // ============================================

    /**
     * @dev Get a single balance from packed balances
     * @param packed The packed balances
     * @param subIndex The subIndex (0-7)
     * @return balance The balance at the specified subIndex
     */
    function getPackedBalance(uint256 packed, uint256 subIndex, uint256 elementBitSize) 
        internal 
        pure 
        returns (uint256 balance) 
    {
        balance = (packed >> (subIndex * elementBitSize)) & ((1 << elementBitSize) - 1);
    }

    /**
     * @dev Set a single balance in packed balances
     * @param packed The current packed balances
     * @param subIndex The subIndex (0-7)
     * @param newBalance The new balance to set
     * @return newPacked The updated packed balances
     */
    function setPackedBalance(uint256 packed, uint256 subIndex, uint256 newBalance, uint256 elementBitSize) 
        internal 
        pure 
        returns (uint256 newPacked) 
    {
        // Clear the old balance bits and set the new balance
        uint256 mask = ((1 << elementBitSize) - 1) << (subIndex * elementBitSize);
        newPacked = (packed & ~mask) | (newBalance << (subIndex * elementBitSize));
    }

    // ============================================
    // INDEX CALCULATION FUNCTIONS
    // ============================================

    /**
     * @dev Get the packed balance key (bucket index) from global index
     * @param globalIndex The global index
     * @return packedKey The bucket index for balance storage (maps 1:1 to globalMintTimestamps)
     */
    function getPackedBalanceKeyFromGlobalIndex(uint256 globalIndex, uint256 slotsPerWord) 
        internal 
        pure 
        returns (uint256 packedKey) 
    {
        // Calculate bucket index - each bucket in globalMintTimestamps contains 8 elements
        packedKey = globalIndex / slotsPerWord;
    }

    // ============================================
    // BITMAP MANIPULATION FUNCTIONS
    // ============================================

    /**
     * @dev Clear all bits that belong to a bucket and are in the current word
     * @param word_ The bitmap word to modify
     * @param globalIndex Any global index within the bucket (doesn't need to be aligned)
     * @param wordIndex_ The word index in the bitmap (0, 1, 2, ...)
     * @param slotsPerWord The number of slots per word (4-8)
     * @return The updated word with cleared bits
     * @notice Clears slotsPerWord consecutive bits starting from bucket start
     * @notice Only clears bits that are within the current word boundaries
     */
    function clearBucketBits(
        uint256 word_,
        uint256 globalIndex,
        uint256 wordIndex_,
        uint256 slotsPerWord
    ) internal pure returns (uint256) {
        uint256 bucketStartIndex = (globalIndex / slotsPerWord) * slotsPerWord;
        uint256 wordStartBit = wordIndex_ * 256;
        uint256 wordEndBit = wordStartBit + 256;

        // Calculate which bits of the bucket are in this word
        uint256 firstBitToClear = bucketStartIndex < wordStartBit ? 0 : bucketStartIndex - wordStartBit;
        uint256 lastBitToClear = bucketStartIndex + slotsPerWord > wordEndBit ? 255 : bucketStartIndex + slotsPerWord - wordStartBit - 1;

        // Create mask and clear bits in one operation
        if (firstBitToClear <= lastBitToClear && lastBitToClear < 256) {
            uint256 mask = ((1 << (lastBitToClear - firstBitToClear + 1)) - 1) << firstBitToClear;
            return word_ & ~mask;
        }

        return word_;
    }

    // ============================================
    // UTILITY FUNCTIONS
    // ============================================

    /**
     * @dev Calculate days after deployment from timestamps
     * @param mintTimestamp The mint timestamp to calculate from
     * @param deploymentDay_ The deployment timestamp to calculate relative to
     * @return daysAfterDeployment The number of days after deployment (midnight-aligned)
     */
    function calculateDaysAfterDeployment(
        uint256 mintTimestamp,
        uint256 deploymentDay_
    ) internal pure returns (uint256) {
        if (mintTimestamp < deploymentDay_) {
            return 0;
        }
        return (mintTimestamp - deploymentDay_) / 1 days;
    }

    /**
     * @dev Convert days since deploy back to absolute timestamp
     * @param daysSinceDeploy The days since deployment
     * @param deploymentDay_ The deployment day timestamp
     * @return timestamp The absolute timestamp
     */
    function daysSinceDeployToTimestamp(uint256 daysSinceDeploy, uint256 deploymentDay_) 
        internal 
        pure 
        returns (uint256 timestamp) 
    {
        timestamp = deploymentDay_ + (daysSinceDeploy * 1 days);
    }

    // ============================================
    // SLOT CALCULATION FUNCTIONS
    // ============================================

    /**
     * @dev Calculate the optimal number of slots per 256-bit word based on max total supply
     * @param maxTotalSupply The maximum total supply of the token (in basis units)
     * @return slotsPerWord The number of slots that fit in a 256-bit word (4-8)
     * @notice Decision is based on max total supply divided by 1000 to account for 
     *         worst case scenario of 1000 holdings with overflow value
     * @notice Uses powers of 2 for precise mathematical calculation
     */
    function calculateSlotsPerWord(uint256 maxTotalSupply) 
        internal 
        pure 
        returns (uint256 slotsPerWord) 
    {
        // Calculate the effective max value
        // Divide by 1000 to account for worst case scenario of 1000 holdings with overflow
        uint256 effectiveMaxValue = maxTotalSupply / 1000;

        // Determine optimal slot size based on effective max value using powers of 2
        if (effectiveMaxValue <= (2 ** 32)) {
            // 32 bits: fits 2^32 = 4,294,967,296
            // 8 slots in 256 bits (256/32 = 8)
            slotsPerWord = 8;
        } else if (effectiveMaxValue <= (2 ** 36)) {
            // 36 bits: fits 2^36 = 68,719,476,736
            // 7 slots in 256 bits (256/36 = 7.11, so 7 slots)
            slotsPerWord = 7;
        } else if (effectiveMaxValue <= (2 ** 42)) {
            // 42 bits: fits 2^42 = 4,398,046,511,104
            // 6 slots in 256 bits (256/42 = 6.09, so 6 slots)
            slotsPerWord = 6;
        } else if (effectiveMaxValue <= (2 ** 51)) {
            // 51 bits: fits 2^51 = 2,251,799,813,685,248
            // 5 slots in 256 bits (256/51 = 5.02, so 5 slots)
            slotsPerWord = 5;
        } else {
            // 64 bits: fits 2^64 = 18,446,744,073,709,551,616
            // 4 slots in 256 bits (256/64 = 4)
            slotsPerWord = 4;
        }

        return slotsPerWord;
    }

    /**
     * @dev Calculate the maximum balance value that can fit in each slot
     * @param slotsPerWord The number of slots per 256-bit word (4-8)
     * @return maxBalancePerSubIndex The maximum balance value per slot
     * @notice This calculates 2^(256/slotsPerWord) - 1 to get the maximum value per slot
     */
    function calculateMaxBalancePerSubIndex(uint256 slotsPerWord) 
        internal 
        pure 
        returns (uint256 maxBalancePerSubIndex) 
    {
        // Calculate the number of bits per slot
        uint256 bitsPerSlot = 256 / slotsPerWord;

        // Calculate 2^bitsPerSlot - 1 to get the maximum value per slot
        maxBalancePerSubIndex = (2 ** bitsPerSlot) - 1;
    }

    /**
     * @dev Calculate the number of bits needed to store an element (tokenType + daysAfterDeployment)
     * @param slotsPerWord The number of slots per 256-bit word (4-8)
     * @return elementBitSize The number of bits needed to store an element
     */
    function calculateElementBitSize(uint256 slotsPerWord) 
        internal 
        pure 
        returns (uint256 elementBitSize) 
    {
        elementBitSize = 256 / slotsPerWord;
    }

    /**
     * @dev Calculate the number of bits for days after deployment based on element size
     * @param elementBitSize The total bits per element
     * @return daysBitSize The number of bits for days (elementBitSize - 8 for tokenType)
     */
    function calculateDaysBitSize(uint256 elementBitSize) 
        internal 
        pure 
        returns (uint256 daysBitSize) 
    {
        require(elementBitSize > TOKEN_TYPE_BITS, "Element bit size too small for token type");
        daysBitSize = elementBitSize - TOKEN_TYPE_BITS;
    }
}

