// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/// @title VestingMath Library
/// @notice Contains pure helper functions that were previously embedded in RestrictedLockupToken.
///         Linking this library removes a few kilobytes from the main contract byte-code.
library VestingMath {
    uint256 internal constant BIPS_PRECISION = 10_000;

    /**
     * @notice Calculates how many tokens are unlocked for a vesting schedule at a given timestamp.
     * @param commencedTimestamp_  Timestamp when the schedule started.
     * @param currentTimestamp_    Timestamp to calculate the unlocked amount for.
     * @param amount_              Total tokens under the schedule.
     * @param releaseCount_        Total number of releases (including initial one).
     * @param delayUntilFirstReleaseInSeconds_  Cliff period in seconds before first release.
     * @param initialReleasePortionInBips_      Portion unlocked at the first release in BIPS (1/100th of a percent).
     * @param periodBetweenReleasesInSeconds_   Time between subsequent releases after the first.
     * @return unlocked            Amount of tokens that should be unlocked.
     */
    function calculateUnlocked(
        uint256 commencedTimestamp_,
        uint256 currentTimestamp_,
        uint256 amount_,
        uint256 releaseCount_,
        uint256 delayUntilFirstReleaseInSeconds_,
        uint256 initialReleasePortionInBips_,
        uint256 periodBetweenReleasesInSeconds_
    ) internal pure returns (uint256 unlocked) {
        // Nothing unlocked before commencement
        if (commencedTimestamp_ > currentTimestamp_) {
            return 0;
        }

        uint256 secondsElapsed = currentTimestamp_ - commencedTimestamp_;

        // All tokens unlocked if vesting fully complete
        if (
            secondsElapsed >=
            delayUntilFirstReleaseInSeconds_ +
                (periodBetweenReleasesInSeconds_ * (releaseCount_ - 1))
        ) {
            return amount_;
        }

        // Initial cliff release
        if (secondsElapsed >= delayUntilFirstReleaseInSeconds_) {
            unlocked = (amount_ * initialReleasePortionInBips_) / BIPS_PRECISION;

            // Subsequent periodic releases
            if (
                secondsElapsed - delayUntilFirstReleaseInSeconds_ >=
                periodBetweenReleasesInSeconds_
            ) {
                uint256 additionalPeriods = (secondsElapsed -
                    delayUntilFirstReleaseInSeconds_) /
                    periodBetweenReleasesInSeconds_;

                unlocked +=
                    ((amount_ - unlocked) * additionalPeriods) /
                    (releaseCount_ - 1);
            }
        }
    }

    /**
     * @notice Rounds a timestamp up to midnight UTC of the next day.
     */
    function toMidnightTimestamp(uint256 timestamp)
        internal
        pure
        returns (uint256)
    {
        return ((timestamp + 86399) / 86400) * 86400;
    }
}

